/**
 * Named concept figures — small inline SVGs rendered above concept-step bodies.
 * Design rules (DESIGN.md): ink/paper/sky/tangerine/leaf tokens only; borders over
 * shadows; the figure supports the text and never competes with the manipulable.
 * Every figure is decorative-plus-labelled: role="img" with a title for screen readers.
 */

const INK = "#22314F";
const SKY = "#2E7CD6";
const TANGERINE = "#FF8A3D";
const LEAF = "#2FA36B";
const BERRY = "#D6455D";

function Box({ x, y, w, label, fill }: { x: number; y: number; w: number; label: string; fill?: string }) {
  return (
    <g>
      <rect x={x} y={y} width={w} height={26} rx={8} fill={fill ?? "white"} stroke={INK} strokeWidth={1.5} />
      <text x={x + w / 2} y={y + 17} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>
        {label}
      </text>
    </g>
  );
}

/** The quadrilateral family tree: quadrilateral → parallelogram → rectangle/rhombus → square; trapezoid on its own branch. */
