/** Triangle side-families: scalene / isosceles / equilateral with tick marks. */
function TriangleFamilies() {
  const tri = (pts: string) => <polygon points={pts} fill="white" stroke={INK} strokeWidth={2} />;
  const tick = (x1: number, y1: number, x2: number, y2: number, color: string) => {
    const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
    const dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy);
    const nx = (-dy / len) * 5, ny = (dx / len) * 5;
    return <line x1={mx - nx} y1={my - ny} x2={mx + nx} y2={my + ny} stroke={color} strokeWidth={2.5} />;
  };
  return (
    <svg viewBox="0 0 340 120" role="img" className="mx-auto w-full max-w-sm">
      <title>Triangle side families: scalene has no equal sides, isosceles has two marked equal sides, equilateral has all three marked equal.</title>
      {/* scalene */}
      {tri("14,86 104,86 44,26")}
      <text x={58} y={106} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>scalene</text>
      {/* isosceles: apex centered so the two slanted sides are equal */}
      {tri("128,86 208,86 168,24")}
      {tick(128, 86, 168, 24, SKY)}
      {tick(208, 86, 168, 24, SKY)}
      <text x={168} y={106} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>isosceles</text>
      {/* equilateral: 70px sides */}
      {tri("238,86 308,86 273,25.4")}
      {tick(238, 86, 308, 86, LEAF)}
      {tick(238, 86, 273, 25.4, LEAF)}
      {tick(308, 86, 273, 25.4, LEAF)}
      <text x={273} y={106} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>equilateral</text>
    </svg>
  );
}

/** A box built from unit-cube layers: a 3×2 base layer repeated 3 high (isometric-ish, flat per DESIGN). */
function BoxLayers() {
  const w = 26, d = 12, h = 20; // cube face metrics
  const cube = (cx: number, cy: number, accent = false) => (
    <g stroke={INK} strokeWidth={1.25}>
      <polygon points={`${cx},${cy} ${cx + w},${cy} ${cx + w + d},${cy - d} ${cx + d},${cy - d}`} fill={accent ? "#FFE3CC" : "#F0F3F7"} />
      <polygon points={`${cx},${cy} ${cx + w},${cy} ${cx + w},${cy + h} ${cx},${cy + h}`} fill={accent ? "#FFD1AB" : "white"} />
      <polygon points={`${cx + w},${cy} ${cx + w + d},${cy - d} ${cx + w + d},${cy - d + h} ${cx + w},${cy + h}`} fill={accent ? "#F5B076" : "#DCE4EE"} />
    </g>
  );
  const layer = (baseY: number, accent = false) => {
    const cells: JSX.Element[] = [];
    for (let row = 1; row >= 0; row--) {
      for (let col = 0; col < 3; col++) {
        cells.push(<g key={`${baseY}-${row}-${col}`}>{cube(30 + col * w + row * d, baseY - row * d, accent)}</g>);
      }
    }
    return cells;
  };
  return (
    <svg viewBox="0 0 300 170" role="img" className="mx-auto w-full max-w-xs">
      <title>A box built from unit cubes: a base layer of 3 by 2 cubes, stacked 4 layers high; the highlighted bottom layer shows the base.</title>
      {layer(136 - 3 * h)}
      {layer(136 - 2 * h)}
      {layer(136 - h)}
      {layer(136, true)}
      <text x={158} y={158} fontSize={10} fontWeight={700} fill={TANGERINE}>base layer: 3 × 2</text>
      <text x={158} y={26} fontSize={10} fontWeight={700} fill={INK} opacity={0.75}>4 layers tall</text>
    </svg>
  );
}


/** A single unit cube: 1 unit on every edge, filling 1 cubic unit. */
function UnitCube() {
  const w = 44, d = 20, h = 36, cx = 78, cy = 60;
  return (
    <svg viewBox="0 0 220 130" role="img" className="mx-auto w-full max-w-xs">
      <title>A single unit cube: each edge is 1 unit long, and it fills exactly 1 cubic unit of space.</title>
      <g stroke={INK} strokeWidth={1.5}>
        <polygon points={`${cx},${cy} ${cx + w},${cy} ${cx + w + d},${cy - d} ${cx + d},${cy - d}`} fill="#F0F3F7" />
        <polygon points={`${cx},${cy} ${cx + w},${cy} ${cx + w},${cy + h} ${cx},${cy + h}`} fill="white" />
        <polygon points={`${cx + w},${cy} ${cx + w + d},${cy - d} ${cx + w + d},${cy - d + h} ${cx + w},${cy + h}`} fill="#DCE4EE" />
      </g>
      <text x={cx + w / 2} y={cy + h + 16} textAnchor="middle" fontSize={10} fontWeight={700} fill={SKY}>1 unit</text>
      <text x={cx - 8} y={cy + h / 2} textAnchor="end" fontSize={10} fontWeight={700} fill={SKY}>1 unit</text>
      <text x={cx + w + d + 6} y={cy - d / 2} fontSize={10} fontWeight={700} fill={SKY}>1 unit</text>
      <text x={cx + w / 2 + d / 2} y={cy + h + 34} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>
        = 1 cubic unit
      </text>
    </svg>
  );
}

/** The ch5 L-solid with BOTH cuts shown: horizontal 20+8, vertical 16+12 — both give 28. */
function LSolidCuts() {
  const u = 22, ox = 40, oy = 116; // unit px, origin (bottom-left of the L), side view x:0..5, z:0..4
  const X = (x: number) => ox + x * u;
  const Z = (z: number) => oy - z * u;
  return (
    <svg viewBox="0 0 320 150" role="img" className="mx-auto w-full max-w-sm">
      <title>An L-shaped solid cut two ways: a horizontal cut gives pieces of 20 and 8 cubic units; a vertical cut gives 16 and 12. Both totals are 28.</title>
      <polygon
        points={`${X(0)},${Z(0)} ${X(5)},${Z(0)} ${X(5)},${Z(2)} ${X(2)},${Z(2)} ${X(2)},${Z(4)} ${X(0)},${Z(4)}`}
        fill="#F0F3F7"
        stroke={INK}
        strokeWidth={2}
      />
      <line x1={X(0)} y1={Z(2)} x2={X(5)} y2={Z(2)} stroke={TANGERINE} strokeWidth={2.5} strokeDasharray="5 4" />
      <line x1={X(2)} y1={Z(0)} x2={X(2)} y2={Z(4)} stroke={LEAF} strokeWidth={2.5} strokeDasharray="5 4" />
      <text x={X(5) + 8} y={Z(2) + 4} fontSize={10} fontWeight={700} fill={TANGERINE}>cut A: 20 + 8</text>
      <text x={X(2) + 5} y={Z(4) - 6} fontSize={10} fontWeight={700} fill={LEAF}>cut B: 16 + 12</text>
      <text x={X(2.5)} y={Z(0) + 20} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>
        either cut: 28 cubic units
      </text>
    </svg>
  );
}

/** The fm-03-01 area model, exactly its example: 1/2 × 1/3 on a 2-column, 3-row square — overlap 1 of 6. */

/** Grade 3 fractions — shared bar helper: a whole split into `parts`, first `shaded` filled. */
function FractionBar({ parts, shaded, y, color, x0 = 16, w = 178, h = 24 }: { parts: number; shaded: number; y: number; color: string; x0?: number; w?: number; h?: number }) {
  const pw = w / parts;
  return (
    <g>
      {Array.from({ length: parts }, (_, i) => (
        <rect key={i} x={x0 + i * pw} y={y} width={pw} height={h} fill={i < shaded ? color : "#ffffff"} stroke={INK} strokeWidth={1.3} />
      ))}
    </g>
  );
}

/** Grade 3 fractions — shared number line 0..maxWhole split into `parts` per whole, tick at numerator/parts. */
function FractionNumLine({ maxWhole, parts, mark, label, y = 60 }: { maxWhole: number; parts: number; mark: number; label: string; y?: number }) {
  const x0 = 20, x1 = 200;
  const total = maxWhole * parts;
  const px = (n: number) => x0 + (n / total) * (x1 - x0);
  const markX = px(mark);
  return (
    <g>
      <line x1={x0} y1={y} x2={x1} y2={y} stroke={INK} strokeWidth={2} />
      {Array.from({ length: total + 1 }, (_, i) => {
        const isWhole = i % parts === 0;
        return <line key={i} x1={px(i)} y1={y - (isWhole ? 9 : 5)} x2={px(i)} y2={y + (isWhole ? 9 : 5)} stroke={INK} strokeWidth={isWhole ? 2 : 1} />;
      })}
      {Array.from({ length: maxWhole + 1 }, (_, i) => (
        <text key={i} x={px(i * parts)} y={y + 22} fontSize="11" fill={INK} textAnchor="middle">{i}</text>
      ))}
      <circle cx={markX} cy={y} r={5} fill={BERRY} />
      <text x={markX} y={y - 14} fontSize="12" fontWeight="700" fill={BERRY} textAnchor="middle">{label}</text>
    </g>
  );
}

