/** Grade 3 place value — schematic base-ten blocks: flats (hundreds), rods (tens), units (ones). */
function Pv3Blocks({ hundreds, tens, ones, y0 = 20 }: { hundreds: number; tens: number; ones: number; y0?: number }) {
  const flats = Array.from({ length: hundreds }, (_, i) => i);
  const rods = Array.from({ length: tens }, (_, i) => i);
  const units = Array.from({ length: ones }, (_, i) => i);
  return (
    <g>
      {flats.map((i) => (
        <rect key={`f${i}`} x={16 + i * 34} y={y0} width={28} height={28} fill={SKY} fillOpacity={0.3} stroke={INK} strokeWidth={1.4} />
      ))}
      {rods.map((i) => (
        <rect key={`r${i}`} x={16 + i * 10} y={y0 + 36} width={7} height={28} fill={LEAF} fillOpacity={0.45} stroke={INK} strokeWidth={1.1} />
      ))}
      {units.map((i) => (
        <rect key={`u${i}`} x={16 + i * 11} y={y0 + 72} width={8} height={8} fill={TANGERINE} fillOpacity={0.6} stroke={INK} strokeWidth={1} />
      ))}
    </g>
  );
}

/** Grade 3 place value — general number line lo..hi by step, with a point and an optional rounding target. */
function Pv3NumLine({ lo, hi, step, mark, markLabel, target, targetLabel, y = 56 }: { lo: number; hi: number; step: number; mark: number; markLabel: string; target?: number; targetLabel?: string; y?: number }) {
  const x0 = 24, x1 = 200;
  const px = (n: number) => x0 + ((n - lo) / (hi - lo)) * (x1 - x0);
  const ticks: number[] = [];
  for (let v = lo; v <= hi + 1e-9; v += step) ticks.push(Math.round(v));
  return (
    <g>
      <line x1={x0} y1={y} x2={x1} y2={y} stroke={INK} strokeWidth={2} />
      {ticks.map((v) => (
        <g key={v}>
          <line x1={px(v)} y1={y - 7} x2={px(v)} y2={y + 7} stroke={INK} strokeWidth={1.6} />
          <text x={px(v)} y={y + 20} fontSize="11" fill={INK} textAnchor="middle">{v}</text>
        </g>
      ))}
      {target !== undefined && (
        <g>
          <circle cx={px(target)} cy={y} r={6} fill={LEAF} />
          {/* S238 wave 13: x clamped so an edge target's label stays on-canvas; the mark
              label moved below the line, out of this label's band. */}
          {targetLabel && <text x={Math.max(x0 + targetLabel.length * 4, Math.min(px(target), x1 - targetLabel.length * 4))} y={y - 24} fontSize="11" fontWeight="700" fill={LEAF} textAnchor="middle">{targetLabel}</text>}
        </g>
      )}
      <circle cx={px(mark)} cy={y} r={5} fill={BERRY} />
      <text x={px(mark)} y={y + 36} fontSize="12" fontWeight="700" fill={BERRY} textAnchor="middle">{markLabel}</text>
    </g>
  );
}

/** Grade 3 place value figure: 342 as hundreds, tens, and ones. */

/** Grade 3 measurement — a rows×cols grid of unit squares for area. */
function AreaGrid({ rows, cols, x0 = 60, y0 = 22, cell = 16, fill = SKY }: { rows: number; cols: number; x0?: number; y0?: number; cell?: number; fill?: string }) {
  const cells = [];
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) cells.push({ r, c });
  return (
    <g>
      {cells.map(({ r, c }) => (
        <rect key={`${r}-${c}`} x={x0 + c * cell} y={y0 + r * cell} width={cell} height={cell} fill={fill} fillOpacity={0.28} stroke={INK} strokeWidth={1} />
      ))}
    </g>
  );
}

/** Grade 3 measurement — a simple clock face with hour + minute hands at given clock positions (0-60 minute units). */
function ClockAt({ hourAngleMin, minute, label }: { hourAngleMin: number; minute: number; label: string }) {
  const cx = 56, cy = 54, r = 40;
  const ha = (hourAngleMin / 60) * 2 * Math.PI - Math.PI / 2;
  const ma = (minute / 60) * 2 * Math.PI - Math.PI / 2;
  return (
    <g>
      <circle cx={cx} cy={cy} r={r} fill="#ffffff" stroke={INK} strokeWidth={2} />
      {Array.from({ length: 12 }, (_, i) => {
        const a = (i / 12) * 2 * Math.PI - Math.PI / 2;
        return <line key={i} x1={cx + (r - 4) * Math.cos(a)} y1={cy + (r - 4) * Math.sin(a)} x2={cx + r * Math.cos(a)} y2={cy + r * Math.sin(a)} stroke={INK} strokeWidth={1.2} />;
      })}
      <line x1={cx} y1={cy} x2={cx + 22 * Math.cos(ha)} y2={cy + 22 * Math.sin(ha)} stroke={BERRY} strokeWidth={3} />
      <line x1={cx} y1={cy} x2={cx + 34 * Math.cos(ma)} y2={cy + 34 * Math.sin(ma)} stroke={SKY} strokeWidth={2} />
      <circle cx={cx} cy={cy} r={2.5} fill={INK} />
      <text x={cx} y={106} fontSize="12" fontWeight="700" fill={INK} textAnchor="middle">{label}</text>
    </g>
  );
}

/** Grade 3 measurement figure: Two hands, two jobs: hour and minute. */

/** Grade 3 multiplication — g equal groups of n dots each. */
function EqualGroups({ groups, per, fill = SKY }: { groups: number; per: number; fill?: string }) {
  const gEls = [];
  for (let g = 0; g < groups; g++) {
    const dots = [];
    for (let i = 0; i < per; i++) {
      const col = i % 3, row = Math.floor(i / 3);
      dots.push(<circle key={i} cx={g * 62 + 24 + col * 13} cy={34 + row * 13} r={5} fill={fill} fillOpacity={0.7} stroke={INK} strokeWidth={0.8} />);
    }
    gEls.push(
      <g key={g}>
        <rect x={g * 62 + 14} y={20} width={44} height={Math.ceil(per / 3) * 13 + 8} rx={5} fill="none" stroke={INK} strokeWidth={1.3} strokeDasharray="3 2" />
        {dots}
      </g>
    );
  }
  return <g>{gEls}</g>;
}

/** Grade 3 mult/div figure: Equal groups: 3 groups of 4 = 12. */
/** Grade 5 decimal/operations figure: Order matters: 2 + 3 × 4 = 14, not 20. */
/** Grade 4 fractions-add figure: Two thirds equals four sixths. */

/** Grade 5 fraction multiply — an a-by-b grid where the overlap of shadeCols and shadeRows shows a fraction × fraction product. */
function FracAreaGrid({ cols, rows, shadeCols, shadeRows, x0 = 70, y0 = 22, cell = 15 }: { cols: number; rows: number; shadeCols: number; shadeRows: number; x0?: number; y0?: number; cell?: number }) {
  const cells = [];
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const both = c < shadeCols && r < shadeRows;
    const one = c < shadeCols || r < shadeRows;
    cells.push(<rect key={`${r}-${c}`} x={x0 + c * cell} y={y0 + r * cell} width={cell} height={cell} fill={both ? BERRY : one ? SKY : "#ffffff"} fillOpacity={both ? 0.7 : one ? 0.22 : 1} stroke={INK} strokeWidth={0.7} />);
  }
  return <g>{cells}</g>;
}

