/** fa-01-01's opening image: the same bar cut two ways — 1/2 shaded above, 2/4 shaded below, same amount. */
function EquivalentBars() {
  const ox = 46, w = 210, h = 24;
  const bar = (y: number, cuts: number, shaded: number) => (
    <g>
      <rect x={ox} y={y} width={(w / cuts) * shaded} height={h} fill={TANGERINE} opacity={0.4} />
      <rect x={ox} y={y} width={w} height={h} fill="none" stroke={INK} strokeWidth={2} />
      {Array.from({ length: cuts - 1 }, (_, i) => (
        <line key={i} x1={ox + (i + 1) * (w / cuts)} y1={y} x2={ox + (i + 1) * (w / cuts)} y2={y + h} stroke={INK} strokeWidth={1.25} opacity={0.6} />
      ))}
    </g>
  );
  return (
    <svg viewBox="0 0 320 122" role="img" className="mx-auto w-full max-w-sm">
      <title>The same bar cut two ways: cut into halves with one half shaded, and cut into fourths with two fourths shaded — the shaded amounts line up exactly.</title>
      {bar(18, 2, 1)}
      <text x={ox - 8} y={34} textAnchor="end" fontSize={11} fontWeight={800} fill={INK}>1/2</text>
      {bar(64, 4, 2)}
      <text x={ox - 8} y={80} textAnchor="end" fontSize={11} fontWeight={800} fill={INK}>2/4</text>
      <line x1={ox + w / 2} y1={14} x2={ox + w / 2} y2={92} stroke={LEAF} strokeWidth={2} strokeDasharray="4 3" />
      <text x={ox + w / 2 + 6} y={106} fontSize={11} fontWeight={800} fill={LEAF}>
        same shaded amount
      </text>
    </svg>
  );
}

/** mc-05-02's exact plot: five pencils (1/2, 3/4, 1/2, 5/8, 1/2) as stacked X marks above an eighths line. */
function LinePlot() {
  const ox = 40, oy = 84, u = 240; // line spans 3/8 .. 7/8 of an inch mapped across u px
  const X = (f: number) => ox + (f - 3 / 8) * (u / (4 / 8));
  const ticks = [3, 4, 5, 6, 7].map((e) => e / 8);
  const labels: Record<string, string> = { "0.375": "3/8", "0.5": "1/2", "0.625": "5/8", "0.75": "3/4", "0.875": "7/8" };
  const marks: Array<[number, number]> = [
    [1 / 2, 3],
    [5 / 8, 1],
    [3 / 4, 1]
  ];
  return (
    <svg viewBox="0 0 320 126" role="img" className="mx-auto w-full max-w-sm">
      <title>A line plot of five pencil lengths in eighths of an inch: three X marks stacked above one half, one above five eighths, one above three fourths.</title>
      <line x1={ox - 10} y1={oy} x2={ox + u + 14} y2={oy} stroke={INK} strokeWidth={2} />
      {ticks.map((f) => (
        <g key={f}>
          <line x1={X(f)} y1={oy - 4} x2={X(f)} y2={oy + 4} stroke={INK} strokeWidth={1.5} />
          <text x={X(f)} y={oy + 18} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>
            {labels[String(f)]}
          </text>
        </g>
      ))}
      {marks.flatMap(([f, n]) =>
        Array.from({ length: n }, (_, i) => (
          <text key={`${f}-${i}`} x={X(f)} y={oy - 10 - i * 19} textAnchor="middle" fontSize={14} fontWeight={800} fill={SKY}>
            ✕
          </text>
        ))
      )}
      <text x={X(1 / 2)} y={14} textAnchor="middle" fontSize={10} fontWeight={700} fill={TANGERINE}>
        1/2 came up 3 times
      </text>
      <text x={ox + u / 2} y={oy + 34} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.7}>
        one ✕ per pencil: 1/2, 3/4, 1/2, 5/8, 1/2
      </text>
    </svg>
  );
}


