/** Schematic (no fixed numbers, reusable): narrowing an unknown value between two consecutive
 *  whole numbers, then zooming in to narrow it again by tenths — the core Ch3 technique. */
function NumberLineBetweenIntegers() {
  return (
    <svg viewBox="0 0 300 190" role="img" className="mx-auto w-full max-w-sm">
      <title>A number line showing an unknown value between two consecutive whole numbers n and n+1; a zoomed-in strip below shows the same interval split into tenths, narrowing down closer to exactly where the value sits.</title>
      <NumberLineAxis x1={20} x2={280} y={40} color={INK} testId="between-integers-overview-axis" />
      <line x1={90} y1={32} x2={90} y2={48} stroke={INK} strokeWidth={2.5} />
      <text x={90} y={22} textAnchor="middle" fontSize={12} fontWeight={800} fill={INK}>n</text>
      <line x1={210} y1={32} x2={210} y2={48} stroke={INK} strokeWidth={2.5} />
      <text x={214} y={22} textAnchor="middle" fontSize={12} fontWeight={800} fill={INK}>n + 1</text>
      <circle cx={150} cy={40} r={5} fill={BERRY} />
      <text x={150} y={62} textAnchor="middle" fontSize={11} fontWeight={700} fill={BERRY}>?</text>
      <path d="M90 48 L60 90 M210 48 L240 90" stroke={INK} strokeWidth={1} strokeDasharray="3 3" opacity={0.5} fill="none" />
      <rect x={45} y={90} width={210} height={62} rx={8} fill="#F7F4EE" stroke={INK} strokeWidth={1.4} />
      <NumberLineAxis x1={60} x2={240} y={132} color={INK} strokeWidth={1.6} testId="between-integers-zoom-axis" />
      {Array.from({ length: 11 }, (_, i) => {
        const x = 60 + i * 18;
        return <line key={i} x1={x} y1={127} x2={x} y2={137} stroke={INK} strokeWidth={i % 10 === 0 ? 2 : 1} />;
      })}
      <text x={60} y={150} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>n.0</text>
      <text x={240} y={150} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>n+1</text>
      <circle cx={150} cy={132} r={5} fill={BERRY} />
      <text x={150} y={118} textAnchor="middle" fontSize={10} fontWeight={700} fill={BERRY}>closer now</text>
      <text x={150} y={178} textAnchor="middle" fontSize={11} fontWeight={700} fill={SKY}>zoom in → narrow one decimal place at a time</text>
    </svg>
  );
}

/** The full power-of-ten ladder, thousands down through thousandths, with the decimal
 *  point anchored between the ones and tenths rungs — bridges positive and negative exponents. */
function PowerOfTenLadder() {
  const rungs = [
    ["thousands", "10³"], ["hundreds", "10²"], ["tens", "10¹"], ["ones", "10⁰"],
    ["tenths", "10⁻¹"], ["hundredths", "10⁻²"], ["thousandths", "10⁻³"],
  ];
  const x = 60, w = 150, rh = 22, oy = 10, gap = 2;
  return (
    <svg viewBox="0 0 300 200" role="img" className="mx-auto w-full max-w-xs">
      <title>The power-of-ten ladder from thousands down to thousandths: thousands is ten cubed, ones is ten to the zero, and tenths, hundredths, and thousandths are ten to the negative one, two, and three — the decimal point sits between ones and tenths.</title>
      {rungs.map(([label, pow], i) => (
        <g key={label}>
          <rect x={x} y={oy + i * (rh + gap)} width={w} height={rh} rx={6}
                fill={i === 3 ? "#EAF2FC" : "white"} stroke={INK} strokeWidth={1.25} />
          <text x={x + 10} y={oy + i * (rh + gap) + 15} fontSize={10.5} fontWeight={700} fill={INK}>{label}</text>
          <text x={x + w - 14} y={oy + i * (rh + gap) + 15} textAnchor="end" fontSize={11} fontWeight={800} fill={SKY}>{pow}</text>
        </g>
      ))}
      <line x1={x - 10} y1={oy + 3 * (rh + gap) + rh + gap / 2} x2={x + w + 10} y2={oy + 3 * (rh + gap) + rh + gap / 2}
            stroke={BERRY} strokeWidth={2.5} />
      <text x={x + w + 16} y={oy + 3 * (rh + gap) + rh + gap / 2 + 4} fontSize={11} fontWeight={800} fill={BERRY}>.</text>
      <text x={x - 16} y={oy + 3 * (rh + gap) + rh + gap / 2 - 6} textAnchor="end" fontSize={10} fontWeight={700} fill={BERRY}>decimal</text>
      <text x={x - 16} y={oy + 3 * (rh + gap) + rh + gap / 2 + 10} textAnchor="end" fontSize={10} fontWeight={700} fill={BERRY}>point</text>
    </svg>
  );
}

/** Why x^2=16 has two solutions (+4 and -4 both square to 16) but x^3=8 has only one
 *  (only +2 cubes to 8 -- a negative cubed stays negative, so it can't reach a positive target). */
function SquareVsCubeSolutions() {
  return (
    <svg viewBox="0 0 300 184" role="img" className="mx-auto w-full max-w-sm">
      <title>Solving x squared equals 16 gives two solutions, positive 4 and negative 4, since both square to 16. Solving x cubed equals 8 gives only one solution, positive 2, since a negative number cubed stays negative and can never reach a positive 8.</title>
      <text x={72} y={16} textAnchor="middle" fontSize={12} fontWeight={800} fill={INK}>x² = 16</text>
      <circle cx={72} cy={44} r={18} fill="#EAF3FB" stroke={SKY} strokeWidth={2} />
      <text x={72} y={49} textAnchor="middle" fontSize={12} fontWeight={800} fill={SKY}>16</text>
      <circle cx={30} cy={100} r={16} fill="#FCE9EC" stroke={BERRY} strokeWidth={2} />
      <text x={30} y={105} textAnchor="middle" fontSize={11} fontWeight={800} fill={BERRY}>+4</text>
      <circle cx={114} cy={100} r={16} fill="#FCE9EC" stroke={BERRY} strokeWidth={2} />
      <text x={114} y={105} textAnchor="middle" fontSize={11} fontWeight={800} fill={BERRY}>−4</text>
      <path d="M38 88 L62 56" stroke={INK} strokeWidth={1.6} markerEnd="url(#svcArrow)" fill="none" />
      <path d="M106 88 L82 56" stroke={INK} strokeWidth={1.6} markerEnd="url(#svcArrow)" fill="none" />
      <text x={150} y={130} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>both square to 16 — TWO solutions</text>
      <defs>
        <marker id="svcArrow" markerWidth="7" markerHeight="7" refX="5" refY="3.5" orient="auto">
          <polygon points="0 0, 7 3.5, 0 7" fill={INK} />
        </marker>
      </defs>
      <line x1={160} y1={0} x2={160} y2={150} stroke={INK} strokeWidth={1} opacity={0.25} />
      <text x={228} y={16} textAnchor="middle" fontSize={12} fontWeight={800} fill={INK}>x³ = 8</text>
      <circle cx={228} cy={44} r={18} fill="#EAF3FB" stroke={SKY} strokeWidth={2} />
      <text x={228} y={49} textAnchor="middle" fontSize={12} fontWeight={800} fill={SKY}>8</text>
      <circle cx={228} cy={100} r={16} fill="#FCE9EC" stroke={BERRY} strokeWidth={2} />
      <text x={228} y={105} textAnchor="middle" fontSize={11} fontWeight={800} fill={BERRY}>+2</text>
      <path d="M228 88 L228 56" stroke={INK} strokeWidth={1.6} markerEnd="url(#svcArrow)" fill="none" />
      <text x={150} y={144} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>−2 cubes to −8, not 8 — ONE solution</text>
    </svg>
  );
}

/** A log-scale magnitude line from atoms to the sun, motivating why scientific
 *  notation exists: real quantities span an enormous range of powers of ten. */
function MagnitudeScale() {
  const points = [
    ["atom", "10⁻¹⁰ m", 20],
    ["hair width", "10⁻⁵ m", 76],
    ["your height", "10⁰ m", 132],
    ["Everest", "10⁴ m", 188],
    ["Earth", "10⁷ m", 244],
    ["to the Sun", "10¹¹ m", 280],
  ];
  return (
    <svg viewBox="0 0 300 150" role="img" className="mx-auto w-full max-w-sm">
      <title>A magnitude scale from an atom at ten to the negative ten meters, through hair width, human height, Mount Everest, and Earth's size, up to the distance to the Sun at ten to the eleven meters — showing the enormous range scientific notation is built to handle.</title>
      <line x1={16} y1={70} x2={288} y2={70} stroke={INK} strokeWidth={2} />
      <polygon points="288,70 278,65 278,75" fill={INK} />
      {points.map(([label, pow, x], i) => (
        <g key={label}>
          <line x1={x} y1={64} x2={x} y2={76} stroke={SKY} strokeWidth={2.5} />
          <circle cx={x} cy={70} r={4} fill={i % 2 === 0 ? TANGERINE : BERRY} />
          <text x={i === 5 ? 298 : x} y={i % 2 === 0 ? 54 : 100} textAnchor={i === 5 ? "end" : "middle"} fontSize={10} fontWeight={700} fill={INK}>{label}</text>
          <text x={i === 5 ? 298 : x} y={i % 2 === 0 ? 40 : 114} textAnchor={i === 5 ? "end" : "middle"} fontSize={10} fontWeight={800} fill={SKY}>{pow}</text>
        </g>
      ))}
      <text x={150} y={140} textAnchor="middle" fontSize={11} fontWeight={700} fill={LEAF}>21 orders of magnitude — atom to Sun</text>
    </svg>
  );
}

/** Why a function needs exactly one output per input: a valid mapping (each input arrow
 *  lands on one output) beside an invalid one (input 1 fans out to two outputs). */
function FunctionVsNot() {
  const css = `@media (prefers-reduced-motion: no-preference){.fvn-bad{animation:fvn-flash 1.6s ease-in-out infinite}@keyframes fvn-flash{0%,100%{opacity:1}50%{opacity:.4}}}`;
  const col = (cx: number, vals: (string | number)[], fill: string) =>
    vals.map((v, i) => (
      <g key={`${cx}-${i}`}>
        <circle cx={cx} cy={40 + i * 34} r={13} fill={fill} stroke={INK} strokeWidth={1.3} />
        <text x={cx} y={45 + i * 34} textAnchor="middle" fontSize={12} fontWeight={700} fill={INK}>{v}</text>
      </g>
    ));
  return (
    <svg viewBox="0 0 300 180" role="img" className="mx-auto w-full max-w-sm">
      <title>A valid function on the left: inputs 1, 2, 3 each send one arrow to a single output, so it is a function. An invalid relation on the right: input 1 sends two arrows to two different outputs, so it is not a function.</title>
      <style>{css}</style>
      <text x={68} y={20} textAnchor="middle" fontSize={11} fontWeight={800} fill={LEAF}>function ✓</text>
      {col(40, [1, 2, 3], "#DCEBFB")}
      {col(96, [4, 5, 6], "#D8F0E4")}
      {[0, 1, 2].map((i) => (
        <line key={i} x1={53} y1={40 + i * 34} x2={83} y2={40 + i * 34} stroke={INK} strokeWidth={1.6} markerEnd="url(#fvnArrow)" />
      ))}
      <line x1={150} y1={10} x2={150} y2={170} stroke={INK} strokeWidth={1} opacity={0.25} />
      <text x={232} y={20} textAnchor="middle" fontSize={11} fontWeight={800} fill={BERRY}>not a function ✗</text>
      {col(204, [1, 2], "#FCE0D2")}
      {col(260, [4, 5, 6], "#FBE0E5")}
      <line x1={217} y1={40} x2={247} y2={40} stroke={BERRY} strokeWidth={1.8} markerEnd="url(#fvnArrowBad)" className="fvn-bad" />
      <line x1={217} y1={40} x2={247} y2={74} stroke={BERRY} strokeWidth={1.8} markerEnd="url(#fvnArrowBad)" className="fvn-bad" />
      <line x1={217} y1={74} x2={247} y2={108} stroke={INK} strokeWidth={1.6} markerEnd="url(#fvnArrow)" />
      <text x={204} y={130} textAnchor="middle" fontSize={10} fontWeight={700} fill={BERRY}>1 → two outputs!</text>
      <defs>
        <marker id="fvnArrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><polygon points="0 0, 7 3.5, 0 7" fill={INK} /></marker>
        <marker id="fvnArrowBad" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><polygon points="0 0, 7 3.5, 0 7" fill={BERRY} /></marker>
      </defs>
    </svg>
  );
}

/** Two nested similar triangles on the same line: both give the same rise÷run, which is
 *  why a straight line has ONE constant slope everywhere (the 8.EE.6 similar-triangles idea). */
function SimilarTrianglesSlope() {
  const ox = 30, oy = 148, u = 34;
  const X = (n: number) => ox + n * u;
  const Y = (n: number) => oy - n * u;
  // line y = (2/3) x through origin (schematic), small triangle run 3 rise 2, big triangle run 6 rise 4... use integers: slope 1, small run1 rise1, big run3 rise3
  return (
    <svg viewBox="0 0 300 180" role="img" className="mx-auto w-full max-w-sm">
      <title>Two right triangles of different sizes sit under the same straight line. The small triangle has rise 1 over run 1 and the big triangle has rise 3 over run 3 — both give the same ratio, which is why a straight line has one constant slope everywhere.</title>
      <line x1={ox} y1={oy} x2={ox} y2={20} stroke={INK} strokeWidth={1.4} opacity={0.5} />
      <line x1={ox} y1={oy} x2={280} y2={oy} stroke={INK} strokeWidth={1.4} opacity={0.5} />
      <line x1={X(0)} y1={Y(0)} x2={X(3.4)} y2={Y(3.4)} stroke={SKY} strokeWidth={2.5} />
      {/* small triangle: run 1, rise 1 */}
      <line x1={X(0)} y1={Y(0)} x2={X(1)} y2={Y(0)} stroke={TANGERINE} strokeWidth={2.5} />
      <line x1={X(1)} y1={Y(0)} x2={X(1)} y2={Y(1)} stroke={TANGERINE} strokeWidth={2.5} />
      <text x={X(0.5)} y={oy + 15} textAnchor="middle" fontSize={10} fontWeight={700} fill={TANGERINE}>run 1</text>
      <text x={X(1) + 16} y={Y(0.5)} textAnchor="middle" fontSize={10} fontWeight={700} fill={TANGERINE}>rise 1</text>
      {/* big triangle: run 3, rise 3 */}
      <line x1={X(0)} y1={Y(0)} x2={X(3)} y2={Y(0)} stroke={LEAF} strokeWidth={2} opacity={0.9} />
      <line x1={X(3)} y1={Y(0)} x2={X(3)} y2={Y(3)} stroke={LEAF} strokeWidth={2} opacity={0.9} />
      <text x={X(2) + 6} y={oy + 15} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>run 3</text>
      <text x={X(3) + 16} y={Y(1.6)} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>rise 3</text>
      <text x={150} y={16} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>1/1 = 3/3 — same slope!</text>
    </svg>
  );
}

/** Linear vs nonlinear: a straight line has constant equal steps (same rise each time),
 *  while a curve's steps keep growing — the visual + numeric signature of nonlinearity. */
function LinearVsNonlinear() {
  const ox = 22, oy = 96, u = 22;
  const X = (n: number) => ox + n * u;
  const Y = (n: number) => oy - n * u;
  const linPts = [0, 1, 2, 3].map((x) => [X(x), Y(x)]);
  const curvePts = [0, 1, 2, 3].map((x) => [X(x), Y(Math.min(x * x, 3.6))]);
  return (
    <svg viewBox="0 0 300 130" role="img" className="mx-auto w-full max-w-sm">
      <title>On the left, a straight line: the output rises by the same amount at each step, so it is linear. On the right, a curve: the output rises by more and more at each step, so it is nonlinear.</title>
      <text x={70} y={14} textAnchor="middle" fontSize={11} fontWeight={800} fill={SKY}>linear</text>
      <line x1={ox} y1={oy} x2={ox} y2={20} stroke={INK} strokeWidth={1} opacity={0.4} />
      <line x1={ox} y1={oy} x2={X(3.4)} y2={oy} stroke={INK} strokeWidth={1} opacity={0.4} />
      <polyline points={linPts.map((p) => p.join(",")).join(" ")} fill="none" stroke={SKY} strokeWidth={2.5} />
      {linPts.map(([x, y], i) => <circle key={i} cx={x} cy={y} r={3} fill={SKY} />)}
      <text x={70} y={118} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>steps: +1, +1, +1</text>
      <line x1={150} y1={8} x2={150} y2={122} stroke={INK} strokeWidth={1} opacity={0.25} />
      <text x={224} y={14} textAnchor="middle" fontSize={11} fontWeight={800} fill={BERRY}>nonlinear</text>
      <line x1={ox + 158} y1={oy} x2={ox + 158} y2={20} stroke={INK} strokeWidth={1} opacity={0.4} />
      <line x1={ox + 158} y1={oy} x2={X(3.4) + 158} y2={oy} stroke={INK} strokeWidth={1} opacity={0.4} />
      <path d={`M ${X(0) + 158} ${Y(0)} Q ${X(1.6) + 158} ${Y(0.2)} ${X(3) + 158} ${Y(3.4)}`} fill="none" stroke={BERRY} strokeWidth={2.5} />
      {curvePts.map(([x, y], i) => <circle key={i} cx={x + 158} cy={y} r={3} fill={BERRY} />)}
      <text x={224} y={118} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>steps: +1, +3, +5</text>
    </svg>
  );
}

/** The three outcomes of a one-variable linear equation, shown by what it reduces to:
 *  a real x-value (one solution), a false statement like 3=5 (no solution), or a always-true
 *  statement like 3=3 (infinitely many). Color-coded green/red/blue for instant recognition. */
function EquationSolutionTypes() {
  const cards: [string, string, string, string][] = [
    ["one solution", "3x + 1 = x + 7", "x = 3", LEAF],
    ["no solution", "2x + 3 = 2x + 5", "3 = 5  ✗", BERRY],
    ["infinitely many", "2x + 3 = 2x + 3", "3 = 3  ✓", SKY],
  ];
  return (
    <svg viewBox="0 0 340 150" role="img" className="mx-auto w-full max-w-sm">
      <title>Three outcomes for a one-variable equation. First, three x plus one equals x plus seven reduces to x equals three — one solution. Second, two x plus three equals two x plus five reduces to three equals five, which is false — no solution. Third, two x plus three equals two x plus three reduces to three equals three, always true — infinitely many solutions.</title>
      {cards.map(([label, eq, result, color], i) => {
        const x = 10 + i * 110;
        return (
          <g key={label}>
            <rect x={x} y={22} width={104} height={104} rx={9} fill="white" stroke={color} strokeWidth={2} />
            <rect x={x} y={22} width={104} height={22} rx={9} fill={color} opacity={0.15} />
            <text x={x + 52} y={37} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={color}>{label}</text>
            <text x={x + 52} y={72} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>{eq}</text>
            <line x1={x + 22} y1={84} x2={x + 82} y2={84} stroke={INK} strokeWidth={1} opacity={0.3} />
            <text x={x + 52} y={106} textAnchor="middle" fontSize={13} fontWeight={800} fill={color}>{result}</text>
          </g>
        );
      })}
      <text x={170} y={14} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>what does it reduce to?</text>
    </svg>
  );
}

/** The three outcomes of a two-line SYSTEM, shown geometrically: crossing lines (one solution),
 *  parallel lines (none), and one line drawn over itself (infinitely many). */
function SystemSolutionTypes() {
  const panel = (cx: number, kind: "cross" | "parallel" | "same", label: string, color: string) => {
    const cy = 74, r = 30;
    return (
      <g key={label}>
        <text x={cx} y={22} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={color}>{label}</text>
        <rect x={cx - r - 4} y={cy - r - 4} width={2 * r + 8} height={2 * r + 8} rx={7} fill="white" stroke={INK} strokeWidth={1} opacity={0.9} />
        {kind === "cross" && (
          <>
            <line x1={cx - r} y1={cy + r} x2={cx + r} y2={cy - r} stroke={SKY} strokeWidth={2.5} />
            <line x1={cx - r} y1={cy - r} x2={cx + r} y2={cy + r} stroke={BERRY} strokeWidth={2.5} />
            <circle cx={cx} cy={cy} r={4} fill={LEAF} stroke="white" strokeWidth={1.4} />
          </>
        )}
        {kind === "parallel" && (
          <>
            <line x1={cx - r} y1={cy - r + 10} x2={cx + r} y2={cy - r - 6} stroke={SKY} strokeWidth={2.5} />
            <line x1={cx - r} y1={cy + r - 6} x2={cx + r} y2={cy + r - 22} stroke={BERRY} strokeWidth={2.5} />
          </>
        )}
        {kind === "same" && (
          <>
            <line x1={cx - r} y1={cy + r} x2={cx + r} y2={cy - r} stroke={SKY} strokeWidth={5} opacity={0.5} />
            <line x1={cx - r} y1={cy + r} x2={cx + r} y2={cy - r} stroke={BERRY} strokeWidth={2} strokeDasharray="5 4" />
          </>
        )}
      </g>
    );
  };
  return (
    <svg viewBox="0 0 300 130" role="img" className="mx-auto w-full max-w-sm">
      <title>Three outcomes for a system of two lines. Crossing lines meet at one point — one solution. Parallel lines never meet — no solution. Two lines lying exactly on top of each other share every point — infinitely many solutions.</title>
      {panel(52, "cross", "one", LEAF)}
      {panel(150, "parallel", "none", BERRY)}
      {panel(248, "same", "infinite", SKY)}
      <text x={52} y={122} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>lines cross</text>
      <text x={150} y={122} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>parallel</text>
      <text x={248} y={122} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>same line</text>
    </svg>
  );
}

/** The substitution method as a flow: one equation gives y, plug that into the other to
 *  get a one-variable equation, solve for x, then back-substitute to get y. */
function SubstitutionFlow() {
  const boxes: [string, string][] = [
    ["y = 2x − 1", "start: y is alone"],
    ["3x + (2x−1) = 9", "plug into the other"],
    ["5x − 1 = 9 → x = 2", "solve for x"],
    ["y = 2(2)−1 = 3", "back-substitute"],
  ];
  return (
    <svg viewBox="0 0 300 186" role="img" className="mx-auto w-full max-w-xs">
      <title>The substitution method in four steps: start with y equals two x minus one where y is alone, plug that into the other equation to get three x plus the quantity two x minus one equals nine, solve that for x to get x equals two, then back-substitute to find y equals three.</title>
      {/* S238 wave 11: every note used to sit BESIDE its equation and overlap it — now it
          sits under the equation inside a taller box. */}
      {boxes.map(([eq, note], i) => {
        const y = 8 + i * 44;
        const color = i === boxes.length - 1 ? LEAF : SKY;
        return (
          <g key={i}>
            <rect x={40} y={y} width={220} height={36} rx={7} fill="white" stroke={color} strokeWidth={2} />
            <text x={52} y={y + 15} fontSize={11.5} fontWeight={800} fill={INK}>{eq}</text>
            <text x={52} y={y + 29} fontSize={10} fontStyle="italic" fill={color}>{note}</text>
            {i < boxes.length - 1 && (
              <line x1={150} y1={y + 36} x2={150} y2={y + 44} stroke={INK} strokeWidth={1.6} markerEnd="url(#subArrow)" />
            )}
          </g>
        );
      })}
      <defs>
        <marker id="subArrow" markerWidth="8" markerHeight="8" refX="4" refY="6" orient="auto">
          <polygon points="0 0, 8 0, 4 7" fill={INK} />
        </marker>
      </defs>
    </svg>
  );
}

/** The three rigid motions side by side: translation (slide), reflection (flip across a
 *  line), and rotation (turn). In each, the pre-image (blue) and image (orange) are the
 *  same size and shape — that's what "rigid" means. */
function RigidTransformations() {
  const tri = (cx: number, cy: number, s: number, color: string, flip = false, rot = 0) => {
    const pts = [[0, -s], [s, s * 0.7], [-s, s * 0.7]].map(([x, y]) => {
      if (flip) x = -x;
      if (rot === 90) [x, y] = [-y, x];
      return `${cx + x},${cy + y}`;
    });
    return <polygon points={pts.join(" ")} fill={color} opacity={color === SKY ? 0.9 : 0.85} stroke={INK} strokeWidth={1.2} />;
  };
  return (
    <svg viewBox="0 0 300 130" role="img" className="mx-auto w-full max-w-sm">
      <title>Three rigid motions. A translation slides a triangle to a new spot. A reflection flips it across a line like a mirror. A rotation turns it around a point. In every case the moved copy is the same size and shape as the original.</title>
      <text x={50} y={14} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>translate (slide)</text>
      {tri(30, 60, 12, SKY)}
      <line x1={44} y1={60} x2={60} y2={60} stroke={INK} strokeWidth={1.4} markerEnd="url(#rtArrow)" />
      {tri(74, 60, 12, TANGERINE)}
      <line x1={104} y1={16} x2={104} y2={116} stroke={INK} strokeWidth={1} opacity={0.25} />
      <text x={150} y={28} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>reflect (flip)</text>
      {tri(128, 60, 12, SKY)}
      <line x1={150} y1={26} x2={150} y2={100} stroke={BERRY} strokeWidth={1.4} strokeDasharray="4 3" />
      {tri(172, 60, 12, TANGERINE, true)}
      <line x1={204} y1={16} x2={204} y2={116} stroke={INK} strokeWidth={1} opacity={0.25} />
      <text x={252} y={14} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>rotate (turn)</text>
      {tri(240, 62, 12, SKY)}
      <circle cx={258} cy={70} r={2.5} fill={BERRY} />
      <path d="M 250 54 A 14 14 0 0 1 272 62" fill="none" stroke={INK} strokeWidth={1.2} markerEnd="url(#rtArrow)" />
      {tri(268, 74, 12, TANGERINE, false, 90)}
      <text x={150} y={128} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>same size &amp; shape every time</text>
      <defs>
        <marker id="rtArrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><polygon points="0 0, 7 3.5, 0 7" fill={INK} /></marker>
      </defs>
    </svg>
  );
}

/** A dilation: a small triangle scaled out from a center point by a factor of 2. The image
 *  is the same SHAPE but a different SIZE — similar, not congruent. Rays from the center
 *  through each vertex show the scaling. */
function Dilation() {
  const cx = 40, cy = 108;
  const inner = [[24, -18], [54, -12], [30, -48]];
  const k = 1.7;
  const outer = inner.map(([x, y]) => [x * k, y * k]);
  const ip = inner.map(([x, y]) => `${cx + x},${cy + y}`).join(" ");
  const op = outer.map(([x, y]) => `${cx + x},${cy + y}`).join(" ");
  return (
    <svg viewBox="0 0 300 130" role="img" className="mx-auto w-full max-w-sm">
      <title>A dilation from a center point. Rays drawn from the center through each corner of a small triangle are extended to twice the distance, producing a larger triangle of the same shape. The two triangles are similar but not congruent.</title>
      {inner.map((_, i) => (
        <line key={i} x1={cx} y1={cy} x2={cx + outer[i][0]} y2={cy + outer[i][1]} stroke={INK} strokeWidth={0.8} opacity={0.4} strokeDasharray="3 3" />
      ))}
      <polygon points={op} fill={TANGERINE} opacity={0.25} stroke={TANGERINE} strokeWidth={2} />
      <polygon points={ip} fill={SKY} opacity={0.85} stroke={INK} strokeWidth={1.3} />
      <circle cx={cx} cy={cy} r={3.5} fill={BERRY} stroke="white" strokeWidth={1.2} />
      <text x={cx + 2} y={cy + 16} fontSize={10} fontWeight={700} fill={BERRY}>center</text>
      <text x={cx + 40} y={cy - 30} fontSize={10.5} fontWeight={800} fill={SKY}>original</text>
      <text x={cx + 96} y={cy - 74} fontSize={10.5} fontWeight={800} fill={TANGERINE}>×2 image</text>
      <text x={210} y={120} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>same shape, bigger size</text>
    </svg>
  );
}

/** Two parallel lines cut by a transversal, with the eight angles colored to show which
 *  are equal: corresponding and alternate angles share a color; each color pair sums with
 *  the other to 180 degrees. */
function TransversalAngles() {
  // parallel lines at y=40 and y=90; transversal crosses them
  const css = `@media (prefers-reduced-motion: no-preference){.tvA{animation:tv-pulse 2.4s ease-in-out infinite}@keyframes tv-pulse{0%,100%{opacity:1}50%{opacity:.55}}}`;
  return (
    <svg viewBox="0 0 300 140" role="img" className="mx-auto w-full max-w-sm">
      <title>Two parallel lines crossed by a slanted transversal. At each crossing the same pattern of angles appears. Angles in matching positions (corresponding angles) are equal, and alternate interior angles are equal too — shown here by shared colors.</title>
      <style>{css}</style>
      <line x1={20} y1={45} x2={280} y2={45} stroke={INK} strokeWidth={2} />
      <line x1={20} y1={100} x2={280} y2={100} stroke={INK} strokeWidth={2} />
      <polygon points="272,41 280,45 272,49" fill={INK} />
      <polygon points="272,96 280,100 272,104" fill={INK} />
      <line x1={90} y1={20} x2={210} y2={125} stroke={SKY} strokeWidth={2} />
      {/* top crossing ~ (118,45); bottom crossing ~ (182,100) */}
      <circle cx={130} cy={38} r={9} fill={TANGERINE} opacity={0.85} className="tvA" />
      <circle cx={170} cy={107} r={9} fill={TANGERINE} opacity={0.85} className="tvA" />
      <circle cx={106} cy={52} r={9} fill={LEAF} opacity={0.85} />
      <circle cx={195} cy={93} r={9} fill={LEAF} opacity={0.85} />
      <text x={130} y={42} textAnchor="middle" fontSize={10} fontWeight={800} fill="white">a</text>
      <text x={170} y={111} textAnchor="middle" fontSize={10} fontWeight={800} fill="white">a</text>
      <text x={106} y={56} textAnchor="middle" fontSize={10} fontWeight={800} fill="white">b</text>
      <text x={195} y={97} textAnchor="middle" fontSize={10} fontWeight={800} fill="white">b</text>
      <text x={244} y={30} fontSize={10} fontWeight={700} fill={TANGERINE}>a = a</text>
      <text x={250} y={128} fontSize={10} fontWeight={700} fill={LEAF}>b = b</text>
      <text x={30} y={132} fontSize={10} fontWeight={700} fill={INK}>parallel lines + a transversal</text>
    </svg>
  );
}

/** General rearrangement proof of a² + b² = c² using two equal (a+b)-squares. */
function PythagoreanProof() {
  return (
    <svg
      viewBox="0 0 300 180"
      role="img"
      aria-label="General rearrangement proof: equal outer squares with the same four right triangles leave c squared in one arrangement and a squared plus b squared in the other."
      className="mx-auto w-full max-w-sm"
      data-proof="rearrangement"
      data-outer-side="a+b"
      data-congruent-triangles="4"
      data-left-remainder="c²"
      data-right-remainder="a²+b²"
    >
      <title>General rearrangement proof of the Pythagorean theorem</title>
      <desc>Two equal outer squares each have side length a plus b and contain the same four congruent right triangles with legs a and b. In the first arrangement the remaining region is a square of area c squared. In the second arrangement the remaining regions are squares of areas a squared and b squared. Removing equal triangle areas from equal outer squares proves that a squared plus b squared equals c squared.</desc>

      <text x={65} y={11} textAnchor="middle" fontSize={10} fontWeight={800} fill={INK}>leftover c²</text>
      <text x={235} y={11} textAnchor="middle" fontSize={10} fontWeight={800} fill={INK}>leftover a²+b²</text>

      {/* First (a+b)-square: four congruent right triangles surround a true c-by-c square. */}
      <g data-arrangement="c-squared">
        <rect x={10} y={28} width={110} height={110} rx={2} fill="none" stroke={INK} strokeWidth={1.7} data-shape="outer-square" data-side="a+b" />
        <polygon points="10,28 52,28 10,96" fill={SKY} opacity={0.4} stroke={INK} strokeWidth={1} />
        <polygon points="52,28 120,28 120,70" fill={SKY} opacity={0.4} stroke={INK} strokeWidth={1} />
        <polygon points="120,70 120,138 78,138" fill={SKY} opacity={0.4} stroke={INK} strokeWidth={1} />
        <polygon points="78,138 10,138 10,96" fill={SKY} opacity={0.4} stroke={INK} strokeWidth={1} />
        <polygon
          points="52,28 120,70 78,138 10,96"
          fill={BERRY}
          opacity={0.32}
          stroke={BERRY}
          strokeWidth={1.8}
          data-shape="square"
          data-side="c"
          data-area="c²"
        />
        <text x={65} y={88} textAnchor="middle" fontSize={15} fontWeight={900} fill={BERRY}>c²</text>
        <text x={31} y={25} textAnchor="middle" fontSize={10} fontWeight={800} fill={INK}>a</text>
        <text x={86} y={25} textAnchor="middle" fontSize={10} fontWeight={800} fill={INK}>b</text>
      </g>

      <text x={150} y={88} textAnchor="middle" fontSize={18} fontWeight={900} fill={INK}>=</text>

      {/* Second equal (a+b)-square: the same triangles leave true a- and b-squares. */}
      <g data-arrangement="a-squared-plus-b-squared">
        <rect x={180} y={28} width={110} height={110} rx={2} fill="none" stroke={INK} strokeWidth={1.7} data-shape="outer-square" data-side="a+b" />
        <rect x={180} y={28} width={42} height={42} fill={LEAF} opacity={0.38} stroke={LEAF} strokeWidth={1.4} data-shape="square" data-side="a" data-area="a²" />
        <rect x={222} y={70} width={68} height={68} fill={TANGERINE} opacity={0.34} stroke={TANGERINE} strokeWidth={1.4} data-shape="square" data-side="b" data-area="b²" />
        <polygon points="222,28 290,28 290,70" fill={SKY} opacity={0.4} stroke={INK} strokeWidth={1} />
        <polygon points="222,28 290,70 222,70" fill={SKY} opacity={0.4} stroke={INK} strokeWidth={1} />
        <polygon points="180,70 222,70 180,138" fill={SKY} opacity={0.4} stroke={INK} strokeWidth={1} />
        <polygon points="222,70 222,138 180,138" fill={SKY} opacity={0.4} stroke={INK} strokeWidth={1} />
        <text x={201} y={53} textAnchor="middle" fontSize={13} fontWeight={900} fill={LEAF}>a²</text>
        <text x={256} y={108} textAnchor="middle" fontSize={14} fontWeight={900} fill={TANGERINE}>b²</text>
        <text x={201} y={25} textAnchor="middle" fontSize={10} fontWeight={800} fill={INK}>a</text>
        <text x={256} y={25} textAnchor="middle" fontSize={10} fontWeight={800} fill={INK}>b</text>
      </g>

      <text x={150} y={154} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>equal outer squares − the same four triangles</text>
      <text x={150} y={174} textAnchor="middle" fontSize={13} fontWeight={900} fill={BERRY}>a² + b² = c²</text>
    </svg>
  );
}

/** Cylinder, cone, and sphere side by side with their volume formulas. The cone is shaded
 *  to echo that its volume is exactly one-third of the matching cylinder. */
function RoundSolids() {
  return (
    <svg viewBox="0 0 300 150" role="img" className="mx-auto w-full max-w-sm">
      <title>Three round solids with their volume formulas. A cylinder has volume pi times r squared times h. A cone with the same base and height has one-third that volume: one-third pi r squared h. A sphere has volume four-thirds pi r cubed.</title>
      {/* cylinder */}
      <g>
        <ellipse cx={50} cy={34} rx={26} ry={9} fill={SKY} opacity={0.35} stroke={INK} strokeWidth={1.3} />
        <path d="M 24 34 L 24 96 A 26 9 0 0 0 76 96 L 76 34" fill={SKY} opacity={0.2} stroke={INK} strokeWidth={1.3} />
        <ellipse cx={50} cy={96} rx={26} ry={9} fill="none" stroke={INK} strokeWidth={1.3} strokeDasharray="3 3" />
        <text x={50} y={118} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>cylinder</text>
        <text x={50} y={134} textAnchor="middle" fontSize={10} fontWeight={700} fill={SKY}>πr²h</text>
      </g>
      {/* cone */}
      <g>
        <path d="M 150 30 L 124 96 A 26 9 0 0 0 176 96 Z" fill={TANGERINE} opacity={0.3} stroke={INK} strokeWidth={1.3} />
        <ellipse cx={150} cy={96} rx={26} ry={9} fill="none" stroke={INK} strokeWidth={1.3} strokeDasharray="3 3" />
        <text x={150} y={118} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>cone</text>
        <text x={150} y={134} textAnchor="middle" fontSize={10} fontWeight={700} fill={TANGERINE}>⅓πr²h</text>
      </g>
      {/* sphere */}
      <g>
        <circle cx={250} cy={64} r={30} fill={LEAF} opacity={0.25} stroke={INK} strokeWidth={1.3} />
        <ellipse cx={250} cy={64} rx={30} ry={10} fill="none" stroke={INK} strokeWidth={1} opacity={0.5} strokeDasharray="3 3" />
        <text x={250} y={118} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>sphere</text>
        <text x={250} y={134} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>4⁄3πr³</text>
      </g>
      <text x={150} y={14} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>volume of round solids</text>
    </svg>
  );
}

/** Three small scatter plots side by side showing the association types: points trending
 *  up (positive), down (negative), and with no pattern (none). Color-coded per panel. */
function ScatterAssociation() {
  /* S241 (D-17, rules A1/C4): three bare 50%-opacity segments used to stand in for three
   * coordinate planes — no axis names, no ticks, no origin. This is the lesson's canonical
   * picture of a scatter plot, and bv-01-01 teaches exactly the vocabulary it was missing:
   * "one measurement for its across-position (x) and the other for its up-position (y)". Each
   * panel now names both axes, marks the origin the directions are read FROM, and carries tick
   * strokes so "as x goes up, y tends to go up" has countable steps behind it. */
  const panel = (ox: number, pts: [number, number][], label: string, color: string) => (
    <g key={label}>
      <text x={ox + 32} y={16} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={color}>{label}</text>
      <line x1={ox + 6} y1={30} x2={ox + 6} y2={92} stroke={INK} strokeWidth={1} opacity={0.5} />
      <line x1={ox + 6} y1={92} x2={ox + 62} y2={92} stroke={INK} strokeWidth={1} opacity={0.5} />
      {[20, 40].map((d) => (
        <g key={d}>
          <line x1={ox + 6 + d} y1={92} x2={ox + 6 + d} y2={95} stroke={INK} strokeWidth={1} opacity={0.5} />
          <line x1={ox + 3} y1={92 - d} x2={ox + 6} y2={92 - d} stroke={INK} strokeWidth={1} opacity={0.5} />
        </g>
      ))}
      <text x={ox + 2} y={62} textAnchor="end" fontSize={10} fontWeight={700} fill={INK}>y</text>
      <text x={ox + 34} y={104} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>x</text>
      <text x={ox + 3} y={104} textAnchor="end" fontSize={10} fill={INK} opacity={0.75}>0</text>
      {pts.map(([px, py], i) => (
        <circle key={i} cx={ox + 6 + px} cy={92 - py} r={2.6} fill={color} opacity={0.85} />
      ))}
    </g>
  );
  const up: [number, number][] = [[6, 8], [14, 14], [22, 20], [30, 30], [38, 34], [46, 44], [52, 50]];
  const down: [number, number][] = [[6, 50], [14, 42], [22, 36], [30, 26], [38, 22], [46, 12], [52, 8]];
  const none: [number, number][] = [[8, 30], [16, 12], [24, 46], [32, 22], [40, 40], [48, 16], [52, 34]];
  return (
    <svg viewBox="0 0 300 122" role="img" className="mx-auto w-full max-w-sm">
      <title>Three scatter plots. On the left, points rise from lower-left to upper-right — a positive association. In the middle, points fall from upper-left to lower-right — a negative association. On the right, points are scattered with no pattern — no association.</title>
      {panel(6, up, "positive", LEAF)}
      {panel(108, down, "negative", BERRY)}
      {panel(210, none, "none", SKY)}
      <text x={150} y={118} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.75}>x = across-position · y = up-position</text>
    </svg>
  );
}

/** A scatter plot with a straight line of best fit drawn through the middle of the cloud,
 *  showing how the line balances points above and below it. */
function ScatterBestFit() {
  const ox = 30, oy = 118;
  const pts: [number, number][] = [
    [1, 3], [2, 4], [3, 4], [4, 6], [5, 6], [6, 8], [7, 7], [8, 9], [2, 6], [5, 4], [7, 9], [4, 4],
  ];
  const sx = 26, sy = 11;
  const X = (x: number) => ox + x * sx;
  const Y = (y: number) => oy - y * sy;
  // best-fit-ish line y = 0.8x + 2.2 (schematic, balances the cloud)
  const lineY = (x: number) => 0.8 * x + 2.2;
  return (
    <svg viewBox="0 0 300 140" role="img" className="mx-auto w-full max-w-sm">
      <title>A scatter plot of about a dozen points trending upward, with a single straight line drawn through the middle of the cloud. The line of best fit passes close to the points, with roughly as many points above it as below it.</title>
      {/* S241 (D-17, rules A1/C4/A7): the plane the "line of best fit" lives on used to be two
          bare segments — no variable names, no ticks, no origin — so "runs through the middle of
          the cloud" was a claim with no readable coordinates behind it. Axis names plus a
          countable scale on both axes; the origin's 0 is shared by the two axes. */}
      <line x1={ox} y1={oy} x2={ox} y2={14} stroke={INK} strokeWidth={1.2} opacity={0.5} />
      <line x1={ox} y1={oy} x2={270} y2={oy} stroke={INK} strokeWidth={1.2} opacity={0.5} />
      {[2, 4, 6, 8].map((v) => (
        <g key={`x${v}`}>
          <line x1={X(v)} y1={oy} x2={X(v)} y2={oy + 4} stroke={INK} strokeWidth={1.2} opacity={0.5} />
          <text x={X(v)} y={oy + 13} textAnchor="middle" fontSize={10} fill={INK} opacity={0.75}>{v}</text>
        </g>
      ))}
      {[0, 4, 8].map((v) => (
        <g key={`y${v}`}>
          <line x1={ox - 4} y1={Y(v)} x2={ox} y2={Y(v)} stroke={INK} strokeWidth={1.2} opacity={0.5} />
          <text x={ox - 7} y={Y(v) + 3.5} textAnchor="end" fontSize={10} fill={INK} opacity={0.75}>{v}</text>
        </g>
      ))}
      <text x={ox - 7} y={18} textAnchor="end" fontSize={10} fontWeight={700} fill={INK}>y</text>
      <text x={264} y={oy + 13} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>x</text>
      <line x1={X(0.4)} y1={Y(lineY(0.4))} x2={X(8.6)} y2={Y(lineY(8.6))} stroke={TANGERINE} strokeWidth={2.5} />
      {pts.map(([px, py], i) => (
        <circle key={i} cx={X(px)} cy={Y(py)} r={3} fill={SKY} opacity={0.85} stroke="white" strokeWidth={0.6} />
      ))}
      <text x={150} y={12} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>line of best fit</text>
      <text x={222} y={Y(lineY(8.6)) - 4} fontSize={10} fontWeight={700} fill={TANGERINE}>balances the cloud</text>
    </svg>
  );
}

/** A two-way table for categorical bivariate data: rows and columns are two categories,
 *  each cell a count, with row and column totals in the margins. */
function TwoWayTable() {
  const cell = (x: number, y: number, w: number, h: number, fill: string, txt: string, bold = false) => (
    <g>
      <rect x={x} y={y} width={w} height={h} fill={fill} stroke={INK} strokeWidth={1} />
      <text x={x + w / 2} y={y + h / 2 + 4} textAnchor="middle" fontSize={bold ? 12 : 11} fontWeight={bold ? 800 : 600} fill={INK}>{txt}</text>
    </g>
  );
  const x0 = 60, y0 = 34, cw = 58, ch = 26;
  return (
    <svg viewBox="0 0 300 140" role="img" className="mx-auto w-full max-w-sm">
      <title>A two-way table. Columns are labeled dog and cat; rows are labeled child and adult. The four inner cells hold counts: 20 and 10 in the top row, 5 and 15 in the bottom row. The right margin shows row totals 30 and 20, and the bottom margin shows column totals 25 and 25, with a grand total of 50.</title>
      {/* column headers */}
      <text x={x0 + cw / 2} y={y0 - 8} textAnchor="middle" fontSize={11} fontWeight={800} fill={SKY}>dog</text>
      <text x={x0 + cw + cw / 2} y={y0 - 8} textAnchor="middle" fontSize={11} fontWeight={800} fill={SKY}>cat</text>
      <text x={x0 + 2 * cw + cw / 2} y={y0 - 8} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>total</text>
      {/* row headers */}
      <text x={x0 - 8} y={y0 + ch / 2 + 4} textAnchor="end" fontSize={11} fontWeight={800} fill={LEAF}>child</text>
      <text x={x0 - 8} y={y0 + ch + ch / 2 + 4} textAnchor="end" fontSize={11} fontWeight={800} fill={LEAF}>adult</text>
      <text x={x0 - 8} y={y0 + 2 * ch + ch / 2 + 4} textAnchor="end" fontSize={10.5} fontWeight={800} fill={INK}>total</text>
      {/* inner cells */}
      {cell(x0, y0, cw, ch, "#EAF2FB", "20")}
      {cell(x0 + cw, y0, cw, ch, "#EAF2FB", "10")}
      {cell(x0, y0 + ch, cw, ch, "#EAF2FB", "5")}
      {cell(x0 + cw, y0 + ch, cw, ch, "#EAF2FB", "15")}
      {/* margins */}
      {cell(x0 + 2 * cw, y0, cw, ch, "#FFF1E6", "30", true)}
      {cell(x0 + 2 * cw, y0 + ch, cw, ch, "#FFF1E6", "20", true)}
      {cell(x0, y0 + 2 * ch, cw, ch, "#FFF1E6", "25", true)}
      {cell(x0 + cw, y0 + 2 * ch, cw, ch, "#FFF1E6", "25", true)}
      {cell(x0 + 2 * cw, y0 + 2 * ch, cw, ch, "#EDE7F6", "50", true)}
      <text x={150} y={132} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>counts by two categories, with totals</text>
    </svg>
  );
}

/** Parent parabola with a vertical shift and a horizontal shift, arrows showing each move.
 *  Motion (gated): the two shifted copies slide in from the parent's position. */
function TransformationShifts() {
  const ox = 150, oy = 112, sx = 13, sy = 9;
  const X = (x: number) => ox + x * sx;
  const Y = (y: number) => oy - y * sy;
  const path = (h: number, k: number) => {
    const pts: string[] = [];
    for (let t = -3; t <= 3; t += 0.25) {
      const x = t + h, y = 0.6 * t * t + k;
      pts.push(`${pts.length ? "L" : "M"}${X(x).toFixed(1)},${Y(y).toFixed(1)}`);
    }
    return pts.join(" ");
  };
  const css = `@media (prefers-reduced-motion: no-preference){.ts-up{animation:ts-u .6s ease-out backwards .2s}.ts-right{animation:ts-r .6s ease-out backwards .5s}@keyframes ts-u{from{opacity:0;transform:translateY(27px)}to{opacity:1;transform:translateY(0)}}@keyframes ts-r{from{opacity:0;transform:translateX(-65px)}to{opacity:1;transform:translateX(0)}}}`;
  return (
    <svg viewBox="0 0 300 140" role="img" className="mx-auto w-full max-w-sm">
      <title>Three parabolas on one grid. The blue parent parabola has its vertex at the origin. A green copy sits 3 units higher, labeled f of x plus 3, with an up arrow. An orange copy sits 5 units to the right, labeled f of x minus 5, with a right arrow. Each shifted copy keeps the parent's exact shape.</title>
      <style>{css}</style>
      <line x1={X(-9)} y1={oy} x2={X(9.5)} y2={oy} stroke={INK} strokeWidth={1.2} opacity={0.45} />
      <line x1={ox} y1={Y(10.4)} x2={ox} y2={Y(-0.4)} stroke={INK} strokeWidth={1.2} opacity={0.45} />
      <path d={path(0, 0)} fill="none" stroke={SKY} strokeWidth={2.5} />
      <g className="ts-up">
        <path d={path(0, 3)} fill="none" stroke={LEAF} strokeWidth={2.5} strokeDasharray="none" />
      </g>
      <g className="ts-right">
        <path d={path(5, 0)} fill="none" stroke={TANGERINE} strokeWidth={2.5} />
      </g>
      <line x1={X(-2.6)} y1={Y(4.2)} x2={X(-2.6)} y2={Y(6.6)} stroke={LEAF} strokeWidth={1.8} markerEnd="url(#ts-ah-g)" />
      <line x1={X(1.2)} y1={Y(1)} x2={X(3.6)} y2={Y(1)} stroke={TANGERINE} strokeWidth={1.8} markerEnd="url(#ts-ah-o)" />
      <defs>
        <marker id="ts-ah-g" markerWidth="7" markerHeight="7" refX="5" refY="3.5" orient="auto"><path d="M0,0 L7,3.5 L0,7 Z" fill={LEAF} /></marker>
        <marker id="ts-ah-o" markerWidth="7" markerHeight="7" refX="5" refY="3.5" orient="auto"><path d="M0,0 L7,3.5 L0,7 Z" fill={TANGERINE} /></marker>
      </defs>
      <text x={X(-4.6)} y={Y(8.6)} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={LEAF}>f(x) + 3</text>
      <text x={X(0)} y={Y(-0.9)} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={SKY}>f(x)</text>
      <text x={X(7.2)} y={Y(6.2)} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={TANGERINE}>f(x − 5)</text>
      <text x={150} y={12} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>same shape — only the position moves</text>
    </svg>
  );
}

/** Parent parabola vs a vertical stretch and a reflection, all sharing one vertex. */
function StretchReflect() {
  const ox = 150, oy = 74, sx = 15, sy = 7.5;
  const X = (x: number) => ox + x * sx;
  const Y = (y: number) => oy - y * sy;
  const path = (a: number) => {
    const pts: string[] = [];
    for (let t = -3; t <= 3; t += 0.25) {
      pts.push(`${pts.length ? "L" : "M"}${X(t).toFixed(1)},${Y(a * 0.7 * t * t).toFixed(1)}`);
    }
    return pts.join(" ");
  };
  return (
    <svg viewBox="0 0 300 148" role="img" className="mx-auto w-full max-w-sm">
      <title>Three parabolas sharing the same vertex at the origin. The blue parent opens upward. An orange parabola labeled 2 f of x is the same parent stretched taller and narrower. A red parabola labeled negative f of x is the parent flipped upside down, opening downward.</title>
      <line x1={X(-9)} y1={oy} x2={X(9.5)} y2={oy} stroke={INK} strokeWidth={1.2} opacity={0.45} />
      <line x1={ox} y1={Y(9)} x2={ox} y2={Y(-8.6)} stroke={INK} strokeWidth={1.2} opacity={0.45} />
      <path d={path(2)} fill="none" stroke={TANGERINE} strokeWidth={2.5} />
      <path d={path(1)} fill="none" stroke={SKY} strokeWidth={2.5} />
      <path d={path(-1)} fill="none" stroke={BERRY} strokeWidth={2.5} />
      <text x={X(-2.4)} y={Y(8.2)} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={TANGERINE}>2·f(x)</text>
      <text x={X(3.6)} y={Y(5.4)} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={SKY}>f(x)</text>
      <text x={X(3.4)} y={Y(-7.2)} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={BERRY}>−f(x)</text>
      <text x={150} y={143} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>stretch changes steepness; a minus sign flips it</text>
    </svg>
  );
}

/** Two function machines chained: the first machine's output becomes the second's input.
 *  Motion (gated): the number badges light up left-to-right, tracing the value through. */
function CompositionChain() {
  const box = (x: number, fill: string, label: string) => (
    <g>
      <rect x={x} y={44} width={62} height={38} rx={8} fill={fill} opacity={0.9} stroke={INK} strokeWidth={1.4} />
      <text x={x + 31} y={67} textAnchor="middle" fontSize={12} fontWeight={800} fill="white">{label}</text>
    </g>
  );
  const badge = (x: number, txt: string, cls: string) => (
    <g className={cls}>
      <circle cx={x} cy={63} r={13} fill="white" stroke={INK} strokeWidth={1.4} />
      <text x={x} y={67} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>{txt}</text>
    </g>
  );
  const css = `@media (prefers-reduced-motion: no-preference){.cc-1{animation:cc-in .4s ease-out backwards .1s}.cc-2{animation:cc-in .4s ease-out backwards .6s}.cc-3{animation:cc-in .4s ease-out backwards 1.1s}@keyframes cc-in{from{opacity:0;transform:scale(.3);transform-origin:center;transform-box:fill-box}to{opacity:1;transform:scale(1)}}}`;
  return (
    <svg viewBox="0 0 300 120" role="img" className="mx-auto w-full max-w-sm">
      <title>Two function machines connected in a chain. The input 4 enters the first machine, g, whose rule is times 2, producing 8. That 8 immediately enters the second machine, f, whose rule is plus 3, producing the final output 11. The composition f of g of 4 equals 11.</title>
      <style>{css}</style>
      {badge(24, "4", "cc-1")}
      <line x1={39} y1={63} x2={58} y2={63} stroke={INK} strokeWidth={1.6} />
      {box(60, SKY, "g: ×2")}
      <line x1={124} y1={63} x2={143} y2={63} stroke={INK} strokeWidth={1.6} />
      {badge(158, "8", "cc-2")}
      <line x1={173} y1={63} x2={192} y2={63} stroke={INK} strokeWidth={1.6} />
      {box(194, TANGERINE, "f: +3")}
      <line x1={258} y1={63} x2={272} y2={63} stroke={INK} strokeWidth={1.6} />
      {badge(287, "11", "cc-3")}
      <text x={150} y={16} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>f(g(4)): inner machine g runs first</text>
      <text x={150} y={110} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>4 → ×2 → 8 → +3 → 11</text>
    </svg>
  );
}

/** A function and its inverse as mirror images across the dashed line y = x,
 *  with one swapped point pair highlighted. */
function InverseReflection() {
  const ox = 44, oy = 120, s = 20;
  const X = (x: number) => ox + x * s;
  const Y = (y: number) => oy - y * s;
  const curve = (fn: (t: number) => number, t0: number, t1: number) => {
    const pts: string[] = [];
    for (let t = t0; t <= t1 + 0.001; t += (t1 - t0) / 24) {
      pts.push(`${pts.length ? "L" : "M"}${X(t).toFixed(1)},${Y(fn(t)).toFixed(1)}`);
    }
    return pts.join(" ");
  };
  return (
    <svg viewBox="0 0 300 140" role="img" className="mx-auto w-full max-w-sm">
      <title>A coordinate grid with the dashed line y equals x running diagonally. A blue curve for f rises steeply, passing through the point 2 comma 4. An orange curve for f inverse is its exact mirror image across the dashed line, passing through the swapped point 4 comma 2. The two marked points reflect onto each other across the line.</title>
      <line x1={ox} y1={oy} x2={ox} y2={Y(5.4)} stroke={INK} strokeWidth={1.2} opacity={0.45} />
      <line x1={ox} y1={oy} x2={X(5.9)} y2={oy} stroke={INK} strokeWidth={1.2} opacity={0.45} />
      <line x1={X(0)} y1={Y(0)} x2={X(5.3)} y2={Y(5.3)} stroke={INK} strokeWidth={1.4} strokeDasharray="5 4" opacity={0.6} />
      <path d={curve((t) => t * t, 0, 2.3)} fill="none" stroke={SKY} strokeWidth={2.5} />
      <path d={curve((t) => Math.sqrt(t), 0, 5.3)} fill="none" stroke={TANGERINE} strokeWidth={2.5} />
      <circle cx={X(2)} cy={Y(4)} r={4} fill={SKY} stroke="white" strokeWidth={1} />
      <circle cx={X(4)} cy={Y(2)} r={4} fill={TANGERINE} stroke="white" strokeWidth={1} />
      <text x={X(2) + 16} y={Y(4) - 8} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={SKY}>(2, 4)</text>
      <text x={X(4) + 4} y={Y(2) + 17} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={TANGERINE}>(4, 2)</text>
      <text x={X(1)} y={Y(4.55)} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={SKY}>f</text>
      <text x={X(5.3)} y={Y(2.6)} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={TANGERINE}>f⁻¹</text>
      <text x={X(4.6)} y={Y(4.4)} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} transform={`rotate(-38 ${X(4.6)} ${Y(4.4)})`}>y = x</text>
      <text x={150} y={12} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>an inverse swaps every (x, y) pair</text>
    </svg>
  );
}

/** The five Algebra 2 parent functions side by side: line, parabola, absolute value V, square-root half-curve, cubic S-curve — each family in a consistent color content can name. */
function ParentFunctions() {
  const panels: Array<{ label: string; color: string; d: (X: (x: number) => number, Y: (y: number) => number) => string }> = [
    {
      label: "y = x",
      color: SKY,
      d: (X, Y) => `M${X(-2)},${Y(-2)} L${X(2)},${Y(2)}`
    },
    {
      label: "y = x²",
      color: TANGERINE,
      d: (X, Y) => {
        const pts: string[] = [];
        for (let t = -1.6; t <= 1.6; t += 0.2) pts.push(`${pts.length ? "L" : "M"}${X(t).toFixed(1)},${Y(t * t - 1.4).toFixed(1)}`);
        return pts.join(" ");
      }
    },
    {
      label: "y = |x|",
      color: LEAF,
      d: (X, Y) => `M${X(-2)},${Y(0.9)} L${X(0)},${Y(-1.5)} L${X(2)},${Y(0.9)}`
    },
    {
      label: "y = √x",
      color: BERRY,
      d: (X, Y) => {
        const pts: string[] = [];
        for (let t = 0; t <= 4.2; t += 0.3) pts.push(`${pts.length ? "L" : "M"}${X(t - 2).toFixed(1)},${Y(Math.sqrt(t) - 1.3).toFixed(1)}`);
        return pts.join(" ");
      }
    },
    {
      label: "y = x³",
      color: INK,
      d: (X, Y) => {
        const pts: string[] = [];
        for (let t = -1.4; t <= 1.4; t += 0.1) pts.push(`${pts.length ? "L" : "M"}${X(t).toFixed(1)},${Y(t * t * t * 0.7).toFixed(1)}`);
        return pts.join(" ");
      }
    }
  ];
  return (
    <svg viewBox="0 0 340 110" role="img" className="mx-auto w-full max-w-sm">
      <title>Five small graphs, one per parent function: a straight line for y equals x, an upward parabola for y equals x squared, a V shape for absolute value of x, a half curve starting at a point and rising to the right for the square root of x, and an S shaped curve for x cubed.</title>
      {panels.map((p, i) => {
        const px = 4 + i * 67;
        const cx = px + 31, cy = 42;
        const X = (x: number) => cx + x * 13;
        const Y = (y: number) => cy - y * 13;
        return (
          <g key={p.label}>
            <rect x={px} y={6} width={62} height={72} rx={8} fill="white" stroke={INK} strokeWidth={1.2} opacity={0.9} />
            <line x1={px + 5} y1={cy} x2={px + 57} y2={cy} stroke={INK} strokeWidth={1} opacity={0.3} />
            <line x1={cx} y1={12} x2={cx} y2={72} stroke={INK} strokeWidth={1} opacity={0.3} />
            <path d={p.d(X, Y)} fill="none" stroke={p.color} strokeWidth={2.4} strokeLinecap="round" />
            <text x={cx} y={94} textAnchor="middle" fontSize={11} fontWeight={800} fill={p.color}>
              {p.label}
            </text>
          </g>
        );
      })}
      <text x={170} y={107} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>
        every family keeps its shape — transformations only move, flip, or stretch it
      </text>
    </svg>
  );
}

/** A function as a machine: an input goes in, the rule transforms it, an output comes out. */
/** Geometric completing the square: x² + 6x rearranged as an almost-square missing its (b/2)² corner. */
function CompleteSquareArea() {
  const s = 74; // x-square side
  const w = 26; // strip width (b/2)
  const ox = 96, oy = 18;
  const css = `@media (prefers-reduced-motion: no-preference){.cs-corner{animation:cs-in .5s ease-out backwards .9s}.cs-strip{animation:cs-fade .4s ease-out backwards}.cs-s2{animation-delay:.45s}@keyframes cs-in{from{opacity:0;transform:scale(.3);transform-origin:center;transform-box:fill-box}to{opacity:1;transform:scale(1)}}@keyframes cs-fade{from{opacity:0}to{opacity:.92}}}`;
  return (
    <svg viewBox="0 0 340 190" role="img" className="mx-auto w-full max-w-sm">
      <title>Completing the square as area: a large square labeled x squared, with a strip labeled three x attached to its right and another strip labeled three x attached below. Together they form a bigger square of side x plus three, except one small dashed corner square labeled nine is missing. Caption: add nine to complete the square.</title>
      <style>{css}</style>
      <rect x={ox} y={oy} width={s} height={s} rx={4} fill={SKY} opacity={0.92} stroke={INK} strokeWidth={1.4} />
      <text x={ox + s / 2} y={oy + s / 2 + 4} textAnchor="middle" fontSize={14} fontWeight={800} fill="white">x²</text>
      <rect className="cs-strip" x={ox + s + 2} y={oy} width={w} height={s} rx={4} fill={TANGERINE} opacity={0.92} stroke={INK} strokeWidth={1.4} />
      <text x={ox + s + 2 + w / 2} y={oy + s / 2 + 4} textAnchor="middle" fontSize={11} fontWeight={800} fill="white">3x</text>
      <rect className="cs-strip cs-s2" x={ox} y={oy + s + 2} width={s} height={w} rx={4} fill={TANGERINE} opacity={0.92} stroke={INK} strokeWidth={1.4} />
      <text x={ox + s / 2} y={oy + s + 2 + w / 2 + 4} textAnchor="middle" fontSize={11} fontWeight={800} fill="white">3x</text>
      <g className="cs-corner">
        <rect x={ox + s + 2} y={oy + s + 2} width={w} height={w} rx={4} fill="white" stroke={BERRY} strokeWidth={2} strokeDasharray="5 4" />
        <text x={ox + s + 2 + w / 2} y={oy + s + 2 + w / 2 + 4} textAnchor="middle" fontSize={11} fontWeight={800} fill={BERRY}>9</text>
      </g>
      <text x={ox - 10} y={oy + s / 2 + 4} textAnchor="end" fontSize={11} fontWeight={700} fill={INK}>x</text>
      <text x={ox - 10} y={oy + s + 2 + w / 2 + 4} textAnchor="end" fontSize={11} fontWeight={700} fill={TANGERINE}>3</text>
      <text x={ox + s / 2} y={oy - 6} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>x</text>
      <text x={ox + s + 2 + w / 2} y={oy - 6} textAnchor="middle" fontSize={11} fontWeight={700} fill={TANGERINE}>3</text>
      <text x={170} y={178} textAnchor="middle" fontSize={11.5} fontWeight={700} fill={INK}>
        x² + 6x needs the <tspan fill={BERRY} fontWeight={800}>corner 9</tspan> to become the square (x + 3)²
      </text>
    </svg>
  );
}

/** Powers of i cycle: i → −1 → −i → 1 arranged on a circle, each ×i step a quarter turn. */
function PowersOfICycle() {
  const cx = 170, cy = 84, r = 52;
  const stops = [
    { x: cx + r, y: cy, label: "1", sub: "i⁰, i⁴, …", color: INK },
    { x: cx, y: cy - r, label: "i", sub: "i¹", color: SKY },
    { x: cx - r, y: cy, label: "−1", sub: "i²", color: BERRY },
    { x: cx, y: cy + r, label: "−i", sub: "i³", color: TANGERINE }
  ];
  const arc = (a0: number, a1: number) => {
    const p0 = [cx + (r + 22) * Math.cos(a0), cy - (r + 22) * Math.sin(a0)];
    const p1 = [cx + (r + 22) * Math.cos(a1), cy - (r + 22) * Math.sin(a1)];
    return `M${p0[0].toFixed(1)},${p0[1].toFixed(1)} A${r + 22},${r + 22} 0 0 0 ${p1[0].toFixed(1)},${p1[1].toFixed(1)}`;
  };
  const deg = Math.PI / 180;
  const css = `@media (prefers-reduced-motion: no-preference){.pi-a{animation:pi-in .4s ease-out backwards}.pi-a2{animation-delay:.4s}.pi-a3{animation-delay:.8s}.pi-a4{animation-delay:1.2s}@keyframes pi-in{from{opacity:0}to{opacity:1}}}`;
  return (
    <svg viewBox="0 0 340 190" role="img" className="mx-auto w-full max-w-sm">
      <title>The powers of i arranged on a circle: 1 on the right, i on top, negative 1 on the left, negative i on the bottom. Curved arrows labeled times i step counterclockwise from each value to the next, showing the repeating four step cycle 1, i, negative 1, negative i, back to 1.</title>
      <style>{css}</style>
      <circle cx={cx} cy={cy} r={r} fill="none" stroke={INK} strokeWidth={1.2} opacity={0.25} strokeDasharray="3 5" />
      {[["pi-a", 10, 80], ["pi-a pi-a2", 100, 170], ["pi-a pi-a3", 190, 260], ["pi-a pi-a4", 280, 350]].map(([cls, a0, a1], i) => (
        <g key={i} className={cls as string}>
          <path d={arc((a0 as number) * deg, (a1 as number) * deg)} fill="none" stroke={LEAF} strokeWidth={2} markerEnd="url(#pi-arrow)" />
        </g>
      ))}
      <defs>
        <marker id="pi-arrow" viewBox="0 0 8 8" refX={6} refY={4} markerWidth={6} markerHeight={6} orient="auto">
          <path d="M1,1 L7,4 L1,7 Z" fill={LEAF} />
        </marker>
      </defs>
      {[[45], [135], [225], [315]].map(([a], i) => (
        <text key={i} x={cx + (r + 36) * Math.cos(a * deg)} y={cy - (r + 36) * Math.sin(a * deg) + 4} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={LEAF}>× i</text>
      ))}
      {stops.map((s) => (
        <g key={s.label}>
          <circle cx={s.x} cy={s.y} r={17} fill="white" stroke={s.color} strokeWidth={2.2} />
          <text x={s.x} y={s.y + 4.5} textAnchor="middle" fontSize={13} fontWeight={800} fill={s.color}>{s.label}</text>
          <text x={s.x} y={s.y + 31} textAnchor="middle" fontSize={10} fontWeight={700} fill={s.color} opacity={0.85}>{s.sub}</text>
        </g>
      ))}
      <text x={170} y={182} textAnchor="middle" fontSize={11.5} fontWeight={700} fill={INK}>
        multiplying by i is a quarter turn — the cycle repeats every 4 powers
      </text>
    </svg>
  );
}

/** Complex plane: 3 + 2i plotted as a point, real axis horizontal, imaginary axis vertical. */
function ComplexPlane() {
  const cx = 130, cy = 108, u = 26;
  const px = cx + 3 * u, py = cy - 2 * u;
  const css = `@media (prefers-reduced-motion: no-preference){.cp-pt{animation:cp-pop .45s ease-out backwards .7s}.cp-guide{animation:cp-fade .4s ease-out backwards .3s}@keyframes cp-pop{from{opacity:0;transform:scale(.2);transform-origin:center;transform-box:fill-box}to{opacity:1;transform:scale(1)}}@keyframes cp-fade{from{opacity:0}to{opacity:1}}}`;
  return (
    <svg viewBox="0 0 340 190" role="img" className="mx-auto w-full max-w-sm">
      <title>The complex plane: a horizontal real axis and a vertical imaginary axis. The number 3 plus 2 i is plotted as a single point, reached by moving 3 units right along the real axis and 2 units up along the imaginary axis, with dashed guide lines showing each move.</title>
      <style>{css}</style>
      <line x1={cx - 3.6 * u} y1={cy} x2={cx + 4.6 * u} y2={cy} stroke={SKY} strokeWidth={2} />
      <line x1={cx} y1={cy + 2.6 * u} x2={cx} y2={cy - 3.2 * u} stroke={TANGERINE} strokeWidth={2} />
      {[1, 2, 3, 4].map((n) => (
        <g key={"r" + n}>
          <line x1={cx + n * u} y1={cy - 3} x2={cx + n * u} y2={cy + 3} stroke={SKY} strokeWidth={1.6} />
          <text x={cx + n * u} y={cy + 16} textAnchor="middle" fontSize={10} fontWeight={700} fill={SKY}>{n}</text>
        </g>
      ))}
      {[1, 2].map((n) => (
        <g key={"i" + n}>
          <line x1={cx - 3} y1={cy - n * u} x2={cx + 3} y2={cy - n * u} stroke={TANGERINE} strokeWidth={1.6} />
          <text x={cx - 10} y={cy - n * u + 4} textAnchor="end" fontSize={10} fontWeight={700} fill={TANGERINE}>{n}i</text>
        </g>
      ))}
      <text x={cx + 4.6 * u} y={cy - 8} textAnchor="end" fontSize={10.5} fontWeight={800} fill={SKY}>real</text>
      <text x={cx + 8} y={cy - 3.2 * u + 10} fontSize={10.5} fontWeight={800} fill={TANGERINE}>imaginary</text>
      <g className="cp-guide">
        <line x1={px} y1={cy} x2={px} y2={py} stroke={BERRY} strokeWidth={1.6} strokeDasharray="4 4" opacity={0.7} />
        <line x1={cx} y1={py} x2={px} y2={py} stroke={BERRY} strokeWidth={1.6} strokeDasharray="4 4" opacity={0.7} />
      </g>
      <g className="cp-pt">
        <circle cx={px} cy={py} r={6.5} fill={BERRY} stroke="white" strokeWidth={2} />
        <text x={px + 12} y={py - 8} fontSize={12} fontWeight={800} fill={BERRY}>3 + 2i</text>
      </g>
      <text x={170} y={182} textAnchor="middle" fontSize={11.5} fontWeight={700} fill={INK}>
        one complex number = one point: <tspan fill={SKY} fontWeight={800}>3 right</tspan>, <tspan fill={TANGERINE} fontWeight={800}>2i up</tspan>
      </text>
    </svg>
  );
}

/** End behavior 2×2 grid: degree parity × leading-coefficient sign, four mini-graphs. */
function EndBehaviorQuadrants() {
  const cell = (px: number, py: number, label: string, color: string, d: (X: (x: number) => number, Y: (y: number) => number) => string, tag: string) => {
    const cx = px + 37, cy = py + 34;
    const X = (x: number) => cx + x * 15;
    const Y = (y: number) => cy - y * 13;
    return (
      <g key={label}>
        <rect x={px} y={py} width={74} height={66} rx={8} fill="white" stroke={INK} strokeWidth={1.2} opacity={0.9} />
        <line x1={px + 6} y1={cy} x2={px + 68} y2={cy} stroke={INK} strokeWidth={1} opacity={0.25} />
        <path d={d(X, Y)} fill="none" stroke={color} strokeWidth={2.4} strokeLinecap="round" />
        <text x={cx} y={py + 62} textAnchor="middle" fontSize={10} fontWeight={800} fill={color}>{label}</text>
        <text x={cx} y={py - 5} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.75}>{tag}</text>
      </g>
    );
  };
  const evenUp = (X: (v: number) => number, Y: (v: number) => number) => { const p: string[] = []; for (let t = -1.5; t <= 1.5; t += 0.15) p.push(`${p.length ? "L" : "M"}${X(t).toFixed(1)},${Y(t * t - 1).toFixed(1)}`); return p.join(" "); };
  const evenDn = (X: (v: number) => number, Y: (v: number) => number) => { const p: string[] = []; for (let t = -1.5; t <= 1.5; t += 0.15) p.push(`${p.length ? "L" : "M"}${X(t).toFixed(1)},${Y(1 - t * t).toFixed(1)}`); return p.join(" "); };
  const oddUp = (X: (v: number) => number, Y: (v: number) => number) => { const p: string[] = []; for (let t = -1.4; t <= 1.4; t += 0.1) p.push(`${p.length ? "L" : "M"}${X(t).toFixed(1)},${Y(t * t * t * 0.75).toFixed(1)}`); return p.join(" "); };
  const oddDn = (X: (v: number) => number, Y: (v: number) => number) => { const p: string[] = []; for (let t = -1.4; t <= 1.4; t += 0.1) p.push(`${p.length ? "L" : "M"}${X(t).toFixed(1)},${Y(-t * t * t * 0.75).toFixed(1)}`); return p.join(" "); };
  return (
    <svg viewBox="0 0 340 190" role="img" className="mx-auto w-full max-w-sm">
      <title>Four mini graphs arranged by degree parity and leading coefficient sign. Even degree with positive lead rises on both ends like a U. Even degree with negative lead falls on both ends like an upside-down U. Odd degree with positive lead falls on the left and rises on the right. Odd degree with negative lead rises on the left and falls on the right.</title>
      {cell(10, 18, "up · up", SKY, evenUp, "even, a > 0")}
      {cell(94, 18, "down · down", BERRY, evenDn, "even, a < 0")}
      {cell(178, 18, "down · up", LEAF, oddUp, "odd, a > 0")}
      {cell(262, 18, "up · down", TANGERINE, oddDn, "odd, a < 0")}
      <text x={170} y={112} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>degree parity picks the pattern; the leading sign can flip it</text>
      <text x={170} y={132} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK} opacity={0.8}>even degree: ends match &nbsp;·&nbsp; odd degree: ends oppose</text>
    </svg>
  );
}

/** Multiplicity: one curve crossing at an odd-multiplicity zero, bouncing at an even one. */
function MultiplicityBounceCross() {
  // f(x) = (x+2)(x-1)^2 scaled: crosses at -2, bounces at 1
  const cx = 170, cy = 96, ux = 34, uy = 12;
  const X = (x: number) => cx + x * ux;
  const Y = (y: number) => cy - y * uy;
  const pts: string[] = [];
  for (let t = -2.75; t <= 2.35; t += 0.05) {
    const y = (t + 2) * (t - 1) * (t - 1) * 0.55;
    if (y < -6.4 || y > 6.4) { continue; }
    pts.push(`${pts.length ? "L" : "M"}${X(t).toFixed(1)},${Y(y).toFixed(1)}`);
  }
  const css = `@media (prefers-reduced-motion: no-preference){.mb-tag{animation:mb-in .45s ease-out backwards .6s}.mb-t2{animation-delay:1s}@keyframes mb-in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}}`;
  return (
    <svg viewBox="0 0 340 190" role="img" className="mx-auto w-full max-w-sm">
      <title>The graph of a cubic with a zero of multiplicity one at x equals negative 2, where the curve passes straight through the x axis, and a zero of multiplicity two at x equals 1, where the curve comes down, touches the axis, and bounces back up without crossing.</title>
      <style>{css}</style>
      <line x1={X(-3)} y1={cy} x2={X(2.6)} y2={cy} stroke={INK} strokeWidth={1.4} opacity={0.4} />
      <path d={pts.join(" ")} fill="none" stroke={SKY} strokeWidth={2.6} strokeLinecap="round" />
      <circle cx={X(-2)} cy={cy} r={6} fill={BERRY} stroke="white" strokeWidth={2} />
      <circle cx={X(1)} cy={cy} r={6} fill={TANGERINE} stroke="white" strokeWidth={2} />
      <g className="mb-tag">
        <text x={X(-2)} y={cy - 46} textAnchor="middle" fontSize={11} fontWeight={800} fill={BERRY}>crosses at −2</text>
        <text x={X(-2)} y={cy - 32} textAnchor="middle" fontSize={10} fontWeight={700} fill={BERRY} opacity={0.85}>multiplicity 1 (odd)</text>
      </g>
      <g className="mb-tag mb-t2">
        <text x={X(1)} y={cy + 34} textAnchor="middle" fontSize={11} fontWeight={800} fill={TANGERINE}>bounces at 1</text>
        <text x={X(1)} y={cy + 48} textAnchor="middle" fontSize={10} fontWeight={700} fill={TANGERINE} opacity={0.85}>multiplicity 2 (even)</text>
      </g>
      <text x={170} y={180} textAnchor="middle" fontSize={11.5} fontWeight={700} fill={INK}>
        odd multiplicity <tspan fill={BERRY} fontWeight={800}>crosses</tspan> · even multiplicity <tspan fill={TANGERINE} fontWeight={800}>bounces</tspan>
      </text>
    </svg>
  );
}

/** Synthetic division table: x³−2x²−5x+6 ÷ (x−1) with bring-down / multiply / add flow. */
function SyntheticDivision() {
  const cols = [110, 165, 220, 275];
  const top = ["1", "−2", "−5", "6"];
  const mid = ["", "1", "−1", "−6"];
  const bot = ["1", "−1", "−6", "0"];
  const css = `@media (prefers-reduced-motion: no-preference){.sd-r2{animation:sd-in .4s ease-out backwards .5s}.sd-r3{animation:sd-in .4s ease-out backwards 1s}@keyframes sd-in{from{opacity:0}to{opacity:1}}}`;
  return (
    <svg viewBox="0 0 340 190" role="img" className="mx-auto w-full max-w-sm">
      <title>A synthetic division table dividing x cubed minus 2 x squared minus 5 x plus 6 by x minus 1. The value 1 sits in a box on the left. The top row holds the coefficients 1, negative 2, negative 5, 6. Each bottom row entry is the column sum; each middle row entry is the previous bottom entry times 1. The final bottom row reads 1, negative 1, negative 6, with remainder 0 highlighted.</title>
      <style>{css}</style>
      <rect x={38} y={30} width={34} height={30} rx={6} fill={LEAF} opacity={0.92} stroke={INK} strokeWidth={1.4} />
      <text x={55} y={50} textAnchor="middle" fontSize={13} fontWeight={800} fill="white">1</text>
      <text x={55} y={78} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>from x − 1</text>
      {top.map((v, i) => (
        <text key={"t" + i} x={cols[i]} y={50} textAnchor="middle" fontSize={13} fontWeight={800} fill={INK}>{v}</text>
      ))}
      <g className="sd-r2">
        {mid.map((v, i) => v && (
          <text key={"m" + i} x={cols[i]} y={92} textAnchor="middle" fontSize={12} fontWeight={700} fill={SKY}>{v}</text>
        ))}
        <text x={308} y={92} textAnchor="start" fontSize={10} fontWeight={700} fill={SKY}>× 1</text>
      </g>
      <line x1={92} y1={106} x2={300} y2={106} stroke={INK} strokeWidth={1.6} />
      <g className="sd-r3">
        {bot.map((v, i) => i === 3 ? null : (
          <text key={"b" + i} x={cols[i]} y={128} textAnchor="middle" fontSize={13} fontWeight={800} fill={INK}>{v}</text>
        ))}
        <rect x={cols[3] - 16} y={112} width={32} height={22} rx={6} fill="none" stroke={BERRY} strokeWidth={2} />
        <text x={cols[3]} y={128} textAnchor="middle" fontSize={13} fontWeight={800} fill={BERRY}>0</text>
        <text x={cols[3]} y={150} textAnchor="middle" fontSize={10} fontWeight={700} fill={BERRY}>remainder</text>
      </g>
      <text x={170} y={168} textAnchor="middle" fontSize={11.5} fontWeight={700} fill={INK}>
        bring down, <tspan fill={SKY} fontWeight={800}>multiply by 1</tspan>, add
      </text>
      <text x={170} y={184} textAnchor="middle" fontSize={11.5} fontWeight={700} fill={INK}>
        bottom row: x² − x − 6, <tspan fill={BERRY} fontWeight={800}>r = 0</tspan>
      </text>
    </svg>
  );
}

/** Domain of a shifted square-root function: y = √(x−3) with the excluded region shaded. */
function SqrtDomainGraph() {
  const cx = 76, cy = 122, ux = 30, uy = 30;
  const X = (x: number) => cx + x * ux;
  const Y = (y: number) => cy - y * uy;
  const pts: string[] = [];
  for (let t = 0; t <= 5.6; t += 0.08) {
    pts.push(`${pts.length ? "L" : "M"}${X(3 + t).toFixed(1)},${Y(Math.sqrt(t)).toFixed(1)}`);
  }
  const css = `@media (prefers-reduced-motion: no-preference){.sd-dom{animation:sd-dom-in .5s ease-out backwards .5s}@keyframes sd-dom-in{from{opacity:0}to{opacity:1}}}`;
  return (
    <svg viewBox="0 0 340 190" role="img" className="mx-auto w-full max-w-sm">
      <title>The graph of y equals the square root of x minus 3. The curve starts at the point 3 comma 0 and rises to the right. The region left of x equals 3 is shaded to show it is excluded: inputs there would put a negative under the root. An arrow along the x axis marks the domain, x greater than or equal to 3.</title>
      <style>{css}</style>
      <rect x={X(-2.2)} y={18} width={X(3) - X(-2.2)} height={Y(0) - 18} fill={BERRY} opacity={0.1} />
      <line x1={X(3)} y1={20} x2={X(3)} y2={Y(0)} stroke={BERRY} strokeWidth={1.4} strokeDasharray="4 4" opacity={0.7} />
      <line x1={X(-2.2)} y1={cy} x2={X(8.6)} y2={cy} stroke={INK} strokeWidth={1.4} opacity={0.4} />
      <line x1={X(0)} y1={20} x2={X(0)} y2={Y(-0.6)} stroke={INK} strokeWidth={1.4} opacity={0.4} />
      <path d={pts.join(" ")} fill="none" stroke={SKY} strokeWidth={2.6} strokeLinecap="round" />
      <circle cx={X(3)} cy={Y(0)} r={5.5} fill={SKY} stroke="white" strokeWidth={2} />
      <text x={X(3)} y={Y(0) + 20} textAnchor="middle" fontSize={11} fontWeight={800} fill={SKY}>(3, 0)</text>
      <text x={X(0.4)} y={44} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={BERRY}>x &lt; 3 excluded:</text>
      <text x={X(0.4)} y={58} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={BERRY}>negative under the root</text>
      <g className="sd-dom">
        <line x1={X(3)} y1={Y(-0.9)} x2={X(8.2)} y2={Y(-0.9)} stroke={LEAF} strokeWidth={2.4} />
        <path d={`M${X(8.2)},${Y(-0.9)} l-8,-4 v8 z`} fill={LEAF} />
        <circle cx={X(3)} cy={Y(-0.9)} r={4} fill={LEAF} />
        <text x={X(5.4)} y={Y(-0.9) + 18} textAnchor="middle" fontSize={11} fontWeight={800} fill={LEAF}>domain: x ≥ 3</text>
      </g>
      <text x={X(6.6)} y={Y(1.9)} textAnchor="middle" fontSize={11.5} fontWeight={800} fill={SKY}>y = √(x − 3)</text>
    </svg>
  );
}

/** Extraneous solution: y = √(x+7) vs y = x+1 — one true intersection, one phantom. */
function ExtraneousIntersection() {
  const cx = 150, cy = 118, ux = 22, uy = 22;
  const X = (x: number) => cx + x * ux;
  const Y = (y: number) => cy - y * uy;
  const sq: string[] = [];
  for (let t = 0; t <= 11.4; t += 0.1) {
    sq.push(`${sq.length ? "L" : "M"}${X(-7 + t).toFixed(1)},${Y(Math.sqrt(t)).toFixed(1)}`);
  }
  const css = `@media (prefers-reduced-motion: no-preference){.ex-tag{animation:ex-in .45s ease-out backwards .6s}.ex-t2{animation-delay:1.05s}@keyframes ex-in{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}}`;
  return (
    <svg viewBox="0 0 340 204" role="img" className="mx-auto w-full max-w-sm">
      <title>Two graphs: the square root of x plus 7, and the line y equals x plus 1. They truly intersect once, at the point 2 comma 3, marked as the real solution. At the point negative 3 comma negative 2, the line is below the x axis where the square root cannot go — squaring both sides invents this phantom, the extraneous solution.</title>
      <style>{css}</style>
      <line x1={X(-7.6)} y1={cy} x2={X(4.4)} y2={cy} stroke={INK} strokeWidth={1.4} opacity={0.4} />
      <line x1={X(0)} y1={22} x2={X(0)} y2={Y(-2.9)} stroke={INK} strokeWidth={1.4} opacity={0.4} />
      <path d={sq.join(" ")} fill="none" stroke={SKY} strokeWidth={2.6} strokeLinecap="round" />
      <line x1={X(-4.1)} y1={Y(-3.1)} x2={X(2.9)} y2={Y(3.9)} stroke={TANGERINE} strokeWidth={2.4} strokeLinecap="round" />
      <g className="ex-tag">
        <circle cx={X(2)} cy={Y(3)} r={6} fill={LEAF} stroke="white" strokeWidth={2} />
        <text x={X(2) - 4} y={Y(3) - 18} textAnchor="end" fontSize={11} fontWeight={800} fill={LEAF}>(2, 3) — real solution</text>
      </g>
      <g className="ex-t2 ex-tag">
        <circle cx={X(-3)} cy={Y(-2)} r={6} fill="none" stroke={BERRY} strokeWidth={2.4} />
        <line x1={X(-3) - 4} y1={Y(-2) - 4} x2={X(-3) + 4} y2={Y(-2) + 4} stroke={BERRY} strokeWidth={2.4} />
        <text x={X(-3)} y={Y(-2) + 24} textAnchor="middle" fontSize={11} fontWeight={800} fill={BERRY}>(−3, −2) — phantom</text>
        <text x={X(-3)} y={Y(-2) + 38} textAnchor="middle" fontSize={10} fontWeight={700} fill={BERRY} opacity={0.85}>√ can't output −2</text>
      </g>
      <text x={X(-5.9)} y={Y(1.6)} textAnchor="middle" fontSize={11} fontWeight={800} fill={SKY}>y = √(x + 7)</text>
      <text x={X(3.3)} y={Y(3.1)} textAnchor="middle" fontSize={11} fontWeight={800} fill={TANGERINE}>y = x + 1</text>
      <text x={170} y={12} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>squaring both sides can invent solutions — always check</text>
    </svg>
  );
}

/** The reciprocal parent y = 1/x: two branches, dashed asymptotes at x = 0 and y = 0. */
function ReciprocalParent() {
  const cx = 170, cy = 95, u = 26;
  const X = (x: number) => cx + x * u;
  const Y = (y: number) => cy - y * u;
  const branch = (lo: number, hi: number) => {
    const pts: string[] = [];
    for (let t = lo; t <= hi + 1e-9; t += 0.05) {
      pts.push(`${pts.length ? "L" : "M"}${X(t).toFixed(1)},${Y(1 / t).toFixed(1)}`);
    }
    return pts.join(" ");
  };
  const css = `@media (prefers-reduced-motion: no-preference){.rp-b{stroke-dasharray:400;stroke-dashoffset:400;animation:rp-draw .9s ease-out forwards}.rp-b2{animation-delay:.45s}@keyframes rp-draw{to{stroke-dashoffset:0}}}`;
  return (
    <svg viewBox="0 0 340 190" role="img" className="mx-auto w-full max-w-sm">
      <title>The graph of y equals 1 over x: two curved branches. One lives in the first quadrant, the other in the third. Dashed lines mark the two asymptotes: the vertical line x equals 0 and the horizontal line y equals 0. The branches hug the asymptotes but never touch them.</title>
      <style>{css}</style>
      <line x1={X(-6)} y1={cy} x2={X(6)} y2={cy} stroke={BERRY} strokeWidth={1.6} strokeDasharray="5 4" opacity={0.75} />
      <line x1={X(0)} y1={16} x2={X(0)} y2={174} stroke={BERRY} strokeWidth={1.6} strokeDasharray="5 4" opacity={0.75} />
      <path className="rp-b" d={branch(0.36, 5.8)} fill="none" stroke={SKY} strokeWidth={2.6} strokeLinecap="round" />
      <path className="rp-b rp-b2" d={branch(-5.8, -0.36)} fill="none" stroke={SKY} strokeWidth={2.6} strokeLinecap="round" />
      <text x={X(1.7)} y={Y(1.6)} textAnchor="middle" fontSize={11.5} fontWeight={800} fill={SKY}>y = 1/x</text>
      <text x={X(3.9)} y={Y(0) - 7} textAnchor="middle" fontSize={10} fontWeight={700} fill={BERRY}>y = 0</text>
      <text x={X(0) + 5} y={26} fontSize={10} fontWeight={700} fill={BERRY}>x = 0</text>
      <text x={X(-3.4)} y={Y(-1.9)} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.75}>hugs, never touches</text>
    </svg>
  );
}

/** Hole vs vertical asymptote: f(x) = (x−1)/((x−1)(x−3)) — open circle at (1, −1/2), VA at x = 3. */
function HoleVsAsymptote() {
  const cx = 120, cy = 95, u = 30;
  const X = (x: number) => cx + x * u;
  const Y = (y: number) => cy - y * u;
  const f = (x: number) => 1 / (x - 3);
  const seg = (lo: number, hi: number) => {
    const pts: string[] = [];
    for (let t = lo; t <= hi + 1e-9; t += 0.04) {
      const y = f(t);
      if (Math.abs(y) > 2.6) { continue; }
      pts.push(`${pts.length ? "L" : "M"}${X(t).toFixed(1)},${Y(y).toFixed(1)}`);
    }
    return pts.join(" ");
  };
  const css = `@media (prefers-reduced-motion: no-preference){.hv-tag{animation:hv-in .45s ease-out backwards .55s}.hv-t2{animation-delay:1s}@keyframes hv-in{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}}`;
  return (
    <svg viewBox="0 0 340 190" role="img" className="mx-auto w-full max-w-sm">
      <title>The graph of f of x equals x minus 1 over the product x minus 1 times x minus 3. It looks exactly like 1 over x minus 3, except for one missing point: an open circle at 1 comma negative one-half, the hole left by the cancelled factor. At x equals 3 the denominator still vanishes, so a dashed vertical asymptote stands there and the graph blows up alongside it.</title>
      <style>{css}</style>
      <line x1={X(-2.6)} y1={cy} x2={X(6.9)} y2={cy} stroke={INK} strokeWidth={1.3} opacity={0.4} />
      <line x1={X(0)} y1={16} x2={X(0)} y2={174} stroke={INK} strokeWidth={1.3} opacity={0.4} />
      <line x1={X(3)} y1={16} x2={X(3)} y2={174} stroke={BERRY} strokeWidth={1.8} strokeDasharray="5 4" opacity={0.85} />
      <path d={seg(-2.5, 2.92)} fill="none" stroke={SKY} strokeWidth={2.5} strokeLinecap="round" />
      <path d={seg(3.08, 6.8)} fill="none" stroke={SKY} strokeWidth={2.5} strokeLinecap="round" />
      <g className="hv-tag">
        <circle cx={X(1)} cy={Y(-0.5)} r={5.5} fill="white" stroke={LEAF} strokeWidth={2.6} />
        <text x={X(1)} y={Y(-0.5) + 24} textAnchor="middle" fontSize={11} fontWeight={800} fill={LEAF}>hole at (1, −½)</text>
        <text x={X(1)} y={Y(-0.5) + 38} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF} opacity={0.85}>cancelled factor</text>
      </g>
      <g className="hv-t2 hv-tag">
        <text x={X(3)} y={30} textAnchor="middle" fontSize={11} fontWeight={800} fill={BERRY}>asymptote x = 3</text>
        <text x={X(3)} y={44} textAnchor="middle" fontSize={10} fontWeight={700} fill={BERRY} opacity={0.85}>surviving factor</text>
      </g>
      <text x={336} y={162} textAnchor="end" fontSize={10.5} fontWeight={800} fill={SKY}>{"f(x) = (x−1)/((x−1)(x−3))"}</text>
    </svg>
  );
}

/** Horizontal asymptotes by degree comparison: three color-keyed mini panels. */
function HaDegreePanels() {
  const panel = (ox: number, color: string, top: string, sub: string, kind: "zero" | "ratio" | "none") => {
    const w = 100, h = 92, px = (x: number) => ox + x, py = (y: number) => 46 + y;
    const mid = kind === "zero" ? 72 : 56;
    const curve = () => {
      if (kind === "zero") return `M${px(8)},${py(18)} C${px(30)},${py(20)} ${px(46)},${py(24)} ${px(w - 8)},${py(25)}`;
      if (kind === "ratio") return `M${px(8)},${py(30)} C${px(34)},${py(28)} ${px(52)},${py(14)} ${px(w - 8)},${py(11)}`;
      return `M${px(8)},${py(34)} C${px(44)},${py(30)} ${px(70)},${py(6)} ${px(w - 8)},${py(-32)}`;
    };
    return (
      <g key={ox}>
        <rect x={ox} y={22} width={w} height={h + 24} rx={10} fill={color} opacity={0.09} />
        <line x1={px(8)} y1={py(mid - 46)} x2={px(w - 8)} y2={py(mid - 46)} stroke={kind === "none" ? INK : color} strokeWidth={1.6} strokeDasharray={kind === "none" ? "0" : "5 4"} opacity={kind === "none" ? 0.25 : 0.9} />
        <path d={curve()} fill="none" stroke={INK} strokeWidth={2.2} strokeLinecap="round" opacity={0.8} />
        <text x={ox + w / 2} y={14} textAnchor="middle" fontSize={11} fontWeight={800} fill={color}>{top}</text>
        <text x={ox + w / 2} y={152} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK}>{sub}</text>
      </g>
    );
  };
  return (
    <svg viewBox="0 0 340 164" role="img" className="mx-auto w-full max-w-sm">
      <title>Three panels compare a rational function's horizontal asymptote to its degrees. Panel one: when the numerator's degree is smaller, the curve settles onto the dashed line y equals 0. Panel two: when the degrees are equal, it settles onto y equals the ratio of leading coefficients. Panel three: when the numerator's degree is larger, the curve escapes upward — no horizontal asymptote.</title>
      {panel(6, SKY, "top < bottom", "HA: y = 0", "zero")}
      {panel(120, LEAF, "top = bottom", "HA: y = lead ratio", "ratio")}
      {panel(234, TANGERINE, "top > bottom", "no HA", "none")}
    </svg>
  );
}

/** Log as inverse: y = 2^x and y = log2(x) mirrored across the dashed line y = x. */
function LogAsInverse() {
  const cx = 150, cy = 100, u = 24;
  const X = (x: number) => cx + x * u;
  const Y = (y: number) => cy - y * u;
  const expPts: string[] = [], logPts: string[] = [];
  for (let t = -3.4; t <= 2.7; t += 0.06) {
    expPts.push(`${expPts.length ? "L" : "M"}${X(t).toFixed(1)},${Y(Math.pow(2, t)).toFixed(1)}`);
  }
  for (let t = 0.12; t <= 6.4; t += 0.05) {
    logPts.push(`${logPts.length ? "L" : "M"}${X(t).toFixed(1)},${Y(Math.log2(t)).toFixed(1)}`);
  }
  const css = `@media (prefers-reduced-motion: no-preference){.li-log{stroke-dasharray:420;stroke-dashoffset:420;animation:li-draw 1s ease-out forwards .5s}@keyframes li-draw{to{stroke-dashoffset:0}}}`;
  return (
    <svg viewBox="0 0 340 200" role="img" className="mx-auto w-full max-w-sm">
      <title>Two curves mirrored across the dashed diagonal line y equals x. The exponential y equals 2 to the x sweeps up steeply. Its reflection, y equals log base 2 of x, rises slowly to the right of its vertical asymptote at x equals 0. The point 1 comma 2 on the exponential mirrors to 2 comma 1 on the logarithm — inputs and outputs trade places.</title>
      <style>{css}</style>
      <line x1={X(-3.6)} y1={cy} x2={X(6.6)} y2={cy} stroke={INK} strokeWidth={1.3} opacity={0.35} />
      <line x1={X(0)} y1={16} x2={X(0)} y2={188} stroke={INK} strokeWidth={1.3} opacity={0.35} />
      <line x1={X(-3.2)} y1={Y(-3.2)} x2={X(3.9)} y2={Y(3.9)} stroke={INK} strokeWidth={1.5} strokeDasharray="5 4" opacity={0.55} />
      <path d={expPts.join(" ")} fill="none" stroke={SKY} strokeWidth={2.5} strokeLinecap="round" />
      <path className="li-log" d={logPts.join(" ")} fill="none" stroke={LEAF} strokeWidth={2.5} strokeLinecap="round" />
      <circle cx={X(1)} cy={Y(2)} r={4.5} fill={SKY} stroke="white" strokeWidth={1.8} />
      <circle cx={X(2)} cy={Y(1)} r={4.5} fill={LEAF} stroke="white" strokeWidth={1.8} />
      <text x={X(1) - 6} y={Y(2) - 8} textAnchor="end" fontSize={10.5} fontWeight={800} fill={SKY}>(1, 2)</text>
      <text x={X(2) + 7} y={Y(1) + 14} fontSize={10.5} fontWeight={800} fill={LEAF}>(2, 1)</text>
      <text x={X(-2.2)} y={Y(2.6)} textAnchor="middle" fontSize={11.5} fontWeight={800} fill={SKY}>y = 2ˣ</text>
      <text x={X(5.1)} y={Y(1.9)} textAnchor="middle" fontSize={11.5} fontWeight={800} fill={LEAF}>y = log₂x</text>
      <text x={X(3.6)} y={Y(3.65)} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.7}>y = x</text>
      <text x={X(4.6)} y={Y(-2.5)} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF} opacity={0.85}>inputs ↔ outputs</text>
    </svg>
  );
}

/** Approaching e: compounding (1 + 1/n)^n at n = 1, 4, 12, 365 rising toward the dashed e line. */
function ApproachingE() {
  const ns = [1, 4, 12, 365];
  const labels = ["yearly", "quarterly", "monthly", "daily"];
  const vals = ns.map((n) => Math.pow(1 + 1 / n, n));
  const y0 = 168, scale = 46;
  const Y = (v: number) => y0 - v * scale;
  const css = `@media (prefers-reduced-motion: no-preference){.ae-bar{transform-origin:bottom;animation:ae-up .55s ease-out backwards}.ae-b1{animation-delay:.15s}.ae-b2{animation-delay:.35s}.ae-b3{animation-delay:.55s}.ae-b4{animation-delay:.75s}@keyframes ae-up{from{transform:scaleY(0)}to{transform:scaleY(1)}}}`;
  return (
    <svg viewBox="0 0 340 190" role="img" className="mx-auto w-full max-w-sm">
      <title>Four bars show the value of one dollar after a year at 100 percent interest, compounded more and more often: yearly gives 2 dollars, quarterly about 2.44, monthly about 2.61, daily about 2.71. The bars rise toward — but never pass — a dashed line at e, approximately 2.718.</title>
      <style>{css}</style>
      <line x1={24} y1={Y(Math.E)} x2={316} y2={Y(Math.E)} stroke={BERRY} strokeWidth={1.8} strokeDasharray="6 4" />
      <text x={310} y={Y(Math.E) - 22} textAnchor="end" fontSize={11} fontWeight={800} fill={BERRY}>e ≈ 2.718 — the ceiling</text>
      {vals.map((v, i) => (
        <g key={i} className={`ae-bar ae-b${i + 1}`} style={{ transformBox: "fill-box" } as React.CSSProperties}>
          <rect x={40 + i * 72} y={Y(v)} width={44} height={y0 - Y(v)} rx={6} fill={i === 3 ? LEAF : SKY} opacity={0.85} />
          <text x={62 + i * 72} y={Y(v) - 6} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>{v.toFixed(2)}</text>
        </g>
      ))}
      {labels.map((lab, i) => (
        <text key={lab} x={62 + i * 72} y={182} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.8}>{lab}</text>
      ))}
    </svg>
  );
}

/** Log-scale ladder: each step up a log scale multiplies the underlying quantity by 10. */
function LogScaleLadder() {
  const rows = [
    { m: 3, w: 22, label: "×1" },
    { m: 4, w: 58, label: "×10" },
    { m: 5, w: 130, label: "×100" },
    { m: 6, w: 238, label: "×1000" },
  ];
  const css = `@media (prefers-reduced-motion: no-preference){.ls-bar{transform-origin:left center;animation:ls-grow .7s ease-out backwards}.ls-b1{animation-delay:.15s}.ls-b2{animation-delay:.35s}.ls-b3{animation-delay:.55s}@keyframes ls-grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}}`;
  return (
    <svg viewBox="0 0 340 176" role="img" className="mx-auto w-full max-w-sm">
      <title>A ladder comparing a log scale to the quantity it measures. Magnitudes 3, 4, 5, and 6 climb by equal steps of one, but the bars beside them grow by a factor of ten each step: times 1, times 10, times 100, times 1000. Equal steps on the scale mean equal multiplications underneath.</title>
      <style>{css}</style>
      <text x={12} y={16} fontSize={10.5} fontWeight={800} fill={INK}>scale reading</text>
      <text x={328} y={16} textAnchor="end" fontSize={10.5} fontWeight={800} fill={INK}>actual quantity</text>
      {rows.map((r, i) => {
        const y = 34 + i * 34;
        return (
          <g key={r.m}>
            <rect x={12} y={y} width={30} height={22} rx={6} fill={SKY} opacity={0.15} />
            <text x={27} y={y + 15.5} textAnchor="middle" fontSize={12} fontWeight={800} fill={SKY}>{r.m}</text>
            <rect className={`ls-bar ls-b${i}`} x={58} y={y + 3} width={r.w} height={16} rx={5} fill={i === 3 ? TANGERINE : LEAF} opacity={0.85} />
            <text x={58 + r.w + 6} y={y + 15.5} fontSize={11} fontWeight={800} fill={i === 3 ? TANGERINE : LEAF}>{r.label}</text>
          </g>
        );
      })}
      <text x={170} y={170} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK}>+1 on the scale = ×10 underneath</text>
    </svg>
  );
}

/** Recursive vs explicit: five +3 hops walk to the 6th term; one (n−1)d leap jumps straight there. */
function RecursiveVsExplicit() {
  const a1 = 4, d = 3, n = 6;
  const terms = Array.from({ length: n }, (_, i) => a1 + i * d); // 4,7,10,13,16,19
  const bx = (i: number) => 16 + i * 52;
  const css = `@media (prefers-reduced-motion: no-preference){.rv-hop{opacity:0;animation:rv-in .3s ease-out forwards}.rv-h1{animation-delay:.15s}.rv-h2{animation-delay:.35s}.rv-h3{animation-delay:.55s}.rv-h4{animation-delay:.75s}.rv-h5{animation-delay:.95s}.rv-leap{stroke-dasharray:300;stroke-dashoffset:300;animation:rv-draw .8s ease-out forwards 1.25s}@keyframes rv-in{to{opacity:1}}@keyframes rv-draw{to{stroke-dashoffset:0}}}`;
  return (
    <svg viewBox="0 0 340 176" role="img" className="mx-auto w-full max-w-sm">
      <title>The same sequence reached two ways. Six boxes show the terms 4, 7, 10, 13, 16, 19. Above them, five small hop arrows each labeled plus 3 walk term by term — the recursive route. Below them, one long arrow leaps from the first box straight to the last, labeled plus 5 times 3 equals plus 15 — the explicit route. Both land on 19.</title>
      <style>{css}</style>
      <text x={170} y={16} textAnchor="middle" fontSize={11} fontWeight={800} fill={SKY}>recursive: hop +{d}, five times</text>
      {terms.map((t, i) => (
        <g key={i}>
          <rect x={bx(i)} y={72} width={40} height={28} rx={7} fill={i === 0 || i === n - 1 ? "#FFF1E6" : "white"} stroke={INK} strokeWidth={1.5} />
          <text x={bx(i) + 20} y={91} textAnchor="middle" fontSize={12} fontWeight={800} fill={INK}>{t}</text>
        </g>
      ))}
      {terms.slice(1).map((_, i) => (
        <g key={i} className={`rv-hop rv-h${i + 1}`}>
          <path d={`M${bx(i) + 34},68 Q${bx(i) + 46},48 ${bx(i) + 58},68`} fill="none" stroke={SKY} strokeWidth={2.2} strokeLinecap="round" />
          <path d={`M${bx(i) + 58},68 l-6,-4 l1.5,7 z`} fill={SKY} />
          <text x={bx(i) + 46} y={44} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={SKY}>+{d}</text>
        </g>
      ))}
      <path className="rv-leap" d={`M${bx(0) + 20},104 Q${170},156 ${bx(n - 1) + 20},104`} fill="none" stroke={TANGERINE} strokeWidth={2.6} strokeLinecap="round" />
      <path d={`M${bx(n - 1) + 20},104 l-7,3 l2,-7.5 z`} fill={TANGERINE} />
      <text x={170} y={150} textAnchor="middle" fontSize={11} fontWeight={800} fill={TANGERINE}>explicit: one leap of ({n} − 1)·{d} = +{(n - 1) * d}</text>
      <text x={170} y={168} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.75}>same sequence, two rules — both reach {terms[n - 1]}</text>
    </svg>
  );
}

/** Sigma anatomy: the summation symbol with its three parts labeled, and the sum it unrolls into. */
function SigmaAnatomy() {
  const expand = [1, 2, 3, 4, 5].map((k) => 2 * k + 1); // 3,5,7,9,11
  const total = expand.reduce((a, b) => a + b, 0); // 35
  const css = `@media (prefers-reduced-motion: no-preference){.sa-tag{opacity:0;animation:sa-in .4s ease-out forwards}.sa-t1{animation-delay:.2s}.sa-t2{animation-delay:.5s}.sa-t3{animation-delay:.8s}.sa-row{opacity:0;animation:sa-in .5s ease-out forwards 1.15s}@keyframes sa-in{to{opacity:1}}}`;
  return (
    <svg viewBox="0 0 340 186" role="img" className="mx-auto w-full max-w-sm">
      <title>A summation expression taken apart. The large sigma carries three labeled parts: below it, k equals 1 — where the counter starts; above it, 5 — where the counter stops; to its right, 2k plus 1 — the rule each k is fed through. Underneath, the expression unrolls into 3 plus 5 plus 7 plus 9 plus 11, which equals 35.</title>
      <style>{css}</style>
      <text x={104} y={92} textAnchor="middle" fontSize={54} fontWeight={800} fill={INK}>Σ</text>
      <text x={104} y={34} textAnchor="middle" fontSize={13} fontWeight={800} fill={BERRY}>5</text>
      <text x={104} y={122} textAnchor="middle" fontSize={13} fontWeight={800} fill={LEAF}>k = 1</text>
      <text x={162} y={82} fontSize={16} fontWeight={800} fill={SKY}>(2k + 1)</text>
      <g className="sa-tag sa-t1">
        <line x1={124} y1={34} x2={196} y2={22} stroke={BERRY} strokeWidth={1.4} />
        <text x={202} y={26} fontSize={10.5} fontWeight={800} fill={BERRY}>stop when k reaches 5</text>
      </g>
      <g className="sa-tag sa-t2">
        <line x1={130} y1={114} x2={196} y2={126} stroke={LEAF} strokeWidth={1.4} />
        <text x={202} y={130} fontSize={10.5} fontWeight={800} fill={LEAF}>start the counter at 1</text>
      </g>
      <g className="sa-tag sa-t3">
        <line x1={230} y1={76} x2={258} y2={56} stroke={SKY} strokeWidth={1.4} />
        <text x={238} y={46} fontSize={10.5} fontWeight={800} fill={SKY}>feed each k</text>
        <text x={238} y={60} fontSize={10.5} fontWeight={800} fill={SKY}>through this rule</text>
      </g>
      <g className="sa-row">
        <text x={170} y={158} textAnchor="middle" fontSize={13} fontWeight={800} fill={INK}>
          {expand.join(" + ")} = {total}
        </text>
        <text x={170} y={176} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.7}>k = 1, 2, 3, 4, 5 — five terms, unrolled</text>
      </g>
    </svg>
  );
}

/** Gauss pairing: the staircase 1..8 folded into four equal pairs of 9. */
function GaussPairing() {
  const n = 8;
  const total = (n * (n + 1)) / 2; // 36
  const pairSum = n + 1; // 9
  const bw = 26, gap = 9, x0 = 30, y0 = 128, unit = 11;
  const bx = (i: number) => x0 + i * (bw + gap);
  const css = `@media (prefers-reduced-motion: no-preference){.gp-arc{opacity:0;animation:gp-in .4s ease-out forwards}.gp-a1{animation-delay:.2s}.gp-a2{animation-delay:.45s}.gp-a3{animation-delay:.7s}.gp-a4{animation-delay:.95s}@keyframes gp-in{to{opacity:1}}}`;
  return (
    <svg viewBox="0 0 340 238" role="img" className="mx-auto w-full max-w-sm">
      <title>Eight bars form a staircase of heights 1 through 8. Curved brackets pair the outermost bars inward: 1 with 8, 2 with 7, 3 with 6, 4 with 5. Every pair adds to 9, and four pairs of 9 make 36 — the whole staircase's total.</title>
      <style>{css}</style>
      {Array.from({ length: n }, (_, i) => (
        <g key={i}>
          <rect x={bx(i)} y={y0 - (i + 1) * unit} width={bw} height={(i + 1) * unit} rx={4} fill={SKY} opacity={0.8} />
          <text x={bx(i) + bw / 2} y={y0 + 15} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>{i + 1}</text>
        </g>
      ))}
      {[0, 1, 2, 3].map((p) => {
        const xa = bx(p) + bw / 2, xb = bx(n - 1 - p) + bw / 2;
        const yBase = 148, rise = 26 - p * 5;
        return (
          <g key={p} className={`gp-arc gp-a${p + 1}`}>
            <path d={`M${xa},${yBase} Q${(xa + xb) / 2},${yBase + rise} ${xb},${yBase}`} fill="none" stroke={TANGERINE} strokeWidth={2} strokeLinecap="round" />
            <text x={170} y={186 + p * 14} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={TANGERINE}>{p + 1} + {n - p} = {pairSum}</text>
          </g>
        );
      })}
      <text x={170} y={14} textAnchor="middle" fontSize={11.5} fontWeight={800} fill={INK}>4 pairs × {pairSum} = {total}</text>
    </svg>
  );
}

/** Geometric shift-and-subtract: S and rS written in aligned rows; the shared middle cancels, only the edges survive. */
function GeometricShiftSubtract() {
  const a1 = 3, r = 2, n = 4;
  const terms = Array.from({ length: n }, (_, i) => a1 * r ** i); // 3,6,12,24
  const shifted = terms.map((t) => t * r); // 6,12,24,48
  const S = terms.reduce((a, b) => a + b, 0); // 45
  const colX = (i: number) => 96 + i * 56;
  const css = `@media (prefers-reduced-motion: no-preference){.gs-x{opacity:0;animation:gs-in .45s ease-out forwards}.gs-x1{animation-delay:.3s}.gs-x2{animation-delay:.5s}.gs-x3{animation-delay:.7s}.gs-res{opacity:0;animation:gs-in .5s ease-out forwards 1s}@keyframes gs-in{to{opacity:1}}}`;
  return (
    <svg viewBox="0 0 340 178" role="img" className="mx-auto w-full max-w-sm">
      <title>The shift-and-subtract trick on S equals 3 plus 6 plus 12 plus 24. A second row shows 2 S: 6 plus 12 plus 24 plus 48, slid one column right so equal terms line up. Subtracting cancels the shared 6, 12, and 24, leaving 2 S minus S equals 48 minus 3, so S equals 45.</title>
      <style>{css}</style>
      <text x={16} y={44} fontSize={13} fontWeight={800} fill={SKY}>S =</text>
      {terms.map((t, i) => (
        <text key={i} x={colX(i)} y={44} textAnchor="middle" fontSize={13} fontWeight={800} fill={i === 0 ? LEAF : INK}>{i > 0 ? "+ " : ""}{t}</text>
      ))}
      <text x={16} y={84} fontSize={13} fontWeight={800} fill={TANGERINE}>{r}S =</text>
      {shifted.map((t, i) => (
        <text key={i} x={colX(i + 1)} y={84} textAnchor="middle" fontSize={13} fontWeight={800} fill={i === n - 1 ? BERRY : INK}>+ {t}</text>
      ))}
      {[1, 2, 3].map((i) => (
        <g key={i} className={`gs-x gs-x${i}`}>
          <line x1={colX(i) - 16} y1={30} x2={colX(i) + 16} y2={92} stroke={BERRY} strokeWidth={2} strokeLinecap="round" opacity={0.75} />
        </g>
      ))}
      <line x1={16} y1={104} x2={324} y2={104} stroke={INK} strokeWidth={1.4} opacity={0.5} />
      <g className="gs-res">
        <text x={170} y={130} textAnchor="middle" fontSize={12.5} fontWeight={800} fill={INK}>{r}S − S = {shifted[n - 1]} − {terms[0]}</text>
        <text x={170} y={154} textAnchor="middle" fontSize={13} fontWeight={800} fill={LEAF}>S = {S}</text>
        <text x={170} y={172} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.7}>the whole middle cancels — only the edges survive</text>
      </g>
    </svg>
  );
}

/** Shrinking halves: 1/2 + 1/4 + 1/8 + … filling a unit square toward — never past — area 1. */
function ShrinkingHalves() {
  // rects: [x, y, w, h] in a 160-unit square; areas 1/2, 1/4, 1/8, 1/16, 1/32
  const Ssq = 160, x0 = 24, y0 = 16;
  const rects = [
    { x: 0, y: 0, w: 80, h: 160, label: "1/2" },
    { x: 80, y: 0, w: 80, h: 80, label: "1/4" },
    { x: 80, y: 80, w: 40, h: 80, label: "1/8" },
    { x: 120, y: 80, w: 40, h: 40, label: "1/16" },
    { x: 120, y: 120, w: 20, h: 40, label: "1/32" }
  ];
  // machine check: pieces really are the claimed fractions of the 160×160 square
  const fracs = [1 / 2, 1 / 4, 1 / 8, 1 / 16, 1 / 32];
  const running = fracs.reduce((a, b) => a + b, 0); // 31/32
  const fills = [LEAF, SKY, LEAF, SKY, LEAF];
  const css = `@media (prefers-reduced-motion: no-preference){.sh-p{opacity:0;animation:sh-in .4s ease-out forwards}.sh-p1{animation-delay:.15s}.sh-p2{animation-delay:.4s}.sh-p3{animation-delay:.65s}.sh-p4{animation-delay:.9s}.sh-p5{animation-delay:1.15s}@keyframes sh-in{to{opacity:1}}}`;
  return (
    <svg viewBox="0 0 340 196" role="img" className="mx-auto w-full max-w-sm">
      <title>A unit square being filled by ever-halving pieces: one half, then a quarter, an eighth, a sixteenth, a thirty-second. After five pieces, thirty-one thirty-seconds of the square is shaded, and a small unshaded corner remains. The dashed square outline marks area 1 — the total the sum approaches but never passes.</title>
      <style>{css}</style>
      {rects.map((rc, i) => (
        <g key={i} className={`sh-p sh-p${i + 1}`}>
          <rect x={x0 + rc.x} y={y0 + rc.y} width={rc.w} height={rc.h} fill={fills[i]} opacity={0.28 + 0.1 * (i % 2)} stroke={fills[i]} strokeWidth={1.4} />
          <text x={x0 + rc.x + rc.w / 2} y={y0 + rc.y + rc.h / 2 + 4} textAnchor="middle" fontSize={i < 3 ? 13 : 10} fontWeight={800} fill={INK}>{rc.label}</text>
        </g>
      ))}
      <rect x={x0} y={y0} width={Ssq} height={Ssq} fill="none" stroke={BERRY} strokeWidth={2.2} strokeDasharray="7 5" />
      <text x={x0 + Ssq + 14} y={y0 + 30} fontSize={11.5} fontWeight={800} fill={BERRY}>area = 1</text>
      <text x={x0 + Ssq + 14} y={y0 + 46} fontSize={10.5} fontWeight={700} fill={INK} opacity={0.8}>the ceiling the</text>
      <text x={x0 + Ssq + 14} y={y0 + 60} fontSize={10.5} fontWeight={700} fill={INK} opacity={0.8}>sum approaches</text>
      <text x={x0 + Ssq + 14} y={y0 + 96} fontSize={11} fontWeight={800} fill={LEAF}>5 pieces in:</text>
      <text x={x0 + Ssq + 14} y={y0 + 112} fontSize={11} fontWeight={800} fill={LEAF}>{Math.round(running * 32)}/32 shaded</text>
      <text x={170} y={192} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK} opacity={0.75}>1/2 + 1/4 + 1/8 + ⋯ → 1, never past it</text>
    </svg>
  );
}

function SohCahToaTriangle() {
  // 3-4-5 right triangle, theta at the left vertex; machine facts: 3/5=0.6, 4/5=0.8, 3/4=0.75
  const ax = 40, ay = 168, bx = 232, by = 168, cx = 232, cy = 24;
  return (
    <svg viewBox="0 0 340 206" role="img" className="mx-auto w-full max-w-sm">
      <title>A 3-4-5 right triangle with the angle theta at the left vertex. The side opposite theta, of length 3, is drawn in berry red. The side adjacent to theta, of length 4, is drawn in leaf green. The hypotenuse, of length 5, is drawn in sky blue. Callouts read: sine of theta equals opposite over hypotenuse equals 3 fifths; cosine equals adjacent over hypotenuse equals 4 fifths; tangent equals opposite over adjacent equals 3 fourths.</title>
      <polygon points={`${ax},${ay} ${bx},${by} ${cx},${cy}`} fill="#F3F7FD" stroke="none" />
      <rect x={bx - 14} y={by - 14} width={14} height={14} fill="none" stroke={INK} strokeWidth={1.4} />
      <line x1={ax} y1={ay} x2={bx} y2={by} stroke={LEAF} strokeWidth={3.5} strokeLinecap="round" />
      <line x1={bx} y1={by} x2={cx} y2={cy} stroke={BERRY} strokeWidth={3.5} strokeLinecap="round" />
      <line x1={ax} y1={ay} x2={cx} y2={cy} stroke={SKY} strokeWidth={3.5} strokeLinecap="round" />
      <path d={`M ${ax + 34} ${ay} A 34 34 0 0 0 ${ax + 34 * Math.cos(Math.atan2(ay - cy, cx - ax))} ${ay - 34 * Math.sin(Math.atan2(ay - cy, cx - ax))}`} fill="none" stroke={TANGERINE} strokeWidth={2.2} />
      <text x={ax + 46} y={ay - 10} fontSize={13} fontWeight={800} fill={TANGERINE}>θ</text>
      <text x={(ax + bx) / 2} y={ay + 16} textAnchor="middle" fontSize={11} fontWeight={800} fill={LEAF}>adjacent = 4</text>
      <text x={bx - 8} y={(by + cy) / 2 + 4} textAnchor="end" fontSize={11} fontWeight={800} fill={BERRY}>opp = 3</text>
      <text x={(ax + cx) / 2 - 14} y={(ay + cy) / 2 - 10} textAnchor="middle" fontSize={11} fontWeight={800} fill={SKY} transform={`rotate(-37 ${(ax + cx) / 2 - 14} ${(ay + cy) / 2 - 10})`}>hypotenuse = 5</text>
      <text x={300} y={52} textAnchor="middle" fontSize={11} fontWeight={800} fill={BERRY}>sin θ = 3/5</text>
      <text x={300} y={76} textAnchor="middle" fontSize={11} fontWeight={800} fill={LEAF}>cos θ = 4/5</text>
      <text x={300} y={100} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>tan θ = 3/4</text>
      <text x={170} y={200} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK} opacity={0.75}>SOH · CAH · TOA — each ratio names its two sides</text>
    </svg>
  );
}

function RadianWrap() {
  // circle r=52; arcs of exactly 1 radian marked; ~6.28 fit around
  const cx = 110, cy = 96, r = 52;
  const marks: React.ReactNode[] = [];
  for (let k = 0; k <= 6; k++) {
    const a = -Math.PI / 2 + k; // radians, starting at top
    marks.push(
      <circle key={`m${k}`} cx={cx + r * Math.cos(a)} cy={cy + r * Math.sin(a)} r={3.4} fill={k === 0 ? INK : TANGERINE} />
    );
  }
  const a0 = -Math.PI / 2, a1 = -Math.PI / 2 + 1;
  return (
    <svg viewBox="0 0 340 200" role="img" className="mx-auto w-full max-w-sm">
      <title>A circle with radius 52 units. A straight radius segment is shown in sky blue, and an arc of the same length is highlighted in tangerine along the rim, spanning exactly one radian. Tick marks show the radius-length arc stepping around the circle six times with a small piece left over, illustrating that a full circle holds 2 pi, about 6.28, radians. A caption reads: arc length s equals r times theta.</title>
      <circle cx={cx} cy={cy} r={r} fill="none" stroke={INK} strokeWidth={2} opacity={0.55} />
      <line x1={cx} y1={cy} x2={cx + r * Math.cos(a0)} y2={cy + r * Math.sin(a0)} stroke={SKY} strokeWidth={3.2} strokeLinecap="round" />
      <line x1={cx} y1={cy} x2={cx + r * Math.cos(a1)} y2={cy + r * Math.sin(a1)} stroke={SKY} strokeWidth={2} strokeDasharray="4 3" strokeLinecap="round" />
      <path d={`M ${cx + r * Math.cos(a0)} ${cy + r * Math.sin(a0)} A ${r} ${r} 0 0 1 ${cx + r * Math.cos(a1)} ${cy + r * Math.sin(a1)}`} fill="none" stroke={TANGERINE} strokeWidth={4.2} strokeLinecap="round" />
      {marks}
      <text x={cx - 8} y={cy - r - 10} fontSize={11} fontWeight={800} fill={SKY}>radius r</text>
      <text x={cx + r + 6} y={cy - r + 22} fontSize={11} fontWeight={800} fill={TANGERINE}>same length,</text>
      <text x={cx + r + 6} y={cy - r + 36} fontSize={11} fontWeight={800} fill={TANGERINE}>bent: 1 radian</text>
      <text x={262} y={112} textAnchor="middle" fontSize={11.5} fontWeight={800} fill={INK}>2π ≈ 6.28 of them</text>
      <text x={262} y={128} textAnchor="middle" fontSize={11.5} fontWeight={800} fill={INK}>wrap the circle</text>
      <text x={262} y={156} textAnchor="middle" fontSize={12} fontWeight={800} fill={LEAF}>s = rθ</text>
      <text x={170} y={196} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK} opacity={0.75}>a radian is the angle whose arc is one radius long</text>
    </svg>
  );
}

function UnitCircleReference() {
  // 150° point at (-sqrt3/2, 1/2), reference angle 30°; ASTC labels
  const cx = 150, cy = 100, r = 66;
  const px = cx + r * Math.cos((150 * Math.PI) / 180);
  const py = cy - r * Math.sin((150 * Math.PI) / 180);
  return (
    <svg viewBox="0 0 340 200" role="img" className="mx-auto w-full max-w-sm">
      <title>A unit circle with x and y axes. A point at 150 degrees is marked in berry red at coordinates negative square root of three over two, one half. Its reference angle of 30 degrees to the negative x axis is shaded in tangerine, and the matching first-quadrant 30 degree angle is shown dashed. Quadrant labels read A, S, T, C for all, sine, tangent, cosine positive. A caption notes that cosine is the x coordinate and sine is the y coordinate.</title>
      <line x1={cx - 92} y1={cy} x2={cx + 92} y2={cy} stroke={INK} strokeWidth={1.2} opacity={0.45} />
      <line x1={cx} y1={cy - 90} x2={cx} y2={cy + 90} stroke={INK} strokeWidth={1.2} opacity={0.45} />
      <circle cx={cx} cy={cy} r={r} fill="none" stroke={INK} strokeWidth={2} opacity={0.6} />
      <line x1={cx} y1={cy} x2={px} y2={py} stroke={BERRY} strokeWidth={2.8} strokeLinecap="round" />
      <line x1={cx} y1={cy} x2={cx + r * Math.cos(Math.PI / 6)} y2={cy - r * Math.sin(Math.PI / 6)} stroke={LEAF} strokeWidth={2} strokeDasharray="4 3" strokeLinecap="round" />
      <path d={`M ${cx - 26} ${cy} A 26 26 0 0 1 ${cx + 26 * Math.cos((150 * Math.PI) / 180)} ${cy - 26 * Math.sin((150 * Math.PI) / 180)}`} fill="none" stroke={TANGERINE} strokeWidth={2.4} />
      <circle cx={px} cy={py} r={4.5} fill={BERRY} />
      <text x={px - 4} y={py - 12} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={BERRY}>(−√3/2, 1/2)</text>
      <text x={cx - 40} y={cy - 12} fontSize={10.5} fontWeight={800} fill={TANGERINE}>ref 30°</text>
      <text x={cx + 44} y={cy + 34} fontSize={11} fontWeight={800} fill={INK}>150°</text>
      <text x={cx + 70} y={cy - 70} fontSize={12} fontWeight={800} fill={LEAF}>S | A</text>
      <text x={cx + 70} y={cy + 80} fontSize={12} fontWeight={800} fill={LEAF}>T | C</text>
      <text x={38} y={cy - 70} fontSize={11} fontWeight={800} fill={INK} opacity={0.8}>Q2: sin +</text>
      <text x={38} y={cy + 80} fontSize={11} fontWeight={800} fill={INK} opacity={0.8}>Q3: tan +</text>
      <text x={170} y={196} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK} opacity={0.75}>cos θ = x-coordinate · sin θ = y-coordinate · reference angle sets the size, quadrant sets the sign</text>
    </svg>
  );
}

function SineWaveAnatomy() {
  // y = 2 sin(x) + 1: midline y=1 (LEAF), amplitude 2 (BERRY), period 2pi (TANGERINE)
  const x0 = 34, y0 = 96, sx = 40, sy = 22; // 1 rad = 40/ (2pi/ ~6.28) — width: 2pi*40 ≈ 251
  const pts: string[] = [];
  for (let t = 0; t <= 2 * Math.PI + 0.001; t += 0.1) {
    const X = x0 + t * sx;
    const Y = y0 - (2 * Math.sin(t) + 1) * sy;
    pts.push(`${pts.length ? "L" : "M"}${X.toFixed(1)},${Y.toFixed(1)}`);
  }
  const mid = y0 - 1 * sy, top = y0 - 3 * sy, qx = x0 + (Math.PI / 2) * sx;
  return (
    <svg viewBox="0 0 340 200" role="img" className="mx-auto w-full max-w-sm">
      <title>One full cycle of the wave y equals 2 sine x plus 1. A dashed leaf-green horizontal midline sits at y equals 1. A berry-red double arrow from the midline up to the peak marks the amplitude of 2. A tangerine bracket under one complete cycle marks the period of 2 pi. The wave rises to 3, returns through the midline, dips to negative 1, and comes back.</title>
      <line x1={x0 - 8} y1={y0} x2={x0 + 258} y2={y0} stroke={INK} strokeWidth={1.1} opacity={0.4} />
      <line x1={x0} y1={26} x2={x0} y2={168} stroke={INK} strokeWidth={1.1} opacity={0.4} />
      <line x1={x0 - 6} y1={mid} x2={x0 + 256} y2={mid} stroke={LEAF} strokeWidth={2} strokeDasharray="6 4" />
      <path d={pts.join(" ")} fill="none" stroke={SKY} strokeWidth={3} strokeLinecap="round" />
      <line x1={qx} y1={mid} x2={qx} y2={top} stroke={BERRY} strokeWidth={2.4} />
      <polygon points={`${qx},${top} ${qx - 4},${top + 7} ${qx + 4},${top + 7}`} fill={BERRY} />
      <polygon points={`${qx},${mid} ${qx - 4},${mid - 7} ${qx + 4},${mid - 7}`} fill={BERRY} />
      <text x={qx + 8} y={(mid + top) / 2 + 4} fontSize={11} fontWeight={800} fill={BERRY}>amplitude 2</text>
      <text x={x0 + 200} y={mid - 6} fontSize={11} fontWeight={800} fill={LEAF}>midline y = 1</text>
      <path d={`M ${x0} 178 L ${x0} 184 L ${x0 + 2 * Math.PI * sx} 184 L ${x0 + 2 * Math.PI * sx} 178`} fill="none" stroke={TANGERINE} strokeWidth={2.2} />
      <text x={x0 + Math.PI * sx} y={176} textAnchor="middle" fontSize={11} fontWeight={800} fill={TANGERINE}>period 2π</text>
      <text x={170} y={22} textAnchor="middle" fontSize={11.5} fontWeight={800} fill={INK}>y = 2 sin x + 1</text>
    </svg>
  );
}

function FerrisWheelWave() {
  // wheel radius 20 ft, center height 25 ft -> h(t) between 5 and 45; circle left, wave right
  const wx = 64, wy = 108, wr = 40; // wheel
  const gx = 130, gy0 = 168, sx = 26, sy = 2.4; // graph: h in ft * sy px, t rad * sx
  const pts: string[] = [];
  for (let t = 0; t <= 2 * Math.PI + 0.001; t += 0.1) {
    const h = 25 - 20 * Math.cos(t);
    pts.push(`${pts.length ? "L" : "M"}${(gx + t * sx).toFixed(1)},${(gy0 - h * sy).toFixed(1)}`);
  }
  const rt = Math.PI / 3, rh = 25 - 20 * Math.cos(rt);
  return (
    <svg viewBox="0 0 340 200" role="img" className="mx-auto w-full max-w-sm">
      <title>A ferris wheel of radius 20 feet whose center sits 25 feet above the ground, next to a graph of a rider's height over one full turn. The height curve is a cosine-shaped wave running from a low of 5 feet up to a high of 45 feet and back, with a dashed leaf-green midline at 25 feet. A berry-red dot on the wheel rim matches a berry-red dot on the curve at the same height, tying the rotating position to the wave.</title>
      <line x1={10} y1={gy0} x2={330} y2={gy0} stroke={INK} strokeWidth={1.4} opacity={0.5} />
      <circle cx={wx} cy={wy} r={wr} fill="none" stroke={INK} strokeWidth={2.2} opacity={0.7} />
      <line x1={wx} y1={wy} x2={wx} y2={gy0} stroke={INK} strokeWidth={2.2} opacity={0.5} />
      <line x1={wx - 16} y1={gy0} x2={wx + 16} y2={gy0} stroke={INK} strokeWidth={2.6} opacity={0.7} />
      <circle cx={wx + wr * Math.sin(rt)} cy={wy + wr * Math.cos(rt) * -1} r={4.5} fill={BERRY} />
      <text x={wx} y={wy + 4} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>r = 20</text>
      <text x={wx} y={30} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK} opacity={0.8}>center 25 ft up</text>
      <line x1={gx - 4} y1={gy0 - 25 * sy} x2={326} y2={gy0 - 25 * sy} stroke={LEAF} strokeWidth={1.8} strokeDasharray="5 4" />
      <path d={pts.join(" ")} fill="none" stroke={SKY} strokeWidth={2.8} strokeLinecap="round" />
      <circle cx={gx + rt * sx} cy={gy0 - rh * sy} r={4.5} fill={BERRY} />
      <text x={320} y={gy0 - 25 * sy - 6} textAnchor="end" fontSize={10.5} fontWeight={800} fill={LEAF}>midline 25 ft</text>
      <text x={gx + 60} y={gy0 - 45 * sy - 6} fontSize={10.5} fontWeight={800} fill={SKY}>top 45 ft</text>
      <text x={gx + 130} y={gy0 - 5 * sy - 6} fontSize={10.5} fontWeight={800} fill={SKY}>bottom 5 ft</text>
      <text x={170} y={196} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK} opacity={0.75}>h(t) = 25 − 20cos t — circular motion IS the wave</text>
    </svg>
  );
}

