/** A circle with its radius, diameter, and circumference labeled, plus the two formulas. */
function CircleParts() {
  const cx = 82, cy = 68, r = 46;
  return (
    <svg viewBox="0 0 300 140" role="img" className="mx-auto w-full max-w-sm">
      <title>A circle with center marked. A radius is drawn from the center to the edge, and a diameter crosses the whole circle through the center — twice the radius. The distance around the circle is the circumference, 2 pi r, and the space inside is the area, pi r squared.</title>
      <circle cx={cx} cy={cy} r={r} fill={SKY} opacity={0.18} stroke={SKY} strokeWidth={2.5} />
      <line x1={cx - r} y1={cy} x2={cx + r} y2={cy} stroke={BERRY} strokeWidth={2} strokeDasharray="4 3" />
      <text x={cx} y={cy + 14} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={BERRY}>diameter</text>
      <line x1={cx} y1={cy} x2={cx + r * 0.5} y2={cy - r * 0.87} stroke={TANGERINE} strokeWidth={2.5} />
      <text x={cx + 34} y={cy - 34} fontSize={10.5} fontWeight={800} fill={TANGERINE}>radius</text>
      <circle cx={cx} cy={cy} r={2.6} fill={INK} />
      <text x={cx} y={cy - r - 8} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={SKY}>circumference</text>
      <text x={218} y={52} textAnchor="middle" fontSize={12} fontWeight={800} fill={SKY}>C = 2πr</text>
      <text x={218} y={72} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK}>around the circle</text>
      <text x={218} y={100} textAnchor="middle" fontSize={12} fontWeight={800} fill={LEAF}>A = πr²</text>
      <text x={218} y={120} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK}>space inside</text>
    </svg>
  );
}

