/* ================= GEO band shared primitives (unregistered helpers) =================
 * Band visual grammar (ROADMAP): INK = given/static, SKY = primary object,
 * TANGERINE = unknown/target, LEAF = auxiliary/helper, BERRY = image/second object.
 * Every GEO figure composes these marks so congruence notation is identical band-wide. */

/** 1–3 congruence tick marks drawn across the midpoint of segment (x1,y1)–(x2,y2). */
function TickMarks({ x1, y1, x2, y2, n = 1, color = INK }: { x1: number; y1: number; x2: number; y2: number; n?: number; color?: string }) {
  const len = Math.hypot(x2 - x1, y2 - y1);
  const ux = (x2 - x1) / len, uy = (y2 - y1) / len;
  const px = -uy, py = ux;
  const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
  const marks = [];
  for (let i = 0; i < n; i++) {
    const off = (i - (n - 1) / 2) * 5;
    const cx = mx + ux * off, cy = my + uy * off;
    marks.push(<line key={i} x1={cx - px * 5} y1={cy - py * 5} x2={cx + px * 5} y2={cy + py * 5} stroke={color} strokeWidth={2} />);
  }
  return <g>{marks}</g>;
}

/** 1–3 concentric angle arcs at vertex (vx,vy) between rays toward (ax,ay) and (bx,by). */
function AngleArc({ vx, vy, ax, ay, bx, by, r = 16, n = 1, color = INK }: { vx: number; vy: number; ax: number; ay: number; bx: number; by: number; r?: number; n?: number; color?: string }) {
  const a1 = Math.atan2(ay - vy, ax - vx);
  let d = Math.atan2(by - vy, bx - vx) - a1;
  while (d > Math.PI) d -= 2 * Math.PI;
  while (d < -Math.PI) d += 2 * Math.PI;
  const arcs = [];
  for (let i = 0; i < n; i++) {
    const rr = r + i * 4;
    const sx = vx + rr * Math.cos(a1), sy = vy + rr * Math.sin(a1);
    const ex = vx + rr * Math.cos(a1 + d), ey = vy + rr * Math.sin(a1 + d);
    arcs.push(<path key={i} d={`M ${sx.toFixed(1)} ${sy.toFixed(1)} A ${rr} ${rr} 0 0 ${d > 0 ? 1 : 0} ${ex.toFixed(1)} ${ey.toFixed(1)}`} fill="none" stroke={color} strokeWidth={1.6} />);
  }
  return <g>{arcs}</g>;
}

/** Right-angle box at vertex (vx,vy) opening toward (ax,ay) and (bx,by). */
function RightAngleBox({ vx, vy, ax, ay, bx, by, s = 9, color = INK }: { vx: number; vy: number; ax: number; ay: number; bx: number; by: number; s?: number; color?: string }) {
  const la = Math.hypot(ax - vx, ay - vy), lb = Math.hypot(bx - vx, by - vy);
  const uax = (ax - vx) / la, uay = (ay - vy) / la, ubx = (bx - vx) / lb, uby = (by - vy) / lb;
  const p1 = `${vx + uax * s},${vy + uay * s}`;
  const p2 = `${vx + (uax + ubx) * s},${vy + (uay + uby) * s}`;
  const p3 = `${vx + ubx * s},${vy + uby * s}`;
  return <polyline points={`${p1} ${p2} ${p3}`} fill="none" stroke={color} strokeWidth={1.6} />;
}

/** 1–2 parallel-mark chevrons at the midpoint of a segment, pointing from (x1,y1) toward (x2,y2).
 * First consumed by cp's ParallelThroughPoint; also used across pq. */
function ParallelArrows({ x1, y1, x2, y2, n = 1, color = INK }: { x1: number; y1: number; x2: number; y2: number; n?: number; color?: string }) {
  const len = Math.hypot(x2 - x1, y2 - y1);
  const ux = (x2 - x1) / len, uy = (y2 - y1) / len;
  const px = -uy, py = ux;
  const marks = [];
  for (let i = 0; i < n; i++) {
    const off = (i - (n - 1) / 2) * 7;
    const tx = (x1 + x2) / 2 + ux * off, ty = (y1 + y2) / 2 + uy * off;
    const bx = tx - ux * 6, by = ty - uy * 6;
    marks.push(<polyline key={i} points={`${bx + px * 5},${by + py * 5} ${tx},${ty} ${bx - px * 5},${by - py * 5}`} fill="none" stroke={color} strokeWidth={1.8} />);
  }
  return <g>{marks}</g>;
}

/** A labeled point: dot plus an offset label. */
function LabeledPoint({ x, y, label, dx = 8, dy = -6, color = INK, r = 3 }: { x: number; y: number; label: string; dx?: number; dy?: number; color?: string; r?: number }) {
  return (
    <g>
      <circle cx={x} cy={y} r={r} fill={color} />
      <text x={x + dx} y={y + dy} fontSize={11} fontWeight={800} fill={color}>{label}</text>
    </g>
  );
}

