/** A regular pentagon with its 5 mirror lines and its rotational symmetry badge (order 5, 72°). */
function SymmetryFold() {
  const vs: Array<[number, number]> = [[150, 45], [199.5, 80.9], [180.6, 139.1], [119.4, 139.1], [100.5, 80.9]];
  const mids: Array<[number, number]> = [[150, 139.1], [110, 110], [125.2, 63], [174.8, 63], [190.1, 110]];
  return (
    <svg viewBox="0 0 300 170" role="img" aria-label="A regular pentagon with all five lines of symmetry drawn dashed from each vertex to the opposite side's midpoint, plus a badge reading rotation order 5, 72 degrees per turn">
      <title>A regular pentagon with all five lines of symmetry drawn dashed from each vertex to the opposite side's midpoint, plus a badge reading rotation order 5, 72 degrees per turn</title>
      <polygon points={vs.map((v) => v.join(",")).join(" ")} fill={SKY} opacity={0.18} stroke={SKY} strokeWidth={2.2} />
      {vs.map((v, i) => {
        const m = mids[i];
        const dx = m[0] - v[0], dy = m[1] - v[1];
        return <line key={i} x1={v[0] - dx * 0.12} y1={v[1] - dy * 0.12} x2={m[0] + dx * 0.12} y2={m[1] + dy * 0.12} stroke={LEAF} strokeWidth={1.5} strokeDasharray="5 4" />;
      })}
      <path d="M 251 60 A 20 20 0 1 1 231 40" fill="none" stroke={TANGERINE} strokeWidth={2} />
      <polygon points="231,40 240,37 237,46" fill={TANGERINE} />
      <text x={244} y={92} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={TANGERINE}>turn 72°</text>
      <text x={244} y={107} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={TANGERINE}>× 5 = 360°</text>
      <text x={150} y={164} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK}>5 mirror lines · rotation order 5 — the figure maps onto ITSELF</text>
    </svg>
  );
}

