/* ================= GEO-3 triangle-congruence figures =================
 * Composes the shared band primitives (TickMarks, AngleArc, RightAngleBox, LabeledPoint).
 * Roles: SKY = triangle 1, BERRY = triangle 2, TANGERINE = the target/unknown, LEAF = auxiliary.
 * All theorem coordinates are python-computed and machine-verified (centers, midsegment, hinge). */

/** Two congruent triangles marked to show a criterion. `marks` selects which pairs get tick/arc. */
function CriterionPair({ label, marks }: { label: string; marks: "SSS" | "SAS" | "ASA" | "AAS" }) {
  const A: [number, number] = [40, 130], B: [number, number] = [120, 130], C: [number, number] = [70, 70];
  const D: [number, number] = [190, 130], E: [number, number] = [270, 130], F: [number, number] = [220, 70];
  const side = (p: [number, number], q: [number, number], n: number, color: string) => (
    <TickMarks x1={p[0]} y1={p[1]} x2={q[0]} y2={q[1]} n={n} color={color} />
  );
  const arc = (v: [number, number], a: [number, number], b: [number, number], n: number, color: string) => (
    <AngleArc vx={v[0]} vy={v[1]} ax={a[0]} ay={a[1]} bx={b[0]} by={b[1]} n={n} color={color} />
  );
  return (
    <svg viewBox="0 0 300 170" role="img" aria-label={`Two congruent triangles marked to illustrate the ${label} congruence criterion, with matching sides and angles tagged by identical tick and arc marks`}>
      <title>{`${label} congruence criterion`}</title>
      <polygon points={`${A} ${B} ${C}`} fill={SKY} opacity={0.16} stroke={SKY} strokeWidth={2} />
      <polygon points={`${D} ${E} ${F}`} fill={BERRY} opacity={0.16} stroke={BERRY} strokeWidth={2} />
      <LabeledPoint x={A[0]} y={A[1]} label="A" dx={-12} dy={12} color={SKY} />
      <LabeledPoint x={B[0]} y={B[1]} label="B" dx={2} dy={14} color={SKY} />
      <LabeledPoint x={C[0]} y={C[1]} label="C" dy={-6} color={SKY} />
      <LabeledPoint x={D[0]} y={D[1]} label="D" dx={-12} dy={12} color={BERRY} />
      <LabeledPoint x={E[0]} y={E[1]} label="E" dx={2} dy={14} color={BERRY} />
      <LabeledPoint x={F[0]} y={F[1]} label="F" dy={-6} color={BERRY} />
      {marks === "SSS" && (
        <g>
          {side(A, B, 1, INK)}{side(B, C, 2, INK)}{side(C, A, 3, INK)}
          {side(D, E, 1, INK)}{side(E, F, 2, INK)}{side(F, D, 3, INK)}
        </g>
      )}
      {marks === "SAS" && (
        <g>
          {side(A, B, 1, INK)}{side(A, C, 2, INK)}{arc(A, B, C, 1, TANGERINE)}
          {side(D, E, 1, INK)}{side(D, F, 2, INK)}{arc(D, E, F, 1, TANGERINE)}
        </g>
      )}
      {marks === "ASA" && (
        <g>
          {side(A, B, 1, INK)}{arc(A, B, C, 1, TANGERINE)}{arc(B, A, C, 2, LEAF)}
          {side(D, E, 1, INK)}{arc(D, E, F, 1, TANGERINE)}{arc(E, D, F, 2, LEAF)}
        </g>
      )}
      {marks === "AAS" && (
        <g>
          {arc(A, B, C, 1, TANGERINE)}{arc(B, A, C, 2, LEAF)}{side(B, C, 1, INK)}
          {arc(D, E, F, 1, TANGERINE)}{arc(E, D, F, 2, LEAF)}{side(E, F, 1, INK)}
        </g>
      )}
      <text x={150} y={162} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>△ABC ≅ △DEF by {label}</text>
    </svg>
  );
}

function SssCriterion() { return <CriterionPair label="SSS" marks="SSS" />; }
function SasCriterion() { return <CriterionPair label="SAS" marks="SAS" />; }
function AsaCriterion() { return <CriterionPair label="ASA" marks="ASA" />; }
function AasCriterion() { return <CriterionPair label="AAS" marks="AAS" />; }

/** The SSA ambiguous case: one fixed angle + two sides can close into TWO different triangles. */
function SsaAmbiguous() {
  return (
    <svg viewBox="0 0 300 180" role="img" aria-label="The ambiguous SSA case: from vertex A a fixed angle and side AB are drawn, and a swing arc of the second side length crosses the base ray at two points, giving two different possible triangles">
      <title>SSA ambiguous case</title>
      <line x1={30} y1={140} x2={285} y2={140} stroke={INK} strokeWidth={1.5} />
      <line x1={30} y1={140} x2={250} y2={40} stroke={SKY} strokeWidth={2} />
      <LabeledPoint x={30} y={140} label="A" dx={-12} dy={6} color={INK} />
      <LabeledPoint x={175} y={80} label="B" dx={4} dy={-4} color={SKY} />
      <AngleArc vx={30} vy={140} ax={285} ay={140} bx={250} by={40} r={22} color={TANGERINE} />
      {/* swing arc of BC from B crossing the base ray at two points */}
      <path d="M 108 140 A 62 62 0 0 1 172 140" fill="none" stroke={LEAF} strokeWidth={1.6} strokeDasharray="5 4" />
      <line x1={175} y1={80} x2={108} y2={140} stroke={BERRY} strokeWidth={1.8} />
      <line x1={175} y1={80} x2={172} y2={140} stroke={BERRY} strokeWidth={1.8} />
      <LabeledPoint x={108} y={140} label="C₁" dx={-10} dy={16} color={BERRY} r={3.5} />
      <LabeledPoint x={172} y={140} label="C₂" dx={-2} dy={16} color={BERRY} r={3.5} />
      <text x={150} y={30} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>same angle + two sides → TWO triangles</text>
      <text x={150} y={172} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK}>SSA does not determine a triangle</text>
    </svg>
  );
}

/** HL for right triangles: right-angle box, hypotenuse tick, one leg tick, on two triangles. */
function HlCriterion() {
  const A: [number, number] = [40, 130], B: [number, number] = [40, 70], C: [number, number] = [110, 70];
  const D: [number, number] = [190, 130], E: [number, number] = [190, 70], F: [number, number] = [260, 70];
  return (
    <svg viewBox="0 0 300 170" role="img" aria-label="Two right triangles sharing a right-angle mark, with equal-hypotenuse ticks and one equal-leg tick, illustrating the hypotenuse-leg congruence criterion">
      <title>HL congruence criterion</title>
      <polygon points={`${A} ${B} ${C}`} fill={SKY} opacity={0.16} stroke={SKY} strokeWidth={2} />
      <polygon points={`${D} ${E} ${F}`} fill={BERRY} opacity={0.16} stroke={BERRY} strokeWidth={2} />
      <RightAngleBox vx={B[0]} vy={B[1]} ax={A[0]} ay={A[1]} bx={C[0]} by={C[1]} color={INK} />
      <RightAngleBox vx={E[0]} vy={E[1]} ax={D[0]} ay={D[1]} bx={F[0]} by={F[1]} color={INK} />
      <TickMarks x1={A[0]} y1={A[1]} x2={C[0]} y2={C[1]} n={2} color={TANGERINE} />
      <TickMarks x1={D[0]} y1={D[1]} x2={F[0]} y2={F[1]} n={2} color={TANGERINE} />
      <TickMarks x1={B[0]} y1={B[1]} x2={C[0]} y2={C[1]} n={1} color={INK} />
      <TickMarks x1={E[0]} y1={E[1]} x2={F[0]} y2={F[1]} n={1} color={INK} />
      <text x={80} y={150} textAnchor="middle" fontSize={10} fontWeight={700} fill={TANGERINE}>hyp</text>
      <text x={230} y={150} textAnchor="middle" fontSize={10} fontWeight={700} fill={TANGERINE}>hyp</text>
      <text x={150} y={164} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>right angle + hypotenuse + one leg ⇒ ≅</text>
    </svg>
  );
}

/** Isosceles triangle: equal legs ticked, equal base angles arced — the base-angles theorem. */
function IsoscelesBaseAngles() {
  const A: [number, number] = [90, 55], B: [number, number] = [50, 135], C: [number, number] = [130, 135];
  return (
    <svg viewBox="0 0 180 170" role="img" aria-label="An isosceles triangle with its two equal legs marked by single ticks and its two equal base angles marked by matching single arcs">
      <title>Isosceles base angles theorem</title>
      <polygon points={`${A} ${B} ${C}`} fill={SKY} opacity={0.16} stroke={SKY} strokeWidth={2} />
      <TickMarks x1={A[0]} y1={A[1]} x2={B[0]} y2={B[1]} n={1} color={INK} />
      <TickMarks x1={A[0]} y1={A[1]} x2={C[0]} y2={C[1]} n={1} color={INK} />
      <AngleArc vx={B[0]} vy={B[1]} ax={A[0]} ay={A[1]} bx={C[0]} by={C[1]} r={18} color={TANGERINE} />
      <AngleArc vx={C[0]} vy={C[1]} ax={A[0]} ay={A[1]} bx={B[0]} by={B[1]} r={18} color={TANGERINE} />
      <LabeledPoint x={A[0]} y={A[1]} label="A" dy={-6} color={SKY} />
      <LabeledPoint x={B[0]} y={B[1]} label="B" dx={-14} dy={6} color={SKY} />
      <LabeledPoint x={C[0]} y={C[1]} label="C" dx={6} dy={6} color={SKY} />
      <text x={90} y={162} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK}>equal legs ⇒ equal base angles</text>
    </svg>
  );
}

/** Midsegment: midpoints joined; the midsegment is parallel to the base and half its length. */
function Midsegment() {
  const A: [number, number] = [40, 140], B: [number, number] = [160, 140], C: [number, number] = [90, 60];
  const M: [number, number] = [(A[0] + C[0]) / 2, (A[1] + C[1]) / 2];
  const N: [number, number] = [(B[0] + C[0]) / 2, (B[1] + C[1]) / 2];
  return (
    <svg viewBox="0 0 220 170" role="img" aria-label="A triangle with the midpoints of two sides joined by a midsegment, drawn parallel to the base and marked as half its length">
      <title>Triangle midsegment</title>
      <polygon points={`${A} ${B} ${C}`} fill={SKY} opacity={0.14} stroke={SKY} strokeWidth={2} />
      <line x1={M[0]} y1={M[1]} x2={N[0]} y2={N[1]} stroke={TANGERINE} strokeWidth={2.4} />
      <ParallelArrows x1={A[0]} y1={A[1]} x2={B[0]} y2={B[1]} n={1} color={LEAF} />
      <ParallelArrows x1={M[0]} y1={M[1]} x2={N[0]} y2={N[1]} n={1} color={LEAF} />
      <LabeledPoint x={M[0]} y={M[1]} label="M" dx={-16} dy={4} color={TANGERINE} r={3.5} />
      <LabeledPoint x={N[0]} y={N[1]} label="N" dx={6} dy={4} color={TANGERINE} r={3.5} />
      <LabeledPoint x={A[0]} y={A[1]} label="A" dx={-12} dy={8} color={SKY} />
      <LabeledPoint x={B[0]} y={B[1]} label="B" dx={4} dy={8} color={SKY} />
      <LabeledPoint x={C[0]} y={C[1]} label="C" dy={-6} color={SKY} />
      <text x={110} y={162} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK}>MN ∥ AB and MN = ½ AB</text>
    </svg>
  );
}

/** Shared triangle for the four centers; `center` picks which construction + point to show. */
function TriangleCenter({ kind }: { kind: "circumcenter" | "incenter" | "centroid" | "orthocenter" }) {
  const A: [number, number] = [50, 140], B: [number, number] = [250, 150], C: [number, number] = [130, 45];
  const pts: Record<string, [number, number]> = {
    circumcenter: [150.1, 143.1], incenter: [134.4, 103.3], centroid: [143.3, 111.7], orthocenter: [129.8, 48.8]
  };
  const P = pts[kind];
  const mid = (p: [number, number], q: [number, number]): [number, number] => [(p[0] + q[0]) / 2, (p[1] + q[1]) / 2];
  const desc: Record<string, string> = {
    circumcenter: "perpendicular bisectors meet — equidistant from the three vertices",
    incenter: "angle bisectors meet — equidistant from the three sides",
    centroid: "medians meet — the balance point, 2 : 1 from each vertex",
    orthocenter: "altitudes meet"
  };
  return (
    <svg viewBox="0 0 300 184" role="img" aria-label={`A triangle with its ${kind} marked, where the three defining lines meet at a single point`}>
      <title>{`Triangle ${kind}`}</title>
      <polygon points={`${A} ${B} ${C}`} fill={SKY} opacity={0.12} stroke={SKY} strokeWidth={2} />
      {kind === "centroid" && (
        <g stroke={LEAF} strokeWidth={1.4}>
          <line x1={A[0]} y1={A[1]} x2={mid(B, C)[0]} y2={mid(B, C)[1]} />
          <line x1={B[0]} y1={B[1]} x2={mid(A, C)[0]} y2={mid(A, C)[1]} />
          <line x1={C[0]} y1={C[1]} x2={mid(A, B)[0]} y2={mid(A, B)[1]} />
        </g>
      )}
      {kind === "circumcenter" && (
        <g>
          <circle cx={P[0]} cy={P[1]} r={100.1} fill="none" stroke={LEAF} strokeWidth={1} strokeDasharray="4 4" opacity={0.7} />
          {[[A, B], [B, C], [C, A]].map(([p, q], i) => {
            const m = mid(p as [number, number], q as [number, number]);
            return <line key={i} x1={m[0]} y1={m[1]} x2={P[0]} y2={P[1]} stroke={LEAF} strokeWidth={1.2} />;
          })}
        </g>
      )}
      {kind === "incenter" && (
        <g stroke={LEAF} strokeWidth={1.2}>
          <line x1={A[0]} y1={A[1]} x2={P[0]} y2={P[1]} />
          <line x1={B[0]} y1={B[1]} x2={P[0]} y2={P[1]} />
          <line x1={C[0]} y1={C[1]} x2={P[0]} y2={P[1]} />
          <circle cx={P[0]} cy={P[1]} r={40.9} fill="none" stroke={LEAF} strokeWidth={1} strokeDasharray="4 4" opacity={0.7} />
        </g>
      )}
      {kind === "orthocenter" && (
        <g stroke={LEAF} strokeWidth={1.2}>
          <line x1={A[0]} y1={A[1]} x2={129.8} y2={150.5} />
          <line x1={B[0]} y1={B[1]} x2={100.2} y2={72.8} />
          <line x1={C[0]} y1={C[1]} x2={137.5} y2={144.6} />
        </g>
      )}
      <LabeledPoint x={A[0]} y={A[1]} label="A" dx={-12} dy={6} color={SKY} />
      <LabeledPoint x={B[0]} y={B[1]} label="B" dx={4} dy={10} color={SKY} />
      <LabeledPoint x={C[0]} y={C[1]} label="C" dy={-6} color={SKY} />
      <circle cx={P[0]} cy={P[1]} r={4} fill={TANGERINE} />
      <text x={150} y={174} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>{desc[kind]}</text>
    </svg>
  );
}

function Circumcenter() { return <TriangleCenter kind="circumcenter" />; }
function Incenter() { return <TriangleCenter kind="incenter" />; }
function Centroid() { return <TriangleCenter kind="centroid" />; }
function Orthocenter() { return <TriangleCenter kind="orthocenter" />; }

/** ANIMATED CENTERPIECE: the hinge — same two sides, a wider included angle opens a longer third
 * side. Base render shows both triangles; on no-preference the tangerine side "opens". */
function HingeInequality() {
  const css = `@media (prefers-reduced-motion: no-preference){.hinge-open{animation:hinge-sweep 2.2s ease-in-out infinite alternate;transform-origin:60px 130px}@keyframes hinge-sweep{from{transform:rotate(0deg)}to{transform:rotate(-24deg)}}}`;
  return (
    <svg viewBox="0 0 300 170" role="img" aria-label="Two triangles with the same two side lengths; the one with the larger included angle has the longer third side, illustrating the hinge theorem">
      <title>Hinge theorem</title>
      <style>{css}</style>
      {/* fixed lower arm */}
      <line x1={60} y1={130} x2={200} y2={130} stroke={INK} strokeWidth={2.4} />
      <LabeledPoint x={60} y={130} label="A" dx={-12} dy={6} color={INK} />
      {/* small-angle triangle (SKY): upper arm + short third side */}
      <g>
        <line x1={60} y1={130} x2={168} y2={92} stroke={SKY} strokeWidth={2.4} />
        <line x1={168} y1={92} x2={200} y2={130} stroke={SKY} strokeWidth={1.8} strokeDasharray="4 3" />
        <AngleArc vx={60} vy={130} ax={200} ay={130} bx={168} by={92} r={26} color={SKY} />
        <text x={196} y={86} fontSize={10} fontWeight={700} fill={SKY}>small ∠ → short side</text>
      </g>
      {/* large-angle triangle (BERRY): opened arm + long third side */}
      <g className="hinge-open">
        <line x1={60} y1={130} x2={150} y2={58} stroke={BERRY} strokeWidth={2.4} />
      </g>
      <line x1={150} y1={58} x2={200} y2={130} stroke={TANGERINE} strokeWidth={2.2} />
      <AngleArc vx={60} vy={130} ax={200} ay={130} bx={150} by={58} r={34} color={BERRY} />
      <text x={150} y={44} textAnchor="middle" fontSize={10} fontWeight={700} fill={TANGERINE}>large ∠ → long side</text>
      <LabeledPoint x={200} y={130} label="C" dx={4} dy={10} color={INK} />
      <text x={150} y={164} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK}>same two sides — wider angle, longer opposite side</text>
    </svg>
  );
}


/* ================= GEO-4 similarity figures =================
 * Roles: SKY = pre-image / triangle 1, BERRY = image / triangle 2 (scaled), TANGERINE = target/unknown,
 * LEAF = auxiliary (rays, parallels). Proportional-side styling: image sides get thicker strokes to
 * read as "scaled" vs congruence's identical ticks. All theorem coordinates python-verified. */

/** ANIMATED CENTERPIECE: a dilation from center O. Base render shows pre-image + image at k=1.5;
 * on no-preference the image gently "breathes" between k=1 and k=1.5 to show scale factor at work. */
function DilationScale() {
  // pre-image triangle P,Q,R; image = O + k*(pt-O) at k=1.5, python-verified (P'=(120,90) etc.)
  const O: [number, number] = [30, 150];
  const P: [number, number] = [90, 110], Q: [number, number] = [110, 130], R: [number, number] = [75, 85];
  const k = 1.5;
  const img = (pt: [number, number]): [number, number] => [O[0] + k * (pt[0] - O[0]), O[1] + k * (pt[1] - O[1])];
  const [P2, Q2, R2] = [img(P), img(Q), img(R)];
  const css = `@media (prefers-reduced-motion: no-preference){.dil-img{animation:dil-breathe 3s ease-in-out infinite alternate;transform-origin:30px 150px}@keyframes dil-breathe{from{transform:scale(0.667)}to{transform:scale(1)}}}`;
  return (
    <svg viewBox="0 0 300 180" role="img" aria-label="A dilation from a center point: rays from the center pass through the small pre-image triangle and out to the larger image triangle, scaled by factor one-and-a-half">
      <title>Dilation by a scale factor</title>
      <style>{css}</style>
      {/* rays from O through each vertex */}
      <g stroke={LEAF} strokeWidth={1} strokeDasharray="3 3" opacity={0.7}>
        <line x1={O[0]} y1={O[1]} x2={P2[0]} y2={P2[1]} />
        <line x1={O[0]} y1={O[1]} x2={Q2[0]} y2={Q2[1]} />
        <line x1={O[0]} y1={O[1]} x2={R2[0]} y2={R2[1]} />
      </g>
      <polygon points={`${P2} ${Q2} ${R2}`} className="dil-img" fill={BERRY} opacity={0.14} stroke={BERRY} strokeWidth={2.4} />
      <polygon points={`${P} ${Q} ${R}`} fill={SKY} opacity={0.2} stroke={SKY} strokeWidth={2} />
      <circle cx={O[0]} cy={O[1]} r={4} fill={INK} />
      <text x={O[0] - 10} y={O[1] + 4} fontSize={11} fontWeight={700} fill={INK}>O</text>
      <text x={150} y={168} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK}>image = O + k·(point − O),  k = 1.5</text>
    </svg>
  );
}

/** Two similar triangles marked for a criterion. `marks` picks AA, SAS~, or SSS~. */
function SimilarPair({ label, marks }: { label: string; marks: "AA" | "SAS" | "SSS" }) {
  // small SKY triangle; large BERRY triangle = scale by 1.6 (shape identical, size differs)
  const A: [number, number] = [30, 120], B: [number, number] = [95, 120], C: [number, number] = [55, 70];
  const s = 1.6, ox = 150, oy = 8;
  const scale = (p: [number, number]): [number, number] => [ox + (p[0] - 30) * s * 0.7, oy + (p[1] - 70) * s + 62];
  const [D, E, F] = [scale(A), scale(B), scale(C)];
  const arc = (v: [number, number], a: [number, number], b: [number, number], n: number, color: string) => (
    <AngleArc vx={v[0]} vy={v[1]} ax={a[0]} ay={a[1]} bx={b[0]} by={b[1]} n={n} color={color} />
  );
  const side = (p: [number, number], q: [number, number], n: number, color: string) => (
    <TickMarks x1={p[0]} y1={p[1]} x2={q[0]} y2={q[1]} n={n} color={color} />
  );
  return (
    <svg viewBox="0 0 300 175" role="img" aria-label={`Two similar triangles, a small one and a larger scaled copy, marked to show the ${label} similarity criterion`}>
      <title>{`${label} similarity criterion`}</title>
      <polygon points={`${A} ${B} ${C}`} fill={SKY} opacity={0.16} stroke={SKY} strokeWidth={2} />
      <polygon points={`${D} ${E} ${F}`} fill={BERRY} opacity={0.14} stroke={BERRY} strokeWidth={2.6} />
      {marks === "AA" && (
        <g>
          {arc(A, B, C, 1, TANGERINE)}{arc(B, A, C, 2, LEAF)}
          {arc(D, E, F, 1, TANGERINE)}{arc(E, D, F, 2, LEAF)}
        </g>
      )}
      {marks === "SAS" && (
        <g>
          {side(A, B, 1, INK)}{side(A, C, 2, INK)}{arc(A, B, C, 1, TANGERINE)}
          {side(D, E, 1, INK)}{side(D, F, 2, INK)}{arc(D, E, F, 1, TANGERINE)}
        </g>
      )}
      {marks === "SSS" && (
        <g>
          {side(A, B, 1, INK)}{side(B, C, 2, INK)}{side(C, A, 3, INK)}
          {side(D, E, 1, INK)}{side(E, F, 2, INK)}{side(F, D, 3, INK)}
        </g>
      )}
      <text x={150} y={168} textAnchor="middle" fontSize={11} fontWeight={800} fill={INK}>△ABC ~ △DEF by {label}</text>
    </svg>
  );
}

function AaSimilar() { return <SimilarPair label="AA" marks="AA" />; }
function SasSimilar() { return <SimilarPair label="SAS~" marks="SAS" />; }
function SssSimilar() { return <SimilarPair label="SSS~" marks="SSS" />; }

/** Side-splitter: a line parallel to the base cuts the other two sides proportionally (4:6 = 6:9). */
function SideSplitter() {
  const A: [number, number] = [110, 30], B: [number, number] = [40, 150], C: [number, number] = [230, 150];
  // D on AB, E on AC with AD:DB = 4:6 = AE:EC
  const t = 4 / 10;
  const D: [number, number] = [A[0] + t * (B[0] - A[0]), A[1] + t * (B[1] - A[1])];
  const E: [number, number] = [A[0] + t * (C[0] - A[0]), A[1] + t * (C[1] - A[1])];
  return (
    <svg viewBox="0 0 300 175" role="img" aria-label="A triangle with a line drawn parallel to its base, cutting the two sides into proportional segments, four to six on each side">
      <title>Side-splitter theorem</title>
      <polygon points={`${A} ${B} ${C}`} fill={SKY} opacity={0.14} stroke={SKY} strokeWidth={2} />
      <line x1={D[0]} y1={D[1]} x2={E[0]} y2={E[1]} stroke={TANGERINE} strokeWidth={2.4} />
      <ParallelArrows x1={B[0]} y1={B[1]} x2={C[0]} y2={C[1]} n={1} color={LEAF} />
      <ParallelArrows x1={D[0]} y1={D[1]} x2={E[0]} y2={E[1]} n={1} color={LEAF} />
      <LabeledPoint x={A[0]} y={A[1]} label="A" dy={-6} color={SKY} />
      <LabeledPoint x={D[0]} y={D[1]} label="D" dx={-14} dy={2} color={TANGERINE} r={3.5} />
      <LabeledPoint x={E[0]} y={E[1]} label="E" dx={6} dy={2} color={TANGERINE} r={3.5} />
      <LabeledPoint x={B[0]} y={B[1]} label="B" dx={-12} dy={8} color={SKY} />
      <LabeledPoint x={C[0]} y={C[1]} label="C" dx={6} dy={8} color={SKY} />
      <text x={66} y={96} fontSize={10} fontWeight={700} fill={INK}>4</text>
      <text x={62} y={130} fontSize={10} fontWeight={700} fill={INK}>6</text>
      <text x={168} y={98} fontSize={10} fontWeight={700} fill={INK}>6</text>
      <text x={182} y={130} fontSize={10} fontWeight={700} fill={INK}>9</text>
      <text x={146} y={172} textAnchor="middle" fontSize={10.5} fontWeight={700} fill={INK}>DE ∥ BC ⇒ AD:DB = AE:EC</text>
    </svg>
  );
}

/** Right triangle with altitude to hypotenuse: the altitude is the geometric mean of the segments
 *  (p=4, q=9 → h=6), python-verified. */
function GeometricMean() {
  // right angle at top A; hypotenuse BC on the base; foot H splits it p=4,q=9 (scaled to px)
  const B: [number, number] = [40, 150], C: [number, number] = [230, 150];
  const p = 4, q = 9;
  const H: [number, number] = [B[0] + (p / (p + q)) * (C[0] - B[0]), 150];
  const A: [number, number] = [H[0], 150 - 6 / 13 * (C[0] - B[0])]; // altitude h=6 scaled
  return (
    <svg viewBox="0 0 300 175" role="img" aria-label="A right triangle with the altitude drawn from the right angle to the hypotenuse, splitting it into segments of length four and nine, with the altitude equal to their geometric mean, six">
      <title>Geometric mean altitude</title>
      <polygon points={`${A} ${B} ${C}`} fill={SKY} opacity={0.14} stroke={SKY} strokeWidth={2} />
      <line x1={A[0]} y1={A[1]} x2={H[0]} y2={H[1]} stroke={TANGERINE} strokeWidth={2.2} />
      <RightAngleBox vx={A[0]} vy={A[1]} ax={B[0]} ay={B[1]} bx={C[0]} by={C[1]} color={INK} />
      <RightAngleBox vx={H[0]} vy={H[1]} ax={A[0]} ay={A[1]} bx={C[0]} by={C[1]} color={LEAF} />
      <LabeledPoint x={A[0]} y={A[1]} label="A" dy={-6} color={SKY} />
      <LabeledPoint x={B[0]} y={B[1]} label="B" dx={-12} dy={8} color={SKY} />
      <LabeledPoint x={C[0]} y={C[1]} label="C" dx={6} dy={8} color={SKY} />
      <LabeledPoint x={H[0]} y={H[1]} label="H" dy={16} color={TANGERINE} r={3.5} />
      <text x={(B[0] + H[0]) / 2} y={165} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>4</text>
      <text x={(H[0] + C[0]) / 2} y={165} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>9</text>
      <text x={H[0] + 8} y={(A[1] + H[1]) / 2} fontSize={10} fontWeight={700} fill={TANGERINE}>h = 6</text>
      <text x={150} y={20} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>h = √(4·9) = 6</text>
    </svg>
  );
}

/** Indirect measurement: similar triangles from shadows — person 6 / shadow 4 = tree 30 / shadow 20. */
function IndirectMeasurement() {
  return (
    <svg viewBox="0 0 300 175" role="img" aria-label="Two similar right triangles formed by shadows: a short person with a short shadow beside a tall tree with a long shadow, used to find the tree's height by proportion">
      <title>Indirect measurement by similar triangles</title>
      <line x1={20} y1={150} x2={285} y2={150} stroke={INK} strokeWidth={1.5} />
      {/* person */}
      <line x1={60} y1={150} x2={60} y2={110} stroke={SKY} strokeWidth={3} />
      <line x1={60} y1={110} x2={100} y2={150} stroke={TANGERINE} strokeWidth={1.6} strokeDasharray="4 3" />
      <text x={40} y={132} fontSize={10} fontWeight={700} fill={SKY}>6</text>
      <text x={74} y={165} fontSize={10} fontWeight={700} fill={INK}>4</text>
      {/* tree */}
      <line x1={200} y1={150} x2={200} y2={40} stroke={BERRY} strokeWidth={4} />
      <line x1={200} y1={40} x2={285} y2={150} stroke={TANGERINE} strokeWidth={1.6} strokeDasharray="4 3" />
      <text x={178} y={98} fontSize={11} fontWeight={800} fill={BERRY}>h?</text>
      <text x={238} y={165} fontSize={10} fontWeight={700} fill={INK}>20</text>
      <text x={150} y={22} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>6 / 4 = h / 20 → h = 30</text>
    </svg>
  );
}


/** 45-45-90 and 30-60-90 side by side with exact side ratios (1:1:√2 and 1:√3:2).
 *  All coordinates computed from the ratios: 45er legs 70px each → hyp 70√2 ≈ 99px;
 *  30-60-90 short leg 55px → long leg 55√3 ≈ 95.26px, hyp 110px. */
function SpecialRightTriangles() {
  // 45-45-90: right angle at B=(110,150); legs to A=(40,150) and C=(110,80)
  const A: [number, number] = [40, 150], B: [number, number] = [110, 150], C: [number, number] = [110, 80];
  // 30-60-90: right angle at D=(178,150); long leg √3 to E=(273.26,150); short leg 1 up to F=(178,95)
  const D: [number, number] = [178, 150], E: [number, number] = [273.26, 150], F: [number, number] = [178, 95];
  return (
    <svg viewBox="0 0 320 185" role="img" className="mx-auto w-full max-w-sm">
      <title>Two special right triangles. A 45-45-90 triangle has two equal legs of length 1 and a hypotenuse of length square root of 2. A 30-60-90 triangle has a short leg of length 1 opposite the 30 degree angle, a long leg of length square root of 3 opposite the 60 degree angle, and a hypotenuse of length 2.</title>
      {/* 45-45-90 */}
      <polygon points={`${A} ${B} ${C}`} fill={SKY} opacity={0.16} stroke={SKY} strokeWidth={2} />
      <RightAngleBox vx={B[0]} vy={B[1]} ax={A[0]} ay={A[1]} bx={C[0]} by={C[1]} color={INK} />
      <AngleArc vx={A[0]} vy={A[1]} ax={B[0]} ay={B[1]} bx={C[0]} by={C[1]} r={16} color={TANGERINE} />
      <AngleArc vx={C[0]} vy={C[1]} ax={B[0]} ay={B[1]} bx={A[0]} by={A[1]} r={16} color={TANGERINE} />
      <text x={A[0] + 20} y={A[1] - 6} fontSize={10} fontWeight={700} fill={TANGERINE}>45°</text>
      <text x={C[0] - 8} y={C[1] + 24} fontSize={10} fontWeight={700} fill={TANGERINE}>45°</text>
      <text x={(A[0] + B[0]) / 2} y={165} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>1</text>
      <text x={B[0] + 6} y={(B[1] + C[1]) / 2 + 4} fontSize={10.5} fontWeight={800} fill={INK}>1</text>
      <text x={(A[0] + C[0]) / 2 - 14} y={(A[1] + C[1]) / 2 - 6} fontSize={10.5} fontWeight={800} fill={SKY}>√2</text>
      <text x={75} y={26} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>45-45-90</text>
      <text x={75} y={40} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.75}>1 : 1 : √2</text>
      {/* 30-60-90 */}
      <polygon points={`${D} ${E} ${F}`} fill={LEAF} opacity={0.16} stroke={LEAF} strokeWidth={2} />
      <RightAngleBox vx={D[0]} vy={D[1]} ax={E[0]} ay={E[1]} bx={F[0]} by={F[1]} color={INK} />
      <AngleArc vx={E[0]} vy={E[1]} ax={D[0]} ay={D[1]} bx={F[0]} by={F[1]} r={18} color={BERRY} />
      <AngleArc vx={F[0]} vy={F[1]} ax={D[0]} ay={D[1]} bx={E[0]} by={E[1]} r={14} color={TANGERINE} />
      <text x={E[0] - 34} y={E[1] - 8} fontSize={10} fontWeight={700} fill={BERRY}>30°</text>
      <text x={F[0] + 8} y={F[1] + 22} fontSize={10} fontWeight={700} fill={TANGERINE}>60°</text>
      <text x={(D[0] + E[0]) / 2} y={165} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>√3</text>
      <text x={D[0] - 10} y={(D[1] + F[1]) / 2 + 4} fontSize={10.5} fontWeight={800} fill={INK}>1</text>
      <text x={(E[0] + F[0]) / 2 + 12} y={(E[1] + F[1]) / 2 - 8} fontSize={10.5} fontWeight={800} fill={LEAF}>2</text>
      <text x={228} y={26} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>30-60-90</text>
      <text x={228} y={40} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.75}>1 : √3 : 2</text>
    </svg>
  );
}

/** ANIMATED CENTERPIECE: three nested similar right triangles sharing the same 35° angle.
 *  Hypotenuses 70, 110, 150 px; every opposite/hypotenuse ratio is sin 35° ≈ 0.574 — the
 *  triangles grow, the ratio never moves. Coordinates computed from cos/sin of 35°:
 *  cos35 ≈ 0.8192, sin35 ≈ 0.5736 → verticals at x = 57.3 / 90.1 / 122.9, heights 40.2 / 63.1 / 86.0.
 *  Motion (staggered fade-in of the larger triangles + ratio pulses) is additive only:
 *  the reduced-motion base render already shows the final state with all three triangles. */
function RatioConstantSweep() {
  const O: [number, number] = [34, 168];
  const tris = [
    { dx: 57.3, dy: 40.2, cls: "", color: SKY },
    { dx: 90.1, dy: 63.1, cls: "rcs-t2", color: LEAF },
    { dx: 122.9, dy: 86.0, cls: "rcs-t3", color: BERRY },
  ];
  const css = `@media (prefers-reduced-motion: no-preference){.rcs-t2{animation:rcs-in .5s ease-out .5s backwards}.rcs-t3{animation:rcs-in .5s ease-out 1s backwards}.rcs-r2{animation:rcs-in .4s ease-out .8s backwards}.rcs-r3{animation:rcs-in .4s ease-out 1.3s backwards}@keyframes rcs-in{from{opacity:0}to{opacity:1}}}`;
  return (
    <svg viewBox="0 0 320 195" role="img" className="mx-auto w-full max-w-sm">
      <title>Three nested similar right triangles sharing the same 35 degree angle at the left. Their hypotenuses have lengths 70, 110, and 150, but for every triangle the ratio of the opposite side to the hypotenuse is the same value, sine of 35 degrees, about 0.57. The triangle grows; the ratio never changes.</title>
      <style>{css}</style>
      {tris.map((t, i) => (
        <g key={i} className={t.cls}>
          <polygon points={`${O} ${O[0] + t.dx},${O[1]} ${O[0] + t.dx},${O[1] - t.dy}`} fill={t.color} opacity={0.13} stroke={t.color} strokeWidth={2} />
          <line x1={O[0] + t.dx} y1={O[1]} x2={O[0] + t.dx} y2={O[1] - t.dy} stroke={t.color} strokeWidth={2.6} />
        </g>
      ))}
      <RightAngleBox vx={O[0] + 57.3} vy={O[1]} ax={O[0]} ay={O[1]} bx={O[0] + 57.3} by={O[1] - 40.2} s={8} color={INK} />
      <path d={`M ${O[0] + 26} ${O[1]} A 26 26 0 0 0 ${O[0] + 26 * 0.8192} ${O[1] - 26 * 0.5736}`} fill="none" stroke={TANGERINE} strokeWidth={2.2} />
      <text x={O[0] + 32} y={O[1] - 8} fontSize={12} fontWeight={800} fill={TANGERINE}>35°</text>
      <text x={220} y={54} fontSize={10.5} fontWeight={800} fill={SKY}>40.2 / 70 = 0.574</text>
      <text x={220} y={78} fontSize={10.5} fontWeight={800} fill={LEAF} className="rcs-r2">63.1 / 110 = 0.574</text>
      <text x={220} y={102} fontSize={10.5} fontWeight={800} fill={BERRY} className="rcs-r3">86.0 / 150 = 0.574</text>
      <text x={220} y={130} fontSize={10.5} fontWeight={800} fill={INK}>opp/hyp = sin 35°</text>
      <text x={220} y={146} fontSize={10} fontWeight={700} fill={INK} opacity={0.75}>same angle → same ratio</text>
    </svg>
  );
}

/** Angle of elevation (looking up at a kite) and angle of depression (looking down at a boat)
 *  from one observer, both measured from the HORIZONTAL dashed sight line. */
function ElevationDepression() {
  const eye: [number, number] = [46, 100];
  const kite: [number, number] = [236, 28];
  const boat: [number, number] = [236, 162];
  return (
    <svg viewBox="0 0 320 190" role="img" className="mx-auto w-full max-w-sm">
      <title>An observer on a cliff looks along a horizontal dashed line. The angle of elevation opens upward from the horizontal to a kite above; the angle of depression opens downward from the horizontal to a boat below. Both angles are measured from the horizontal, never from the vertical.</title>
      <line x1={eye[0]} y1={eye[1]} x2={300} y2={eye[1]} stroke={INK} strokeWidth={1.4} strokeDasharray="5 4" />
      <text x={296} y={eye[1] - 6} textAnchor="end" fontSize={10} fontWeight={700} fill={INK} opacity={0.75}>horizontal</text>
      {/* lines of sight */}
      <line x1={eye[0]} y1={eye[1]} x2={kite[0]} y2={kite[1]} stroke={SKY} strokeWidth={2.2} />
      <line x1={eye[0]} y1={eye[1]} x2={boat[0]} y2={boat[1]} stroke={BERRY} strokeWidth={2.2} />
      <AngleArc vx={eye[0]} vy={eye[1]} ax={300} ay={eye[1]} bx={kite[0]} by={kite[1]} r={30} color={SKY} />
      <AngleArc vx={eye[0]} vy={eye[1]} ax={300} ay={eye[1]} bx={boat[0]} by={boat[1]} r={30} color={BERRY} />
      <text x={eye[0] + 40} y={eye[1] - 14} fontSize={10.5} fontWeight={800} fill={SKY}>elevation ↑</text>
      <text x={eye[0] + 40} y={eye[1] + 24} fontSize={10.5} fontWeight={800} fill={BERRY}>depression ↓</text>
      {/* observer */}
      <circle cx={eye[0]} cy={eye[1]} r={4} fill={TANGERINE} />
      <line x1={eye[0]} y1={eye[1] + 4} x2={eye[0]} y2={eye[1] + 26} stroke={TANGERINE} strokeWidth={3} />
      <rect x={eye[0] - 22} y={eye[1] + 26} width={44} height={56} fill={INK} opacity={0.15} />
      {/* kite */}
      <polygon points={`${kite[0]},${kite[1] - 10} ${kite[0] + 9},${kite[1]} ${kite[0]},${kite[1] + 12} ${kite[0] - 9},${kite[1]}`} fill={SKY} stroke={INK} strokeWidth={1} />
      {/* boat */}
      <path d={`M ${boat[0] - 16} ${boat[1]} L ${boat[0] + 16} ${boat[1]} L ${boat[0] + 8} ${boat[1] + 10} L ${boat[0] - 8} ${boat[1] + 10} Z`} fill={BERRY} />
      <line x1={boat[0]} y1={boat[1]} x2={boat[0]} y2={boat[1] - 14} stroke={BERRY} strokeWidth={2} />
      <text x={160} y={186} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.8}>both angles are measured from the horizontal</text>
    </svg>
  );
}

/** Solving a right triangle: hypotenuse 20, angle 34°, unknown opposite side x.
 *  Computed: x = 20·sin 34° ≈ 11.18 → 89.5 px at 8 px/unit; adjacent 16.58 → 132.6 px. */
function SolveRightTriangle() {
  const A: [number, number] = [40, 150], C: [number, number] = [172.6, 150], B: [number, number] = [172.6, 60.5];
  return (
    <svg viewBox="0 0 320 180" role="img" className="mx-auto w-full max-w-sm">
      <title>A right triangle with a 34 degree angle at the left vertex and a hypotenuse of length 20. The side opposite the 34 degree angle is unknown, labeled x. The setup sine of 34 degrees equals x over 20 solves it: x equals 20 times sine of 34 degrees, about 11.2.</title>
      <polygon points={`${A} ${C} ${B}`} fill={SKY} opacity={0.14} stroke={SKY} strokeWidth={2} />
      <RightAngleBox vx={C[0]} vy={C[1]} ax={A[0]} ay={A[1]} bx={B[0]} by={B[1]} color={INK} />
      <AngleArc vx={A[0]} vy={A[1]} ax={C[0]} ay={C[1]} bx={B[0]} by={B[1]} r={24} color={TANGERINE} />
      <text x={A[0] + 30} y={A[1] - 8} fontSize={11} fontWeight={800} fill={TANGERINE}>34°</text>
      <line x1={C[0]} y1={C[1]} x2={B[0]} y2={B[1]} stroke={BERRY} strokeWidth={3} strokeLinecap="round" />
      <text x={C[0] + 10} y={(C[1] + B[1]) / 2 + 4} fontSize={12} fontWeight={800} fill={BERRY}>x</text>
      <text x={(A[0] + B[0]) / 2 - 16} y={(A[1] + B[1]) / 2 - 12} fontSize={10.5} fontWeight={800} fill={SKY}>hyp = 20</text>
      <text x={(A[0] + C[0]) / 2} y={166} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.8}>adjacent</text>
      <text x={252} y={80} fontSize={10.5} fontWeight={800} fill={INK}>sin 34° = x/20</text>
      <text x={252} y={102} fontSize={10.5} fontWeight={800} fill={BERRY}>x ≈ 11.2</text>
      <text x={160} y={20} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>opposite ÷ hypotenuse → use SINE</text>
    </svg>
  );
}

/** An oblique (non-right) triangle with sides a, b, c opposite angles A, B, C, captioned
 *  with the law of sines and the law of cosines — the tools when no right angle exists. */
function ObliqueTriangleLaws() {
  const A: [number, number] = [42, 152], B: [number, number] = [268, 152], C: [number, number] = [190, 46];
  return (
    <svg viewBox="0 0 320 200" role="img" className="mx-auto w-full max-w-sm">
      <title>A triangle with no right angle. Its vertices are labeled with capital A, B, and C, and each side is labeled with the lowercase letter of the opposite angle: side a is opposite angle A, side b opposite angle B, side c opposite angle C. Captions read: law of sines, a over sine A equals b over sine B equals c over sine C; law of cosines, c squared equals a squared plus b squared minus 2 a b cosine C.</title>
      <polygon points={`${A} ${B} ${C}`} fill={LEAF} opacity={0.13} stroke={LEAF} strokeWidth={2} />
      <AngleArc vx={A[0]} vy={A[1]} ax={B[0]} ay={B[1]} bx={C[0]} by={C[1]} r={18} color={SKY} />
      <AngleArc vx={B[0]} vy={B[1]} ax={A[0]} ay={A[1]} bx={C[0]} by={C[1]} r={18} color={TANGERINE} />
      <AngleArc vx={C[0]} vy={C[1]} ax={A[0]} ay={A[1]} bx={B[0]} by={B[1]} r={18} color={BERRY} />
      <LabeledPoint x={A[0]} y={A[1]} label="A" dx={-12} dy={8} color={SKY} />
      <LabeledPoint x={B[0]} y={B[1]} label="B" dx={8} dy={8} color={TANGERINE} />
      <LabeledPoint x={C[0]} y={C[1]} label="C" dy={-8} color={BERRY} />
      <text x={(B[0] + C[0]) / 2 + 12} y={(B[1] + C[1]) / 2} fontSize={11} fontWeight={800} fill={SKY}>a</text>
      <text x={(A[0] + C[0]) / 2 - 14} y={(A[1] + C[1]) / 2 - 4} fontSize={11} fontWeight={800} fill={TANGERINE}>b</text>
      <text x={(A[0] + B[0]) / 2} y={A[1] + 15} textAnchor="middle" fontSize={11} fontWeight={800} fill={BERRY}>c</text>
      <text x={160} y={180} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>a/sin A = b/sin B = c/sin C</text>
      <text x={160} y={196} textAnchor="middle" fontSize={10.5} fontWeight={800} fill={INK}>c² = a² + b² − 2ab·cos C</text>
      <text x={160} y={20} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.8}>lowercase side sits OPPOSITE its uppercase angle</text>
    </svg>
  );
}


