/** A single-unit-scale bar graph: each gridline is worth exactly 1, no key multiplier. */
function SingleScaleGraph() {
  const bars = [3, 6, 4];
  const labels = ["cats", "dogs", "birds"];
  /* S241 (D-16, rules A4/C1): the caption said "each line = 1" and the <title> said "each
   * gridline is worth exactly one" over a chart that drew NO gridlines and numbered its axis
   * 0 · 2 · 4 · 6. The one thing the lesson asks the learner to do — "read straight up from the
   * top of the bar to the number beside it" — was undrawable for the cats bar at 3, and the
   * claim was about lines that did not exist. Now every unit HAS a line and every line HAS its
   * number: `u` is the unit, one gridline per unit, one label per gridline. The taller viewBox
   * buys the 14-unit row pitch those seven labels need to stay clear of each other. */
  const u = 14, y0 = 118;
  const ticks = [0, 1, 2, 3, 4, 5, 6];
  return (
    <svg viewBox="0 0 220 150" role="img" className="mx-auto w-full max-w-sm">
      <title>A bar graph with three bars for cats, dogs, and birds, where each gridline is worth exactly one -- the bar for dogs reaches six, showing six votes directly.</title>
      {ticks.filter((v) => v > 0).map((v) => (
        <line key={v} x1={30} y1={y0 - v * u} x2={210} y2={y0 - v * u} stroke={INK} strokeWidth={0.8} opacity={0.3} />
      ))}
      <line x1={30} y1={y0 - 6 * u - 6} x2={30} y2={y0} stroke={INK} strokeWidth={1.2} />
      <line x1={30} y1={y0} x2={210} y2={y0} stroke={INK} strokeWidth={1.2} />
      {ticks.map((v) => (
        <text key={v} x={24} y={y0 - v * u + 3.5} textAnchor="end" fontSize={10} fill={INK}>{v}</text>
      ))}
      {bars.map((v, i) => (
        <g key={i}>
          <rect x={55 + i * 50} y={y0 - v * u} width={30} height={v * u} fill={SKY} opacity={0.85} stroke={INK} strokeWidth={1} />
          <text x={70 + i * 50} y={134} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>{labels[i]}</text>
        </g>
      ))}
      <text x={110} y={20} textAnchor="middle" fontSize={10} fontWeight={700} fill={TANGERINE}>each line = 1</text>
    </svg>
  );
}

/** A heptagon, an octagon, and a square pyramid -- shapes beyond the G1 vocabulary. */
function ExtendedShapes() {
  const heptPts = Array.from({ length: 7 }, (_, i) => {
    const a = ((2 * Math.PI) / 7) * i - Math.PI / 2;
    return [50 + 26 * Math.cos(a), 50 + 26 * Math.sin(a)];
  });
  const octPts = Array.from({ length: 8 }, (_, i) => {
    const a = ((2 * Math.PI) / 8) * i - Math.PI / 2;
    return [150 + 26 * Math.cos(a), 50 + 26 * Math.sin(a)];
  });
  return (
    <svg viewBox="0 0 280 130" role="img" className="mx-auto w-full max-w-sm">
      <title>A heptagon with seven sides, an octagon with eight sides, and a square pyramid with a square base and four triangular faces meeting at a point.</title>
      <polygon points={heptPts.map((p) => p.join(",")).join(" ")} fill="none" stroke={SKY} strokeWidth={3} />
      <text x={50} y={95} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>heptagon: 7 sides</text>
      <polygon points={octPts.map((p) => p.join(",")).join(" ")} fill="none" stroke={SKY} strokeWidth={3} />
      <text x={150} y={112} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>octagon: 8 sides</text>
      <polygon points="205,70 245,70 235,60 215,60" fill={SKY} opacity={0.6} stroke={INK} strokeWidth={1} />
      <polygon points="205,70 225,25 215,60" fill={TANGERINE} opacity={0.7} stroke={INK} strokeWidth={1} />
      <polygon points="245,70 225,25 235,60" fill={TANGERINE} opacity={0.5} stroke={INK} strokeWidth={1} />
      <text x={225} y={95} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>square pyramid</text>
    </svg>
  );
}

/** A rectangle partitioned into a grid of unit squares -- 3 rows by 4 columns. */
