          <rect key={`${r}-${c}`} x={30 + c * 32} y={20 + r * 28} width={30} height={26}
            fill={(r + c) % 2 === 0 ? SKY : TANGERINE} opacity={0.6} stroke={INK} strokeWidth={1} />
