/** Halves, thirds, and fourths of identical circles, side by side for size comparison. */
function ThirdsCompare() {
  const wedge = (cx: number, n: number, fill: string) => {
    const paths = [];
    for (let i = 0; i < n; i++) {
      const a0 = (2 * Math.PI * i) / n - Math.PI / 2;
      const a1 = (2 * Math.PI * (i + 1)) / n - Math.PI / 2;
      const x0 = cx + 26 * Math.cos(a0), y0 = 45 + 26 * Math.sin(a0);
      const x1 = cx + 26 * Math.cos(a1), y1 = 45 + 26 * Math.sin(a1);
      paths.push(
        <path key={i} d={`M ${cx} 45 L ${x0} ${y0} A 26 26 0 0 1 ${x1} ${y1} Z`}
          fill={i % 2 === 0 ? fill : "none"} opacity={0.75} stroke={INK} strokeWidth={1} />
      );
    }
    return paths;
  };
  return (
    <svg viewBox="0 0 260 100" role="img" className="mx-auto w-full max-w-sm">
      <title>Three identical circles split into halves, thirds, and fourths, showing that more equal parts makes each piece smaller.</title>
      {wedge(45, 2, SKY)}
      <text x={45} y={85} textAnchor="middle" fontSize={11} fontWeight={700} fill={SKY}>halves</text>
      {wedge(130, 3, TANGERINE)}
      <text x={130} y={85} textAnchor="middle" fontSize={11} fontWeight={700} fill={TANGERINE}>thirds</text>
      {wedge(215, 4, LEAF)}
      <text x={215} y={85} textAnchor="middle" fontSize={11} fontWeight={700} fill={LEAF}>fourths</text>
    </svg>
  );
}

/** A fractional unit rate: 1/2 mile in 1/4 hour, divided out to 2 miles per hour. */
function FractionUnitRate() {
  return (
    <svg viewBox="0 0 320 120" role="img" className="mx-auto w-full max-w-sm">
      <title>One half mile in one quarter hour divides out to a unit rate of two miles per hour.</title>
      <rect x={20} y={24} width={110} height={30} rx={9} fill="#EAF2FC" stroke={INK} strokeWidth={1.5} />
      <text x={75} y={44} textAnchor="middle" fontSize={12} fontWeight={800} fill={INK}>1/2 mile</text>
      <rect x={20} y={64} width={110} height={30} rx={9} fill="#FFE9D6" stroke={INK} strokeWidth={1.5} />
      <text x={75} y={84} textAnchor="middle" fontSize={12} fontWeight={800} fill={INK}>1/4 hour</text>
      <text x={150} y={44} fontSize={11} fontWeight={800} fill={LEAF}>÷ 1/4 →</text>
      <text x={150} y={84} fontSize={11} fontWeight={800} fill={LEAF}>÷ 1/4 →</text>
      <rect x={210} y={24} width={94} height={30} rx={9} fill="#EAF2FC" stroke={SKY} strokeWidth={2} />
      <text x={257} y={44} textAnchor="middle" fontSize={12} fontWeight={800} fill={SKY}>2 miles</text>
      <rect x={210} y={64} width={94} height={30} rx={9} fill="#FFE9D6" stroke={SKY} strokeWidth={2} />
      <text x={257} y={84} textAnchor="middle" fontSize={12} fontWeight={800} fill={SKY}>1 hour</text>
      <text x={160} y={110} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>unit rate: 2 miles per hour</text>
    </svg>
  );
}

/** Two small tables side by side: one proportional (every ratio equal), one not. */
function ProportionalityTest() {
  const good: Array<[number, number]> = [[2, 6], [3, 9], [5, 15]];
  const bad: Array<[number, number]> = [[2, 6], [3, 10], [5, 15]];
  const renderTable = (rows: Array<[number, number]>, ox: number, ok: boolean) => (
    <g>
      <text x={ox + 29} y={14} textAnchor="middle" fontSize={11} fontWeight={800} fill={ok ? LEAF : BERRY}>
        {ok ? "proportional" : "not proportional"}
      </text>
      {rows.map(([a, b], i) => (
        <g key={i}>
          <rect x={ox} y={22 + i * 24} width={29} height={22} fill="#EAF2FC" stroke={INK} strokeWidth={1} />
          <rect x={ox + 29} y={22 + i * 24} width={29} height={22} fill="#FFE9D6" stroke={INK} strokeWidth={1} />
          <text x={ox + 14.5} y={22 + i * 24 + 15} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>{a}</text>
          <text x={ox + 43.5} y={22 + i * 24 + 15} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>{b}</text>
        </g>
      ))}
    </g>
  );
  return (
    <svg viewBox="0 0 260 110" role="img" className="mx-auto w-full max-w-sm">
      <title>Two tables compared: one where every ratio equals three, so it is proportional, and one where the middle row breaks the pattern, so it is not proportional.</title>
      {renderTable(good, 20, true)}
      {renderTable(bad, 160, false)}
    </svg>
  );
}

/** A proportional line through the origin, with the unit-rate point (1,k) marked. */
function ProportionalLine() {
  const pts = [[0, 0], [1, 2], [2, 4], [3, 6]];
  const toSvg = ([x, y]: number[]) => [30 + x * 40, 130 - y * 18];
  const svgPts = pts.map(toSvg);
  return (
    <svg viewBox="0 0 200 140" role="img" className="mx-auto w-full max-w-xs">
      <title>A proportional line passing through the origin and the points one-two, two-four, and three-six, showing the unit rate two at the point one-two.</title>
      <line x1={25} y1={130} x2={185} y2={130} stroke={INK} strokeWidth={1.2} />
      <line x1={30} y1={135} x2={30} y2={10} stroke={INK} strokeWidth={1.2} />
      <polyline points={svgPts.map((p) => p.join(",")).join(" ")} fill="none" stroke={SKY} strokeWidth={2.5} />
      {svgPts.map(([x, y], i) => (
        <circle key={i} cx={x} cy={y} r={4} fill={i === 0 ? INK : TANGERINE} stroke={INK} strokeWidth={1} />
      ))}
      <text x={30} y={144} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK}>(0,0)</text>
      <text x={70} y={100} textAnchor="middle" fontSize={10} fontWeight={700} fill={TANGERINE}>(1,2) = unit rate</text>
    </svg>
  );
}

