/** pra Ch4: sign chart of (x+1)(x−2) — cuts at −1 and 2, signs +,−,+ (computed both routes). */
function PraSignchartIntro() {
  return (
    <svg viewBox="0 0 340 150" role="img" aria-label="A sign chart for the product x plus 1 times x minus 2: the number line is cut at x equals negative 1 and x equals 2, with a plus sign on the left interval, a minus sign between the cuts, and a plus sign on the right interval.">
      <title>Sign chart with cuts at −1 and 2 showing the plus, minus, plus pattern.</title>
      <SignChart x={20} y={52} width={300} criticalLabels={["−1", "2"]} signs={["+", "-", "+"]} />
      <text x={70} y={100} fontSize={11} fill={LEAF} textAnchor="middle">kept</text>
      <text x={170} y={100} fontSize={11} fill={BERRY} textAnchor="middle">rejected</text>
      <text x={270} y={100} fontSize={11} fill={LEAF} textAnchor="middle">kept</text>
      <text x={20} y={128} fontSize={12} fill={INK}>(x + 1)(x − 2) &gt; 0 on the highlighted intervals</text>
    </svg>
  );
}

/** pra Ch5: rational sign chart — open circle at the excluded value −1, closed dot at the zero 3 (computed signs). */
function PraExcludedOpen() {
  return (
    <svg viewBox="0 0 340 160" role="img" aria-label="Sign chart of x minus 3 over x plus 1 with cuts at negative 1 and 3 and signs plus, minus, plus. The cut at negative 1 is drawn as an open circle because the expression is undefined there; the cut at 3 is a closed dot because the expression equals zero there.">
      <title>Two kinds of cut points: an open excluded value and a closable zero.</title>
      <SignChart x={20} y={56} width={300} criticalLabels={["−1", "3"]} signs={["+", "-", "+"]} />
      <circle cx={120} cy={56} r={6} fill="#FFFFFF" stroke={BERRY} strokeWidth={2.5} />
      <circle cx={220} cy={56} r={6} fill={LEAF} />
      <text x={120} y={104} fontSize={11} fill={BERRY} textAnchor="middle">excluded: never joins</text>
      <text x={240} y={122} fontSize={11} fill={LEAF} textAnchor="middle">zero: joins under ≥ / ≤</text>
    </svg>
  );
}

