/** ti Ch4: the three equal faces of cos 2θ, each labeled by what it needs (static reference). */
function TiCos2Faces() {
  return (
    <svg viewBox="0 0 340 150" role="img" aria-label="Three equal forms of cosine of two theta shown side by side: cosine squared minus sine squared, one minus two sine squared labeled sine-only, and two cosine squared minus one labeled cosine-only.">
      <title>The three equal faces of cosine of two theta.</title>
      <text x={170} y={24} fontSize={12} fontWeight={700} fill={INK} textAnchor="middle">cos 2θ =</text>
      <g>
        <rect x={12} y={40} width={100} height={62} rx={9} fill="none" stroke={SKY} strokeWidth={2} />
        <text x={62} y={68} fontSize={12} fontWeight={600} fill={SKY} textAnchor="middle">cos²θ − sin²θ</text>
        <text x={62} y={90} fontSize={10} fill={INK} textAnchor="middle">the parent</text>
      </g>
      <g>
        <rect x={120} y={40} width={100} height={62} rx={9} fill="none" stroke={TANGERINE} strokeWidth={2} />
        <text x={170} y={68} fontSize={12} fontWeight={600} fill={TANGERINE} textAnchor="middle">1 − 2sin²θ</text>
        <text x={170} y={90} fontSize={10} fill={INK} textAnchor="middle">sine only</text>
      </g>
      <g>
        <rect x={228} y={40} width={100} height={62} rx={9} fill="none" stroke={LEAF} strokeWidth={2} />
        <text x={278} y={68} fontSize={12} fontWeight={600} fill={LEAF} textAnchor="middle">2cos²θ − 1</text>
        <text x={278} y={90} fontSize={10} fill={INK} textAnchor="middle">cosine only</text>
      </g>
      <text x={170} y={128} fontSize={11} fill={INK} textAnchor="middle">reverse → power reduction: sin²θ = (1 − cos2θ)/2</text>
    </svg>
  );
}

/** ti Ch5: a trig quadratic factored into two branches, each yielding its solutions (static). */
function TiBranchTree() {
  return (
    <svg viewBox="0 0 340 180" role="img" aria-label="A solution tree: the equation two sine squared x minus sine x minus one equals zero factors into two branches. The left branch, two sine x plus one equals zero, gives sine x equals negative one half with solutions seven pi over six and eleven pi over six. The right branch, sine x minus one equals zero, gives sine x equals one with solution pi over two.">
      <title>Factoring a trig quadratic into two solution branches.</title>
      <rect x={92} y={12} width={156} height={30} rx={8} fill={SKY} opacity={0.92} />
      <text x={170} y={31} fontSize={12} fontWeight={700} fill="#FFFFFF" textAnchor="middle">2sin²x − sin x − 1 = 0</text>
      <text x={170} y={57} fontSize={11} fill={INK} textAnchor="middle">factor (u = sin x)</text>
      <line x1={150} y1={62} x2={80} y2={82} stroke={INK} strokeWidth={1.5} />
      <line x1={190} y1={62} x2={262} y2={82} stroke={INK} strokeWidth={1.5} />
      <g>
        <rect x={16} y={84} width={128} height={30} rx={7} fill="none" stroke={TANGERINE} strokeWidth={2} />
        <text x={80} y={103} fontSize={11} fontWeight={600} fill={TANGERINE} textAnchor="middle">2sin x + 1 = 0</text>
        <text x={80} y={134} fontSize={11} fill={INK} textAnchor="middle">sin x = −1/2</text>
        <text x={80} y={154} fontSize={11} fontWeight={600} fill={BERRY} textAnchor="middle">7π/6, 11π/6</text>
      </g>
      <g>
        <rect x={198} y={84} width={128} height={30} rx={7} fill="none" stroke={LEAF} strokeWidth={2} />
        <text x={262} y={103} fontSize={11} fontWeight={600} fill={LEAF} textAnchor="middle">sin x − 1 = 0</text>
        <text x={262} y={134} fontSize={11} fill={INK} textAnchor="middle">sin x = 1</text>
        <text x={262} y={154} fontSize={11} fontWeight={600} fill={BERRY} textAnchor="middle">π/2</text>
      </g>
      <text x={170} y={174} fontSize={11} fill={INK} textAnchor="middle">three solutions on [0, 2π)</text>
    </svg>
  );
}

