function LcContinuityConditions() {
  const cond = (y: number, n: string, text: string) => (
    <g>
      <circle cx={26} cy={y} r={9} fill={LEAF} opacity={0.9} />
      <text x={26} y={y + 4} fontSize="11" fontWeight="700" fill="#ffffff" textAnchor="middle">{n}</text>
      <text x={42} y={y + 4} fontSize="10" fill={INK}>{text}</text>
    </g>
  );
  return (
    <svg viewBox="0 0 220 130" role="img" aria-label="A checklist of the three conditions for a function to be continuous at x equals a: first, f of a is defined; second, the limit as x approaches a exists; third, the limit equals f of a. All three must hold.">
      <title>The three conditions for continuity at a point.</title>
      <text x={14} y={16} fontSize="11" fontWeight="700" fill={INK}>Continuous at x = a when ALL hold:</text>
      {cond(40, "1", "f(a) is defined")}
      {cond(68, "2", "lim (x→a) f(x) exists")}
      {cond(96, "3", "lim (x→a) f(x) = f(a)")}
      <text x={14} y={122} fontSize="10" fill={BERRY}>break any one → discontinuous</text>
    </svg>
  );
}

