/** Precalc band primitives gallery — the render-test gate for the five shared helpers.
 * Coordinates are computed, not eyeballed: the unit-circle point sits at theta=2.2 rad; the
 * sign chart shows f(x)=(x+1)(x-2) with signs verified +,-,+ at x=-2,0,3. */
function PrecalcPrimitivesGallery() {
  const theta = 2.2;
  return (
    <svg viewBox="0 0 360 300" role="img" aria-label="Gallery of the precalculus band's shared figure primitives: unit circle, asymptote, vector with components, sign chart, and focus marker.">
      <title>Precalculus primitives gallery</title>
      <UnitCircleFrame cx={80} cy={80} r={52} theta={theta} />
      <AsymptoteLine x1={200} y1={20} x2={200} y2={140} label="x = 2" />
      <VectorArrow x1={240} y1={130} x2={330} y2={60} label="v" components ox={240} oy={130} />
      <SignChart x={30} y={210} width={300} criticalLabels={["−1", "2"]} signs={["+", "-", "+"]} />
      <FocusMarker x={80} y={265} label="F" />
      <text x={100} y={270} fontSize={11} fill={INK}>focus marker</text>
    </svg>
  );
}

