/** The complement bar: P(A) and 1 − P(A) fill the whole of 1. */
function CprComplementBar() {
  return (
    <svg viewBox="0 0 300 110" role="img" className="mx-auto w-full max-w-sm">
      <title>A bar of total probability 1 split into event A on the left and not-A on the right, showing that P(A) plus P(not A) equals 1.</title>
      <rect x={20} y={34} width={72} height={34} fill={TANGERINE} opacity={0.85} stroke={INK} strokeWidth={1.4} />
      <rect x={92} y={34} width={188} height={34} fill={SKY} opacity={0.25} stroke={INK} strokeWidth={1.4} />
      <text x={56} y={56} textAnchor="middle" fontSize={11} fontWeight={700} fill="white">
        A
      </text>
      <text x={186} y={56} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>
        not A
      </text>
      <text x={56} y={86} textAnchor="middle" fontSize={11} fill={INK}>
        P(A)
      </text>
      <text x={186} y={86} textAnchor="middle" fontSize={11} fill={INK}>
        1 − P(A)
      </text>
      <line x1={20} y1={24} x2={280} y2={24} stroke={INK} strokeWidth={1.2} />
      <text x={150} y={16} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>
        everything: probability 1
      </text>
      <text x={150} y={104} textAnchor="middle" fontSize={10} fill={INK} opacity={0.8}>
        the two pieces never overlap and never leave a gap
      </text>
    </svg>
  );
}

/** The 36 two-dice outcomes; the 11 containing a six are shaded (a row plus a column, sharing one cell). */
function CprAtLeastOneGrid() {
  const cells: { a: number; b: number }[] = [];
  for (let a = 1; a <= 6; a += 1) for (let b = 1; b <= 6; b += 1) cells.push({ a, b });
  return (
    <svg viewBox="0 0 260 190" role="img" className="mx-auto w-full max-w-xs">
      <title>The 36 outcomes of rolling two dice as a 6 by 6 grid. The last row and last column are shaded because they contain a six; they share the corner cell, so 6 plus 6 minus 1 equals 11 shaded outcomes.</title>
      <text x={130} y={14} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>
        at least one 6: 6 + 6 − 1 = 11 of 36
      </text>
      {cells.map(({ a, b }) => {
        const hit = a === 6 || b === 6;
        const corner = a === 6 && b === 6;
        return (
          <rect
            key={`${a}-${b}`}
            x={34 + (a - 1) * 30}
            y={24 + (6 - b) * 24}
            width={28}
            height={22}
            rx={4}
            fill={corner ? BERRY : hit ? SKY : "white"}
            opacity={corner ? 0.85 : hit ? 0.55 : 1}
            stroke={INK}
            strokeWidth={1}
          />
        );
      })}
      <text x={20} y={100} textAnchor="middle" fontSize={10} fill={INK}>
        die 2
      </text>
      <text x={130} y={186} textAnchor="middle" fontSize={10} fill={INK}>
        die 1
      </text>
      <text x={130} y={172} textAnchor="middle" fontSize={10} fill={BERRY}>
        the corner (6, 6) is on both lists — count it once
      </text>
    </svg>
  );
}

