/** Why the union subtracts the middle: adding the circles counts the overlap twice. */
function CprDoubleCount() {
  return (
    <svg viewBox="0 0 300 150" role="img" className="mx-auto w-full max-w-sm">
      <title>Adding the size of circle A to the size of circle B counts the overlapping middle region twice, so the union subtracts that middle once.</title>
      <circle cx={116} cy={70} r={50} fill={SKY} opacity={0.2} stroke={SKY} strokeWidth={1.8} />
      <circle cx={184} cy={70} r={50} fill={TANGERINE} opacity={0.2} stroke={TANGERINE} strokeWidth={1.8} />
      <path d="M150 26 A50 50 0 0 0 150 114 A50 50 0 0 0 150 26 Z" fill={BERRY} opacity={0.45} stroke={BERRY} strokeWidth={1.4} />
      <text x={150} y={66} textAnchor="middle" fontSize={10} fontWeight={700} fill="white">
        counted
      </text>
      <text x={150} y={80} textAnchor="middle" fontSize={10} fontWeight={700} fill="white">
        twice
      </text>
      <text x={86} y={74} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>
        A
      </text>
      <text x={214} y={74} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>
        B
      </text>
      <text x={150} y={20} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>
        |A| + |B| overshoots the union
      </text>
      <text x={150} y={140} textAnchor="middle" fontSize={11} fill={INK}>
        |A ∪ B| = |A| + |B| − |A ∩ B|
      </text>
    </svg>
  );
}

