function SiSamplingDistSizes() {
  const truth = 0.6;
  const piles: Array<{ n: number; spread: number; y: number; label: string }> = [
    { n: 10, spread: 0.31, y: 44, label: "n = 10" },
    { n: 40, spread: 0.155, y: 82, label: "n = 40" },
    { n: 100, spread: 0.098, y: 120, label: "n = 100" },
  ];
  const X = (p: number) => 70 + p * 230;
  return (
    <svg viewBox="0 0 330 165" role="img" className="mx-auto w-full max-w-md">
      <title>Three piles of poll results at sample sizes ten, forty and one hundred. All three centre on the true sixty percent, but the pile narrows sharply as the sample grows: quadrupling the sample halves the spread.</title>
      <text x={165} y={13} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>
        the pile centres on the truth — and narrows with n
      </text>
      <line x1={X(truth)} y1={22} x2={X(truth)} y2={140} stroke={TANGERINE} strokeWidth={2} strokeDasharray="4 3" />
      <text x={X(truth)} y={155} textAnchor="middle" fontSize={10} fontWeight={700} fill={TANGERINE}>
        truth 60%
      </text>
      {piles.map((p) => {
        const dots = Array.from({ length: 21 }, (_, i) => {
          const t = (i - 10) / 10;
          const w = Math.pow(Math.abs(t), 1.6);
          return truth + t * p.spread * (1 - 0.25 * w);
        });
        return (
          <g key={p.n}>
            <text x={10} y={p.y + 4} fontSize={10} fontWeight={700} fill={INK}>
              {p.label}
            </text>
            <line x1={X(truth - p.spread)} y1={p.y} x2={X(truth + p.spread)} y2={p.y} stroke={SKY} strokeWidth={1} strokeOpacity={0.35} />
            {dots.map((v, i) => (
              <circle key={i} cx={X(v)} cy={p.y - (i % 3) * 3.4} r={2.3} fill={SKY} fillOpacity={0.75} />
            ))}
            <text x={X(truth + p.spread) + 6} y={p.y + 4} fontSize={10} fill={INK} fillOpacity={0.7}>
              ±{Math.round(p.spread * 100)}
            </text>
          </g>
        );
      })}
      <line x1={70} y1={140} x2={300} y2={140} stroke={INK} strokeWidth={1} strokeOpacity={0.4} />
    </svg>
  );
}

function SiAccuracyPrecision() {
  const boards = [
    { t: "low bias, high spread", cx: 46, cy: 60, off: [0, 0], sp: 15, c: SKY },
    { t: "low bias, low spread", cx: 130, cy: 60, off: [0, 0], sp: 5, c: LEAF },
    { t: "biased, high spread", cx: 214, cy: 60, off: [12, -9], sp: 15, c: BERRY },
    { t: "biased, low spread", cx: 298, cy: 60, off: [12, -9], sp: 5, c: BERRY },
  ];
  return (
    <svg viewBox="0 0 340 150" role="img" className="mx-auto w-full max-w-md">
      <title>Four dartboards. Random sampling error scatters the darts around the bullseye; bias shifts the whole cluster off it. A bigger sample tightens the cluster but never re-aims it, so the two bottom-right boards stay wrong.</title>
      <text x={170} y={13} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>
        bias moves the cluster · sample size only tightens it
      </text>
      {boards.map((b, bi) => (
        <g key={b.t}>
          <circle cx={b.cx} cy={b.cy} r={30} fill="none" stroke={INK} strokeWidth={1} strokeOpacity={0.35} />
          <circle cx={b.cx} cy={b.cy} r={18} fill="none" stroke={INK} strokeWidth={1} strokeOpacity={0.25} />
          <circle cx={b.cx} cy={b.cy} r={6} fill={TANGERINE} opacity={0.85} />
          {Array.from({ length: 9 }, (_, i) => {
            const a = (i * 2.7 + bi) % (2 * Math.PI);
            const r = ((i * 31 + bi * 7) % 100) / 100;
            return (
              <circle
                key={i}
                cx={b.cx + b.off[0] + Math.cos(a) * r * b.sp}
                cy={b.cy + b.off[1] + Math.sin(a) * r * b.sp}
                r={2.4}
                fill={b.c}
                fillOpacity={0.9}
              />
            );
          })}
          <text x={b.cx} y={106} textAnchor="middle" fontSize={10} fontWeight={700} fill={b.c}>
            {b.t.split(", ")[0]}
          </text>
          <text x={b.cx} y={120} textAnchor="middle" fontSize={10} fill={INK} fillOpacity={0.75}>
            {b.t.split(", ")[1]}
          </text>
        </g>
      ))}
      <text x={170} y={140} textAnchor="middle" fontSize={10} fill={INK} opacity={0.8}>
        the bullseye is the truth · each dart is one sample's estimate
      </text>
    </svg>
  );
}

