/* ---- S200 §22: absolute-value-piecewise (18) ---- */
/** Shared mini number line for the |x| family. */
function S200NL({ y = 62, from = -8, to = 8 }: { y?: number; from?: number; to?: number }) {
  const px = (v: number) => 20 + ((v - from) / (to - from)) * 260;
  return (
    <>
      <line x1={20} y1={y} x2={280} y2={y} stroke={INK} strokeWidth={1.4} />
      {Array.from({ length: to - from + 1 }, (_, i) => from + i).map((v) => (
        <g key={v}>
          <line x1={px(v)} y1={y - 4} x2={px(v)} y2={y + 4} stroke={INK} strokeWidth={v === 0 ? 1.8 : 1} opacity={v === 0 ? 1 : 0.5} />
          {v % 4 === 0 && <text x={px(v)} y={y + 18} textAnchor="middle" fontSize={10} fontWeight={700} fill={INK} opacity={0.75}>{v}</text>}
        </g>
      ))}
    </>
  );
}
const s200px = (v: number, from = -8, to = 8) => 20 + ((v - from) / (to - from)) * 260;
/** Small V-shaped |x| axes used across the graphing steps. */
function S200VAxes({ children, title }: { children: React.ReactNode; title: string }) {
  return (
    <svg viewBox="0 0 300 140" role="img" className="mx-auto w-full max-w-sm">
      <title>{title}</title>
      <line x1={20} y1={110} x2={280} y2={110} stroke={INK} strokeWidth={1.2} opacity={0.6} />
      <line x1={150} y1={16} x2={150} y2={124} stroke={INK} strokeWidth={1.2} opacity={0.6} />
      {children}
    </svg>
  );
}

