function Rr6TableToPlane() {
  const ox = 168, oy = 126, u = 19;
  const px = (x: number) => ox + x * u, py = (y: number) => oy - y * u;
  const pairs: Array<[number, number]> = [[1, 2], [2, 4], [3, 6]];
  return (
    <svg viewBox="0 0 300 150" role="img" className="mx-auto w-full max-w-sm">
      <title>A ratio table of one to two, two to four and three to six, with each row carried across and plotted as a point on the coordinate plane.</title>
      <text x={64} y={18} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>each row is a point</text>
      <rect x={16} y={26} width={96} height={22} fill={SKY} fillOpacity={0.18} stroke={SKY} strokeWidth={1.3} />
      <text x={40} y={41} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>cups</text>
      <text x={88} y={41} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>scoops</text>
      {pairs.map(([a, b], i) => (
        <g key={a}>
          <rect x={16} y={48 + i * 22} width={96} height={22} fill="none" stroke={INK} strokeWidth={1} opacity={0.4} />
          <text x={40} y={63 + i * 22} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>{a}</text>
          <text x={88} y={63 + i * 22} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>{b}</text>
          <path d={`M116 ${58 + i * 22} L${px(a) - 6} ${py(b) + 2}`} stroke={TANGERINE} strokeWidth={1} strokeDasharray="3 3" opacity={0.8} />
        </g>
      ))}
      <line x1={px(0)} y1={py(0)} x2={px(4)} y2={py(0)} stroke={INK} strokeWidth={1.3} />
      <line x1={px(0)} y1={py(0)} x2={px(0)} y2={py(6.4)} stroke={INK} strokeWidth={1.3} />
      {pairs.map(([a, b]) => <circle key={a} cx={px(a)} cy={py(b)} r={4} fill={LEAF} />)}
      <text x={230} y={144} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>(1,2) (2,4) (3,6)</text>
    </svg>
  );
}

