function DmLeastPreciseWins() {
  return (
    <svg viewBox="0 0 300 130" role="img" className="mx-auto w-full max-w-sm">
      <title>Two measurements, one to the nearest whole unit and one to the nearest tenth, combined by a chain that is only as strong as its weakest link, illustrating that a computed result cannot be more precise than the least precise input.</title>
      <text x={150} y={18} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>a chain is only as precise as its weakest link</text>
      <rect x={20} y={40} width={100} height={34} rx={5} fill={SKY} fillOpacity={0.15} stroke={SKY} strokeWidth={1.4} />
      <text x={70} y={58} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>12 cm</text>
      <text x={70} y={72} textAnchor="middle" fontSize={10} fill={INK} opacity={0.7}>nearest cm</text>
      <rect x={180} y={40} width={100} height={34} rx={5} fill={TANGERINE} fillOpacity={0.12} stroke={TANGERINE} strokeWidth={1.4} />
      <text x={230} y={58} textAnchor="middle" fontSize={11} fontWeight={700} fill={INK}>8.0 cm</text>
      <text x={230} y={72} textAnchor="middle" fontSize={10} fill={INK} opacity={0.7}>written to a tenth</text>
      <text x={150} y={58} textAnchor="middle" fontSize={14} fill={INK}>→</text>
      <text x={150} y={104} textAnchor="middle" fontSize={10} fontWeight={700} fill={LEAF}>the difference is honest to the nearest cm — no better</text>
    </svg>
  );
}

function DmFalsePrecision() {
  return (
    <svg viewBox="0 0 300 120" role="img" className="mx-auto w-full max-w-sm">
      <title>A ruler marked only in whole centimetres next to a claimed reading of 3.14159 centimetres, showing that a tool cannot honestly report more decimal places than it can actually distinguish.</title>
      <rect x={30} y={50} width={200} height={16} fill="none" stroke={INK} strokeWidth={1.3} />
      {Array.from({ length: 11 }).map((_, i) => <line key={i} x1={30 + i * 20} y1={50} x2={30 + i * 20} y2={i % 5 === 0 ? 40 : 46} stroke={INK} strokeWidth={1} />)}
      <text x={30} y={36} fontSize={10} fill={INK}>0</text>
      <text x={230} y={36} fontSize={10} fill={INK}>10 cm</text>
      <text x={150} y={90} textAnchor="middle" fontSize={13} fontWeight={700} fill={TANGERINE}>"3.14159 cm" ?</text>
      <text x={150} y={106} textAnchor="middle" fontSize={10} fill={INK} opacity={0.8}>this ruler can only promise the nearest whole cm</text>
    </svg>
  );
}

